INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18299632789', 'Kit Infantil Piscina De Bolinhas 1,50m Quadrada + 1000 Unidades Bolinhas Coloridas', 'Kit Infantil Piscina De Bolinhas 1,50m Quadrada + 1000 Unidades Bolinhas Coloridas KIT PLAYGROUND – PISCINA DE BOLINHAS + 1000 BOLINHAS! PISCINA DE BOLINHAS QUADRADA 1,50m x 1,50m MEDIDAS (VALORES APROXIMADOS): - Largura: 1,50m - Altura total: 1,70m - Altura da tábua lateral: 30cm ESPECIFICAÇÕES: - Estrutura em aço galvanizado; - Acessórios com proteção UV; - Rede de proteção em polipropileno multicolorida; - Sistema de montagem por encaixe (fácil de montar); - Revestida com isotubos blindados. Acompanha 1000 Bolinhas Coloridas Bolinhas produzidas com materiais de alta resistência e qualidade (proporcionam uma brincadeira alegre e sem riscos), além de atóxico (não prejudicam a saúde da criança e proporcionam maior higiene). Sistema anti quebra (você não perde bolinhas quebradas, e não machuca as crianças). Bolinhas com sistema emborrachado (a bolinha não amassa, você aperta e ela volta na hora). As bolinhas são enviadas em cores sortidas e aleatórias, de acordo com a disponibilidade do estoque. Diâmetro: 71 mm Imagem meramente ilustrativa. - GARANTIA DE FÁBRICA: 90 DIAS! - IMAGEM MERAMENTE ILUSTRATIVA, A COR VARIA DE ACORDO COM DISPONIBILIDADE EM ESTOQUE.', 1165.32, 1165.32, NULL, 'Mom & Baby > Toys > Sports & Outdoor Play', 'https://cf.shopee.com.br/file/sg-11134201-7ra3h-m4p1kg5lkk0134', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F18299632789', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
