INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594211759', 'Vinho Luiz Argenta Vinho Marselan + Tannat Terroir XXVII 2024 Caixa com 6 Un', 'Vinho Fino Tinto Seco Marselan + Tannat Terroir XXVII 2024 – 750ml Caixa com 6 unidades Explore a elegância do blend Marselan (70%) e Tannat (30%) da coleção Terroir XXVII, produzido na Indicação de Procedência Altos Montes, Flores da Cunha – RS. Este vinho reflete a singularidade do terroir da Serra Gaúcha. Características: - Tipo: Vinho Fino Tinto Seco - Teor Alcoólico: 13,2% - Região: I.P Altos Montes – RS - Maturação: 6 meses em barricas de carvalho francês e 6 meses em garrafa - Produção artesanal: colheita manual, seleção rigorosa e vinificação por gravidade - Volume: 750ml Notas de Degustação: - Cor: vermelho rubi intenso - Aroma: frutas vermelhas (cereja, ameixa, mirtilo) com delicadas notas de baunilha - Paladar: médio corpo, acidez equilibrada, boa persistência, retrogosto que confirma o aroma Temperatura ideal: 16°C a 18°C Harmonização: carnes vermelhas leves, massas com molhos condimentados e queijos de média maturação.', 492.0, 393.6, NULL, 'Food & Beverages > Alcoholic Beverages > Wine & Champagne', 'https://cf.shopee.com.br/file/sg-11134201-7rdvz-mbxsxnj7oytq21', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1496505540%2F23594211759', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250972715', 'Ventilador De Coluna Mallory Éolo 6 Pás 126W Preto e Grafite - 110V', 'Ventilador De Coluna Mallory Éolo 6 Pás 126W Preto e Grafite - 110V O Ventilador de Coluna Éolo Mallory é a escolha ideal para quem busca eficiência e conforto com máxima economia. Com 126W de potência e hélice de 6 pás, ele proporciona um fluxo de ar poderoso enquanto mantém silêncio absoluto, tornando-o perfeito para qualquer ambiente, seja em casa ou no escritório. Com a grade em sistema especial TS e eficiência energética A, o ventilador oferece um desempenho de alta qualidade nas 3 velocidades, ajudando a reduzir o consumo de energia e garantindo economia a longo prazo. Entre as funcionalidades que aumentam sua praticidade estão o ajuste de altura, a oscilação horizontal, a inclinação vertical e a grade removível para facilitar a limpeza, tornando o ventilador fácil de manter e ajustar conforme as suas necessidades. Com 490 mm de diâmetro, a linha de ventiladores Mallory garante o maior fluxo de ar do mercado na categoria, sem perder em silêncio e desempenho. Escolha o Ventilador de Coluna Éolo Mallory e desfrute de frescura, economia e praticidade em um único produto. Especificações Técnicas: Marca: Mallory Modelo: Éolo Ref.: B94401702 Voltagem: 110V Potência: 126w Quantidade de Pás: 6 Diâmetro: 490 mm Quantas velocidades: 3 Classificação energética: BBA Fluxo de Ar Baixo (Vazão Nominal (m³/s)): 0,74 Fluxo de Ar Médio (Vazão Nominal (m³/s)): 0,93 Fluxo de Ar Alto (Vazão Nominal (m³/s)): 1,10 Altura: 130cm Altura Máxima: 140cm Largura: 39cm Profundidade: 48cm Peso: 5,7kg Garantia: 12 meses contra de fabricação, de acordo com as normas do fabricante.', 198.9, 198.9, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-82286-mhgp1p4pgpvne8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F58250972715', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
