INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53008240829', 'Conjunto 6 Bowls Stoneware Porto Brasil Orgânico Latte 558ml Cru', 'QUALIDADE E PRATICIDADE! O Conjunto 6 Bowl Orgânico Latte 558ml da Porto Brasil é perfeito para quem busca praticidade e estilo na mesa do dia a dia. Com design moderno e acabamento que remete à beleza da cerâmica artesanal, esses bowls são ideais para servir sopas, cereais, saladas e muito mais. Com capacidade de 558 ml cada, eles combinam tamanho ideal para porções individuais e versatilidade no uso diário. Produzidos com materiais de alta qualidade, garantem durabilidade, resistência e facilidade na limpeza. Além disso, o acabamento em tom latte traz uma cor neutra e elegante que harmoniza facilmente com qualquer estilo de louça e decoração. O Stoneware Porto Brasil é um material cerâmico, produzido com matérias-primas naturais e um processo exclusivo de queima e acabamento manual, garantindo alta qualidade e resistência. Suas peças possuem variações únicas de formas, relevos e cores, destacando a originalidade e autenticidade. ------------------------------------------------- DIMENSÕES E PESO DA EMBALAGEM: Altura: 15,8 cm Largura: 16 cm Comprimento: 31,1 cm Peso: 2,44 kg', 500.0, 269.9, NULL, 'Home & Living > Dinnerware > Bowls', 'https://cf.shopee.com.br/file/sg-11134201-81zwn-mmnb21qjb1mt57', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1404215442%2F53008240829', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
