INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52509476093', 'Suporte dobrável para guitarra com estrutura em A, universal, de ABS, para guitarras acústicas, clássicas, elétricas', 'Dimensões do suporte dobrável para violão: 28 cm de largura x 28 cm de profundidade x 32 cm de altura; quando dobrado: 33 cm de comprimento x 10 cm de largura x 5 cm de altura. Equipado com pés ajustáveis que se adaptam a qualquer espessura, desde ukuleles até violões de tamanho normal. Material de alta qualidade: O suporte para guitarra, leve e resistente, é feito de plástico durável. A superfície é revestida com material resistente ao desgaste, adequado para uso a longo prazo Estrutura em A: A estrutura triangular do suporte para guitarra proporciona maior estabilidade. Equipado com suportes de borracha e encostos para proteger a superfície e a parte inferior da guitarra. Usabilidade: O suporte pode ser dobrado e colocado na horizontal em segundos, com um tamanho compacto que é fácil de guardar e transportar. É extremamente prático para viagens, casa, trabalho e estúdio Multifuncional: Muito adequado para violão e guitarra elétrica, baixo, banjo, bandolim, violino e violão infantil, etc. É uma ótima opção para você apoiar seu instrumento de forma prática e segura', 99.98, 54.99, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Music Accessories', 'https://cf.shopee.com.br/file/br-11134207-820lc-mnh0kg4xvvuq75', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1281436474%2F52509476093', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
