INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52011989274', 'Espelho Lopazzi Com 3 Tonalidades de Led Jateado 170x70cm Para Closet,Hall,Lavabo,Sala de Estar,Quarto,e Salão de Beleza', 'Espelho Lopazzi 170x70cm com LED Jateado – Quente, Neutro ou Frio Transforme seu ambiente com o Espelho Lopazzi 170x70cm, uma peça elegante, moderna e funcional para deixar qualquer espaço mais sofisticado. Com design de corpo inteiro, acabamento premium e LED jateado, ele proporciona iluminação suave e uniforme, ideal para quartos, closets, lojas, salões, banheiros, provadores e ambientes comerciais. Disponível com 3 tonalidades de LED: LED Quente 3000K – iluminação aconchegante e elegante. LED Neutro 4000K – equilíbrio perfeito para o dia a dia. LED Frio 6500K – luz mais clara e intensa, ideal para maior definição. O espelho possui medida de 170x70cm, excelente para visualização de corpo inteiro, trazendo mais amplitude, beleza e praticidade ao ambiente. Destaques do produto: Espelho corpo inteiro 170x70cm LED jateado com acabamento moderno Disponível em luz quente, neutra ou fria Visual sofisticado e decorativo Ideal para uso residencial ou comercial Marca Lopazzi Escolha a tonalidade desejada e deixe seu ambiente mais bonito, iluminado e elegante com a qualidade Lopazzi.', 699.99, 509.9, NULL, 'Home & Living > Decoration > Mirrors', 'https://cf.shopee.com.br/file/sg-11134201-823rq-mpasgfsbedqlbc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1248180593%2F52011989274', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
