INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43851251137', 'Kit 6 Ramequim Porcelana Branco Pequeno Médio ou Grande', 'Kit com 6 Ramequins de Porcelana Terramada – Canelado | 40ml, 135ml ou 250ml Monte sua mesa com elegância e praticidade com o kit de ramequins da Terramada. Produzidos em porcelana de alta qualidade e com acabamento canelado, esses potinhos são ideais para servir porções individuais, entradas, molhos, patês, sobremesas ou o que sua criatividade mandar. Disponíveis em três tamanhos diferentes para atender às suas necessidades: – 40ml: ideal para molhos, temperos e acompanhamentos delicados – 135ml: perfeito para sobremesas, entradinhas e pequenas porções – 250ml: ótimo para porções maiores, como suflês frios, creme brulée servido frio ou porções individuais de salada Apesar de serem resistentes, os ramequins não devem ser levados ao forno, pois não são próprios para altas temperaturas. No entanto, são compatíveis com máquina de lavar louças, facilitando a limpeza no dia a dia. Material: Porcelana Acabamento: Canelado Marca: Terramada Itens inclusos: 6 unidades do tamanho escolhido (40ml, 135ml ou 250ml) Monte seu kit, escolha os tamanhos que combinam com a sua rotina e torne cada refeição mais especial!', 66.99, 51.99, NULL, 'Home & Living > Dinnerware > Bowls', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9voe0bgu33t20', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333246733%2F43851251137', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
