INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22294719560', 'Carrinho com Bebê Conforto Cosco Kids Travel System Reverse Alça Reversível 0-15kg Rosa Rajado', 'O passeio está completo com o conjunto do bebê conforto Wizz e do Carrinho Reverse, com alça reversível, bandeja com porta copos duplo e inclinação total tipo berço. Carrinho: - Alça reversível - 3 posições de inclinação - Inclinação tipo berço - Apoio para os pés com 2 posições de altura - Bandeja frontal removível com porta-copos - Capota retrátil e removível - Amplo cesto de compras - Cinto de segurança de 5 pontos - Cinto ajustável na altura e largura - 2 rodas duplas dianteiras com travas de giro 360° - Freio traseiro interligado - Fechamento tipo envelope Bebê Conforto: - 5 modos de uso: balanço, fixo, carregar e instalar no carro ou carrinho - Acompanha redutor de assento - Protetores acolchoados nos cintos - Cinto de segurança com ajuste de altura e largura Modelos compatíveis: - Base Veicular Wizz, Cosco (Não Incluso) Especificações: - Isofix: Não - Material Carrinho: Ferro; Polipropileno; Poliuretano; Poliéster - Material Bebê conforto: Poliéster, HDPE - Idade Indicada Carrinho: 0 a 15kg - Idade Indicada: 0 a 13kg - Peso Carrinho: 8,5kg - Peso do BBC: 2,5KG - Dimensões Carrinho: 96,5 x 47 x 69 | Fechado: 31 x 85 x 47 - Dimensões BBC: 53,5 x 43 x 64,5 - Garantia: 6 meses + 6 meses* - Conteúdo da embalagem:1 carrinho, 1 bebê conforto, 2 manuais, 1 par de adaptadores *Registre seu produto no site e ganhe 6 meses de garantia estendida. *Todos os produtos possuem Nota Fiscal Eletrônica. *O carrinho é aprovado pelo INMETRO conforme a norma ABNT NBR 14.389 para crianças do nascimento aos 15 kg, e o bebê conforto segue a norma ABNT NBR 14.400, garantindo toda a segurança necessária.', 1199.0, 1199.0, NULL, 'Mom & Baby > Baby Travel Essentials > Strollers & Travel Systems', 'https://cf.shopee.com.br/file/sg-11134201-821ds-mh9jdjeq8rnudf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1207408200%2F22294719560', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22291296337', 'VINHO CASILLERO DEL DIABLO SAUVIGNON BLANC 750ML', 'Este Sauvignon Blanc provém de vários vinhedos localizados nos vales vitivinícolas mais renomados do Chile, que se encontram a poucos quilômetros da costa do Oceano Pacífico, Casablanca, Rapel (costa) y Limarí. Esta proximidade com o mar ajuda a moderar as temperaturas na zona, principalmente no verão, e permite criar um Sauvignon Blanc com uma frescura marcada. Com aromas de Pera, limão, alguns toques tropicais e maçã verde, na boca é Equilíbrio de fruta e acidez, com bom frescor.', 59.9, 59.9, NULL, 'Food & Beverages > Alcoholic Beverages > Wine & Champagne', 'https://cf.shopee.com.br/file/sg-11134201-7qvfh-lh59u2gyxco447', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F661273874%2F22291296337', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42100772100', 'Kit 3 Camisetas Masculinas Dry Fit Academia Tech Treino Corrida Anti-Suor Sortida', 'Camisetas Dry Fit – Conforto e Performance no Seu Dia a Dia! Alta performance e conforto incomparável! A nossa Camiseta Dry Fit foi desenvolvida para quem busca leveza, respirabilidade e estilo em todas as ocasiões. Seja para treinar, trabalhar ou curtir momentos de lazer, você estará sempre seco e confortável. Por que escolher nossas camisetas? Tecido respirável: Tecnologia com micro furos que garantem ventilação máxima, mantendo sua pele sempre fresca. Secagem ultra rápida: Absorve e evapora o suor em minutos, evitando incômodos durante o dia. Anti-odor e antibacteriana: Tecnologia inteligente que combate bactérias causadoras de mau cheiro. Toque leve e macio: Perfeita para atividades físicas ou para o dia a dia sem abrir mão do conforto. Design versátil: Combina com qualquer ocasião, do treino ao casual. CARACTERÍSTICAS: - Produto 100% Brasileiro; - Alta qualidade de fibras; - Fácil encaixe ao corpo; - Tecido leve, arejado e confortável; - Não encolhe; - Alta durabilidade; - Versátil. COMPOSIÇÃO: 100% Poliéster. Cores disponíveis: Preto, Cinza, Vermelho e Azul Marinho. TAMANHOS: P, M, G e GG. Confira a tabela de medidas no anúncio. Peça feita com tecido Dry Fit (malha de poliéster e tecnologia inteligente). Esse tecido proporciona conforto, proteção, durabilidade e praticidade.', 109.9, 109.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > T-shirts', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9q6mxyyvbqx00', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328687466%2F42100772100', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11454320772', 'Kit 5 Cuecas Boxer Algodão c/ Poliéster C5 + 3 Pares de Meias', 'Cueca Boxer C5 é uma ótima cueca masculina de entrada (mais popular) Essas cuecas boxer são confeccionadas em algodão (Cotton) com poliéster e elastano, tecido leve e macio, desenvolvido especialmente para quem não abre mão do conforto e busca preço. Modelagem boxer com formato anatômico que proporciona total aderência, e se adapta perfeitamente ao corpo. Composição: 50% Algodão 45% Poliéster 5% Elastano Tamanhos: P (36-38) M (40-42) G (44-46) GG (48-50) O Kit é enviado de forma sortida, podendo haver repetição de cores. SOBRE A COMPRA MAIS: A Compramais tem como missão desde 2013 proporcionar satisfação e qualidade para clientes em todo o Brasil. Trabalhamos com agilidade para garantir que seu pacote chegue com rapidez em suas mãos, no conforto do seu lar e sem precisar sair de casa! Temos um catálogo extenso de moda íntima que conta com itens femininos, masculinos e infantis. Ainda tem alguma dúvida? Nos faça uma pergunta! Compramais, paixão em moda íntima.', 59.9, 59.9, NULL, 'Men Clothes > Innerwear & Underwear > Underwear', 'https://cf.shopee.com.br/file/sg-11134201-23020-954ughhg9hnv89', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328687466%2F11454320772', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
