INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093202624', 'Jasmine Sou Sweet Maracujá E Chia Zero Açúcar 75G', 'O Sou Sweet é um biscoito preparado com Stevia natural, polpa de frutas e cereais integrais. Rico em micronutrientes, carboidratos complexos e fibras. Sua textura mais rústica, preserva a estrutura dos grãos, e o sabor dos seus ingredientes aparece de maneira mais intensa e marcante. Ingredientes: Farinha de trigo integral, farinha integral reconstituída de trigo, farinha de trigo enriquecida com ferro e ácido fólico, óleos vegetais (milho e/ou girassol e/ou algodão e/ou palma), aveia integral, fibra solúvel, farinha de arroz integral, milho integral em pó, chia em grãos, farinha de maracujá, amido, sal, alfarroba em pó, hortelã em pó, chá verde em pó, edulcorantes naturais maltitol e glicosídeo de esteviol, aromas, emulsificante natural lecitina de soja, fermentos bicarbonato de sódio, bicarbonato de amônio e fosfato monocálcico, acidulante ácido cítrico e antioxidante natural tocoferol. ALÉRGICOS: CONTÉM AVEIA, DERIVADOS DE TRIGO E DE SOJA. PODE CONTER CENTEIO, CEVADA, AMENDOIM, AMÊNDOA, AVELÃ, CASTANHA-DE-CAJU, CASTANHA-DO-PARÁ, MACADÂMIA, NOZ, PECÃ, PISTACHE, PINOLI E CASTANHAS. CONTÉM GLÚTEN. O GLÚTEN É PREJUDICIAL À SAÚDE DOS DOENTES CELÍACOS.', 8.0, 8.0, NULL, 'Food & Beverages > Snacks > Biscuits, Cookies & Wafers', 'https://cf.shopee.com.br/file/sg-11134201-7rdvj-lycleqjzoume2c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F590473480%2F22093202624', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
