INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14486893315', 'Camisa Sublimada Proteção Solar UV Preto Blue Com Capuz - Mar Negro', 'Camisa Sublimada com Capuz Proteção Solar UV Blue - Mar Negro A Camisa Sublimada com Capuz Proteção Solar UV Blue da Mar Negro é a escolha perfeita para quem busca máxima proteção e conforto durante atividades ao ar livre. Desenvolvida com tecnologia UV 50+, ela bloqueia até 98% dos raios solares nocivos, protegendo a pele contra queimaduras e envelhecimento precoce. Seu diferencial exclusivo está no sistema inovador de capuz cruzado, que oferece uma proteção 360° para rosto, pescoço e mãos. Esse design ergonômico garante um ajuste perfeito, evitando a exposição ao sol e proporcionando mais segurança para pescadores, aventureiros e esportistas. O tecido sublimado da camisa é altamente respirável e leve, permitindo maior ventilação e conforto térmico mesmo nos dias mais quentes. Além disso, sua secagem rápida reduz o acúmulo de suor, evitando odores e proporcionando uma experiência agradável durante todo o uso. Com um design moderno e estiloso, a Camisa UV Mar Negro se destaca não apenas pela funcionalidade, mas também pelo visual sofisticado. O acabamento de alta qualidade e a durabilidade do tecido garantem que a peça se mantenha impecável por muito mais tempo. Seja para pesca, trilhas, ciclismo ou qualquer outra atividade ao ar livre, essa camisa é indispensável para quem valoriza proteção, conforto e estilo em um único produto. Especificações: Marca: Mar Negro Modelo: Sublimada com Capuz Proteção UV: 50+ (bloqueia até 98% dos raios solares) Sistema de capuz: Capuz cruzado com proteção 360° Tecido: Leve, respirável e de secagem rápida', 129.9, 129.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > T-shirts', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6rb048rarev36', 'https://