INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10414004140', 'Livro - Diário de um nerd - Livro 1', 'Phil, o nerd, é um garoto de 12 anos muito inteligente que adora estar com os amigos. Ele e sua turma precisam se preparar para competir nas Olimpíadas de Matemática e Ciências. Mas, para tentar conquistar a garota dos seus sonhos, Phil começa a viver uma vida secreta de campeão esportista. Em meio a todas as mentiras, será que Phil conseguirá conciliar as duas realidades?_x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 2, 2019_x000D_ Autor: Philip Osbourne _x000D_ Idioma: Português_x000D_ Páginas: 160_x000D_ Dimensões: L 13.50 x A 20.20 x E 0.90_x000D_ ISBN: 9788538091660', 24.9, 24.9, NULL, 'Books & Magazines > Books > Others', 'https://cf.shopee.com.br/file/sg-11134201-23010-zh7hefp6xtlvfe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F10414004140', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54950113711', 'Livro Colorir Cute Capybaras - Livro de colorir com 4 marcadores', 'Inspirado no fenômeno dos livros de colorir para relaxamento do TikTok,o livro CUTE CAPYBARAS é perfeito para quem ama transformar momentos simples em uma verdadeira experiência calmante. Impressas em papel de alta gramatura, para garantir a melhor qualidade de pintura, as 48 páginas com 23 ilustrações exclusivas e uma página para você testar cores e texturas retratam momentos cotidianos e aconchegantes, permitindo que você explore sua criatividade ao máximo, seja colorindo com lápis de cor ou marcadores. Livre para todos os públicos, este livro é perfeito para aliviar o estresse e se desconectar da correria do dia a dia. E ainda acompanha 4 canetinhas. Editora: Ciranda Cultural Edição: 1, 2025 Autor: Ciranda Cultural Idioma: Português Páginas: 48 Dimensões: L 24.00 x A 24.00 x E 0.50 ISBN: 9786526127612 Coleção: Comfy & cozy books (livro com 4 canetas) Linha Editorial: Ciranda Cultural - Lab Faixa Etária: + 4 anos Assuntos (tags): Relaxar, Arteterapia, Colorir, Diversão, Pintar, Pintura, Capybaras, Cozy, comfy, Livro de colorir, livro de colorir + marcador, Personagens, Criatividade, Criança, Adulto, Infantil, Infância, Atividades, Ciranda Cultural BISAC: Jogos e Atividades / Jogos e Atividades / Livros de Colorir Linha de Produto: Comfy and cozy books Encadernação: Lombada quadrada Acabamento: Verniz UV localizado Material: Papel', 24.9, 11.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-8259m-mg8cpoaa991k95', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F54950113711', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
