INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23121492033', 'Colônia Pet Cachorro Gato Hydra Groomers Forever Candy 450mL Refil', 'Versão econômica. Destinada ao uso profissional, a Colônia Pet Society Hydra Groomers Forever Candy é para pets que querem ficar perfumados por mais tempo. Com alta concentração de fragrância, possui longa duração e fixa duas vezes mais. Uso profissional. Fragrância Floral Frutal, com notas bergamota, jasmim, violeta e cedro. Modo de Uso: Após a secagem, aplicar a Colônia Pet Society Hydra Groomers Forever Candy por toda a pelagem. Frasco: 450mL (Refil).', 213.9, 192.51, NULL, 'Pets > Pet Grooming > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m85928pw425t3a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F688030691%2F23121492033', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
