INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22394086846', 'Chinelo Slide Infantil Grendene Kids Angel Disney Mania Plus', 'Nossa gáspea super clássica apresenta um conceito exclusivo, com artes delicadas e linhas suaves, pensadas para encantar as crianças. Além disso, possui um enfeite encantador, inspirado na identidade mágica do universo Disney, com os personagens que as pequenas adoram: Stitch, Angel e Minnie. São diversas opções para as meninas arrasarem nos looks.', 41.99, 41.99, NULL, 'Baby & Kids Fashion > Girl Shoes > Flip Flops', 'https://cf.shopee.com.br/file/sg-11134201-7rauo-mamsi3y2ppx214', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1012616199%2F22394086846', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10854927700', 'Película Nano Gel Dupla para Galaxy S8 Plus – Gorila Shield (Cobre toda tela)', 'A Película Nano Gel Dupla da Gorila Shield garante proteção extra para a tela do seu aparelho. Produzida com a tecnologia hidro nano pet, a película da Gorila Shield se adapta as extremidades curvadas do aparelho, cobrindo toda extremidade do visor. Além disso com a película dupla Nano Gel você conta com uma película reserva para reposição em casos de eventuais acidentes ou erros na instalação.', 11.53, 11.53, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/ba7fd58af045611b874de4d349b5b151', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F10854927700', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093900432', 'Minecraft Vanilla Armas De Batalha Picareta - Mattel Hff59', 'Jogue aventuras do Minecraft no mundo real com estes acessórios de brinquedo de batalha em tamanho real! Os fãs vão adorar recriar seus momentos favoritos do jogo ou inventar histórias emocionantes com peças icônicas de dramatização. Além disso, esses papéis Os acessórios de batalha cabem perfeitamente na mão de uma criança e são autênticos ao design pixelado exclusivo do Minecraft! Especificações: Marca: Mattel Referência: HFF59', 189.9, 149.0, NULL, 'Mom & Baby > Toys > Pretend Play', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8nj5zvrrqbm2d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F567914216%2F23093900432', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19897679074', 'Mesa para Sala de Jantar 120x90cm com Vidro Lapidado Off White/Tabaco Tabaco/Off White', 'A Mesa de Jantar 120cmx90cm Móveis Zamarchi é a escolha ideal para quem busca otimizar o espaço da sala de jantar com elegância e funcionalidade. Com um design moderno e tampo em vidro, ela se torna o ponto central de confraternizações, agregando sofisticação ao ambiente. • Estética Contemporânea: Apresenta acabamento em tons de tabaco e off white que harmonizam facilmente com diversos estilos de decoração, proporcionando um toque de modernidade e leveza visual ao cômodo. • Dimensões e Capacidade: Conta com 120 cm de largura, 90 cm de profundidade e 82 cm de altura, dimensões planejadas para acomodar confortavelmente até 4 pessoas em refeições diárias ou reuniões sociais. • Qualidade e Resistência: O tampo possui espessura de 29 mm, combinando a robustez do MDF com a sofisticação do vidro lapidado, apresentando alta durabilidade e uma superfície fácil de higienizar no dia a dia. • Estrutura e Estabilidade: Desenvolvida com painéis de alta densidade estrutural, a mesa oferece uma base firme e segura que suporta até 100 kg, apresentando a rigidez necessária para evitar balanços e proporcionar total conforto durante o uso. • Acabamento Superior: Recebe pintura UV semi-brilho que protege o móvel contra umidade e riscos, mantendo o brilho e a integridade das cores por muito mais tempo, mesmo com o uso frequente. Acompanha 1 mesa, kit de ferragens e manual de montagem. (Aviso: Mesa avulsa, não acompanha cadeiras). Para uma compra certeira: Os itens decorativos das imagens não fazem parte do produto. Confirme se as medidas cabem no seu ambiente, considerando uma pequena folga de até 2 cm para manuseio. Estilo: Moderno Formato: Retangular Peso (kg): 38 Dobrável: Não Garantia: 03 Meses Altura (cm): 82 Acabamento: Pintura UV Extensível: Não Largura (cm): 120 Cor do Tampo: Off White Possui Vidro: Sim Possui Rodízio: Não Suporta Até (kg): 100 Profundidade (cm): 90 Escala de Brilho: Semi-Brilho Material da Base: MDP Material do Tampo: Vidro/MDF Origem do Produto: Nacional Acabamento da Base: Pintura UV Ambiente Principal: Sala de Jantar Espessura do Tampo (mm): 29 Material Principal: MDP Necessita Montagem: Sim Acabamento do Tampo: Pintura UV Quantidade de Lugares: 4 Complexidade da Montagem: Média: pode ser montado por mais de uma pessoa e/ou necessite de maior conhecimento para montagem Possui Suporte Giratório: Não Informações Complementares (Novo): Mesa para sala de jantar com vidro lapidado preto, serve para 4 cadeiras Marca: Móveis Zamarchi Cor: Tabaco/Off White Cor do Produto: Tabaco/Off White Itens Inclusos: 1 Mesa, Kit Ferragens e Manual de Montagem Cor Predominante: Off White Linha ou Coleção: 2022 Medida da Base (A x L x P): 75x67x41 Medida do Tampo (L x C x E): 120x90x2,9CM', 570.64, 494.38, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-8259w-mqizf09r6dc275', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F19897679074', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
