INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18699768653', 'Esmerilhadeira 920w Com 6 Discos G720X 6 Discos Black & Decker', 'Esmerilhadeira 920w Com 6 Discos G720X6D Black & Decker ATENÇÃO : ESCOLHA A VOLTAGEM NA VARIAÇÃO Reconhecida mundialmente por desenvolver soluções que facilitam a vida das pessoas, a BLACK+DECKER anuncia o lançamento da Esmerilhadeira G720X. Leve e compacta, a ferramenta é ideal para aqueles que realizam pequenos trabalhos de serralheria no dia a dia. Perfeita para realizar corte, polimento, lixamento, desbaste e acabamento em peças de aço ou outras estruturas metálicas. A G720X oferece motor 22% mais compacto e 16% mais potente que o do modelo anterior. Por isso, é indicada para quem atua com pequenos serviços de serralheria. A nova esmerilhadeira chega ao mercado no formato 4–½ (115mm) e com potência de 920W. Alguns de seus principais diferenciais são a resistência contra entrada de pó em seu interruptor e a ergonomia, já que conta com empunhadura em 3 posições. Além disso, tem botão de travamento para troca de disco. Características Adicionais Maior durabilidade Interruptor selado contra entrada de pó; Ergonômica Empunhadura com 3 posições; Conforto e conveniência ajuste da guarda de proteção sem chave; Maior durabilidade Caixa de engrenagens metálica; Mais praticidade com o botão de travamento do eixo para troca de disco. Dimensões do Produto Comprimento: 32,51 cm; Largura: 13,21 cm; Altura: 11,43 cm; Peso: 1,9 kg. Perguntas Frequentes: O produto é original? Sim, pirataria é crime e deve ser denunciado à Shopee. Acompanha Nota Fiscal? Sim. O produto tem a garantia legal do fabricante? Sim. Consulte o campo garantia do anúncio. Estoque limitado – Garanta já o seu! Compre agora e aproveite nossas promoções especiais!', 385.0, 277.2, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mc2fooo453fr11', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1042011939%2F18699768653', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193094833', 'ATAQUE DOS TITÃS VOL. 12 MANGÁ SHINGEKI NO KYOJIN', 'ATAQUE DOS TITÃS VOL. 12 MANGÁ SHINGEKI NO KYOJIN ATAQUE DOS TITÃS VOL. 12 MANGÁ SHINGEKI NO KYOJIN. A trama alcança novos patamares de tensão e revelações. Eren e seus companheiros enfrentam batalhas decisivas enquanto segredos sobre os titãs começam a vir à tona, mudando completamente a compreensão do mundo em que vivem. Com ação intensa, suspense e reviravoltas marcantes, este volume é essencial para quem acompanha a série original e deseja mergulhar ainda mais nesse universo sombrio e impactante. Informações Adicionais Autor: ISAYAMA, HAJIME Data Publicação: 30/12/1899 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: ATAQUE DOS TITÃS VOL. 12 SÉRIE ORIGINAL Idioma: INDEFINIDO Páginas: 192 Edição: 2 ISBN-13: 9786559607938 ISBN-10: 6559607933', 48.28, 37.7, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-7rdvo-mdop8crri9zt2d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F23193094833', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58263171197', 'Ração Úmida GranPlus Sache Gato Adulto Atum 85g - KIT 10 unids.', 'GranPlus Sachê Atum: O Sabor do Mar com Nutrição de Alta PerformanceO Sachê GranPlus Gatos Adultos sabor Atum é a solução ideal para proporcionar uma refeição suculenta, saudável e completa ao seu gato. Formulado com ingredientes nobres e cozido no vapor, este sachê combina o irresistível sabor do peixe com nutrientes essenciais que garantem mais vitalidade e saúde para o dia a dia do seu pet. Benefícios que Fazem a DiferençaProteína Nobre de Atum: Oferece um sabor intenso e natural que atrai até os gatos mais exigentes, garantindo a manutenção da massa muscular. Saúde Renal e Urinária: Com alto índice de umidade, auxilia na ingestão indireta de água, fundamental para prevenir cálculos e manter o sistema urinário saudável. Pelagem Brilhante: Rico em ácidos graxos essenciais (Ômegas) provenientes do peixe, que atuam diretamente na saúde da pele e no brilho dos pelos. Digestão Equilibrada: Ingredientes de alta absorção que favorecem o bom funcionamento do intestino e resultam em fezes com menor volume e odor. Receita Natural: Sem corantes e sem aromas artificiais, oferecendo uma alimentação segura e equilibrada. kit com 10 unidades', 30.35, 30.35, NULL, 'Pets > Pet Food > Cat Treats', 'https://cf.shopee.com.br/file/sg-11134201-824je-mpvlgdobfci55f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1738906516%2F58263171197', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
