INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43366172650', 'Primer Facial Ruby Rose Soft Skin Hbm1700', 'Descrição: Desfrute de uma pele perfeitamente suavizada e iluminada com o Primer Soft Skin! Sua textura leve e macia proporciona um toque aveludado, minimizando a aparência dos poros e suavizando linhas finas. Com um leve tom rosado que ilumina a pele, o Soft Skin cria um efeito blur, garantindo uma superfície suave e radiante para a aplicação da maquiagem. Ideal para preparar a pele para um acabamento impecável, este primer auxilia na fixação da maquiagem, sem deixar um aspecto opaco. MODO DE USAR: Aplique uma pequena quantidade e espalhe pelo rosto onde há necessidade uniformizar a pele e minimizar poros abertos. Use antes da maquiagem. USO EXTERNO. MANTENHA FORA DO ALCANCE DAS CRIANÇAS. Conteúdo da embalagem: 20g. #Imagem ilustrativa. Cor do produto poderá variar dependendo da configuração do monitor ou celular.', 24.99, 24.99, NULL, 'Beauty > Makeup > Face', 'https://cf.shopee.com.br/file/sg-11134201-824ik-me1jcpcioiyo54', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322432427%2F43366172650', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
