INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22094992866', '3 Corações Dark Roast Gourmet Café Torrado e Moído', 'Desfrute do sabor intenso e aroma marcante do Café Torrado e Moído 3 Corações Gourmet Dark Roast. Ideal para apreciadores de café forte, este café 100% Arábica proporciona uma experiência única a cada xícara. Prepare seu café perfeito: * Aqueça 500ml de água mineral ou filtrada sem deixar ferver. * Adicione 3 colheres de sopa cheias (aproximadamente 40g de pó) no coador ou filtro. * Despeje a água lentamente, em movimentos circulares, garantindo que todo o pó seja molhado. * Consuma imediatamente ou guarde numa garrafa térmica por, no máximo, 1 hora. Notas de prova: * Aroma: adocicado * Sabor: chocolate amargo * Bebida: mole * Corpo: encorpado * Moagem: fina * Doçura: média alta', 33.99, 25.99, NULL, 'Food & Beverages > Beverages > Coffee', 'https://cf.shopee.com.br/file/sg-11134201-825bc-mqnem45vkhe377', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555116%2F22094992866', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
