INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11091747259', 'Tomada Usb Veicular Carregador Celular Tablet Gps Roadstar RS-108 3U BR Bivolt', 'Mais tempo de bateria para o celular A tomada USB RS-1083UBR foi desenvolvida especialmente para facilitar na hora de recarregar seu celular, ou tablets, no carro. Indicado principalmente para quem precisa ficar conectado por muito mais tempo com o celular. Fácil instalação. A tomada USB é de fácil instalação e substitui o acendedor original do carro, facilitando muito mais na hora de recarregar o celular, sem a necessidade de carregadores externos. Conta com tampa emborrachada para maior proteção das portas USB. Proteção de curto-circuito / superaquecimento. Produto multifuncional, perfeito para uso em viagens. O material impermeável à prova de poeira pode ser usado para a aplicação interior e exterior. Pode ser instalado verticalmente, horizontalmente ou debaixo do traço, ou qualquer superfície plana. Amplamente utilizado com equipamentos elétricos para alimentação: Veículo, GPS, telefone celular, câmera, mp3. Carregamento rápido a toda velocidade. Compatível com todos os telefones celulares de carregamento USB ou outros produtos eletrônicos. Carregue vários acessórios ao mesmo tempo, muito conveniente e fácil de usar. Especificação: Cor preta. Material: ABS. Dimensões Aproximadas: AxLxC 3,8 x 2,8 x 5 cm. Entrada: DC 12V / 24V. Saída: DC 5V 3.1A (2.1A + 1A). Indicador: LED azul. Acompanha terminais de instalação.', 49.0, 49.0, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Phone Chargers & Holders', 'https://cf.shopee.com.br/file/2fa0f0d2e0c9d3b9cf9eb67e84c7b7e3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F288347041%2F11091747259', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
