INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22493557978', 'Bicicleta Aro 20 Max Boy Colli', 'Ideal para fazer passeios a qualquer hora com os amigos ou familiares e também para a prática de atividades esportivas. A Bicicleta Colli Max Boy possui Aro 20 Aero, 36 Raias, Freios V-Brake Dianteiro e Traseiro, Suporte de Guidão Down Hill. Características: Certificado Inmetro: 09282-01/2021 Quadro completo aro 20 Guidão down hill Garfo em aço carbono aro 20 maçaneta de freio em nylon Movimento direção 22,2m Suporte de guidão em aço down hill Freio V-BRAKE dianteiro e traseiro manoplas de borracha Pedivela braço 40 dentes Selim PVC Movimento central 45mm Pneus 20 Corrente grossa tec 1/2 x 1/8 pedal rosca fina 1/2 com refletor Roda livre 18 dentes Descanso lateral Aro 20 com 36 furos Dimensões: Altura: 82 cm Largura: 61 cm Profundidade: 130 cm Peso: 13,4 kg Garantia do fornecedor de 3 meses.', 749.9, 659.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-7rfg3-m33ipkylizhu78', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1329429906%2F22493557978', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
