INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21296859064', 'Ração GranPlus Gatos Adultos Sabor Frango e Arroz 3kg', 'Ração GranPlus Gatos Adultos Frango e Arroz 3kg - Indicada para gatos;- Com ingredientes nobres cuidadosamente selecionados;- Auxilia na saúde do trato urinário;- Fonte rica em ômega 3, (EPA & DHA), nutrientes essenciais;- Ótimo equilíbrio intestinal;- Com polpa de beterraba e prebiótico MOS. A Ração GranPlus Gatos Adultos Frango e Arroz é um alimento High Premium de alta qualidade, que proporciona uma experiência irresistível para seu gato enquanto o nutre com ingredientes nobres e funcionais que trazem benefícios para sua saúde. Os ingredientes contidos em sua formula, foram introduzidos por especialista e veterinários tornando assim um alimento rica em vitaminas. Ingredientes Carne Mecanicamente Separada de Frango, Fígado de Frango, Farinha de Vísceras de Aves, Farinha de Torresmo, Quirera de Arroz, Grão de Milho1, Grão de Sorgo, Feijão Bandinha2, Óleo de Aves, Farelo de Glúten de Milho-601, Levedura Seca de Cervejaria, Óleo de Peixe Refinado, Óleo de Linhaça, Polpa Desidratada de Beterraba, Farelo de Trigo, Cloreto de Sódio (Sal Comum), Carbonato de Cálcio, Cloreto de Potássio, Taurina, L-Lisina, DL-Metionina, Hidrolisado de Fígado de Aves e Suínos, Antioxidantes (BHA, BHT), Propionato de Cálcio, Sorbato de Potássio, Aditivo Prebiótico (Parede Celular de Levedura Fonte de Mananoligossacarídeos), Aditivo Acidificante (Ácido Fosfórico), Aditivo Adsorvente (Parede Celular de Levedura e Bentonita), Vitaminas (A, D3, E, K3, B1, B2, B6, B12, Pantotenato de Cálcio, Ácido Fólico, Ácido Nicotínico, Biotina, Cloreto de Colina), Minerais (Sulfato de Zinco, Sulfato de Ferro, Sulfato de Manganês, Iodato de Cálcio, Selenito de Sódio), Minerais Quelatados (Proteinato de Manganês, Levedura Enriquecida com Selênio, Proteinato de Zinco, Proteinato de Cobre).', 61.9, 61.9, NULL, 'Pets > Pet Food > Cat Food', 'https://cf.shopee.com.br/file/sg-11134201-7qvcz-lfsq6u4cke852f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F398944029%2F21296859064', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
