INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49310193252', 'Jogo de Tabuleiro Super Compras Pais e Filhos - 793823-1', 'O Jogo Super Compras da Pais e Filhos transforma a experiência de ir às compras em uma brincadeira divertida e educativa. Cada jogador recebe um carrinho e uma lista de compras, e deve percorrer o tabuleiro em busca dos itens corretos, tomando decisões estratégicas ao longo do caminho. As cartas são distribuídas nos locais correspondentes do tabuleiro, e os participantes iniciam a partida posicionando seus peões na saída da casa. A partir daí, vence quem conseguir completar sua lista com mais atenção e estratégia. Além da diversão, o jogo estimula habilidades importantes como memória, concentração, organização e raciocínio lógico, sendo ideal para o desenvolvimento infantil. Características: Marca: Pais e Filhos Modelo: 793823 Tipo: Jogo de tabuleiro educativo Estimula atenção, memória e raciocínio estratégico Incentiva organização e tomada de decisão Ideal para crianças e uso em grupo Especificações: Idade recomendada: a partir de 4 anos Dimensões da embalagem: 32 x 25 x 5,5 cm Peso: 0,415 kg Conteúdo da embalagem: Tabuleiro Cartas de compras Peões Carrinhos Lista de compras Características: - Marca: Pais e Filhos - Modelo: 793823-1 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - 1x Jogo de Tabuleiro Super Compras Pais e Filhos', 52.13, 46.92, NULL, 'Mom & Baby > Toys > Others', 'https://cf.shopee.com.br/file/sg-11134201-820nn-mnzsnah1pfk0a8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F49310193252', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
