INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40025544135', 'Caneta Marca Texto Neon Fever Display com 24 Unidades Jocar Office Leonora - 96140', 'Realce seus documentos e anotações de forma prática e elegante com o Marca Texto Jocar Office. Com cores suaves e delicadas, este conjunto de marca-textos é ideal para uso em escritórios, escolas e em casa, proporcionando uma experiência de escrita suave e sem borrões. Adquira já o Marca Texto Jocar Office e tenha a certeza de estar adquirindo um produto de qualidade para suas necessidades de escrita. Características: - Marca:Leonora - Modelo:96140 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - Marca Texto Neon Fever Display C/24 Unidades Jocar Office', 99.05, 89.15, NULL, 'Stationery > Writing & Correction > Highlighters', 'https://cf.shopee.com.br/file/sg-11134201-8259x-mg58aj0x7uo9c9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F40025544135', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18098073124', 'Cartões de Estímulos de Alto Contraste Montessori Baby Cards 3-6 Meses Cooper Fun - 00166', 'Esse é um daqueles jogos que além de garantir a diversão garante também o aprendizado! O jogo de Contrastes é super divertido e colorido, são 20 cartas todas com uma linda ilustração.Objetivo do jogo além de promover diversão, e desenvolver o raciocínio lógico das crianças e sua percepção visual, o conhecimento das cores e formas. Um jogo de ótima qualidade e todas as suas peças são fáceis de destacar, garantindo muita diversão. Com 1 ano, as ilustrações oferecem texturas, traços mais detalhados e uma expressão ou onomatopéia. Os cartões podem ser usados como roteiro para uma história. Desenvolve: - Percepção Visual - Percepção Auditiva - Conhecimento Específico - Atenção e Foco Especificações: - Idade: 3-6 meses - Dimensão: 4 x 12,8 x 12,8cm - Peso: 0.2kg Características: - Marca: COOPER FUN - Modelo: 00166 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - Montessori Baby Cards 3-6 meses c/ 20 Cartas (Todas Ilustradas) montessori - montessori baby cards - baby cards - jogos educativos', 36.0, 36.0, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rdyo-m1ivqehhfiwmd2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F18098073124', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200677663', 'Chave De Fenda 18" X 6" Bornes Gedore', 'Chave De Fenda 18" X 6" Bornes Gedore - 035.910 Haste fabricada em aço Gedore-Vanadium e cabo em polímero na cor azul padrão Gedore. A Haste possui acabamento niquelado e cromado, com ponta escurecida e cabo ergonômico. É uma chave com haste redonda e resistente, com perfil de encaixe para parafusos tipo fenda simples. Largura da ponta é igual ao diâmetro da haste, possibilitando o uso em bornes (terminais) na linha elétrica e eletrônica. Medida: 18 x 6" Comprimento Total: 230mm Peso: 0,024kg Imagens Meramente Ilustrativas', 25.56, 25.56, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-821fk-mh65qngistu5ce', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1096473040%2F58200677663', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
