INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18298304727', 'Mala de Viagem Bordo Katerini ABS Expansiva Rodas 360 Up4you', 'A Mala de Viagem Bordo Katerini Expansiva ABS Up4you com Rodas 360 é perfeita para quem busca praticidade, segurança e resistência em viagens nacionais e internacionais. Produzida em ABS resistente, oferece maior durabilidade e proteção contra impactos durante o transporte. Seu acabamento fosco na cor verde militar traz visual moderno, sofisticado e elegante para diferentes estilos de viagem. O modelo conta com sistema expansivo, proporcionando aumento de espaço interno para acomodar roupas, acessórios e objetos com mais praticidade durante a viagem. Possui 4 rodas duplas com giro 360°, garantindo deslocamento leve, silencioso e maior estabilidade em aeroportos, rodoviárias e hotéis. Conta com cadeado integrado com segredo, ideal para oferecer mais segurança aos pertences e praticidade em viagens internacionais. Seu carrinho embutido com regulagem de altura proporciona mais conforto durante o transporte, além de possuir alça superior reforçada para facilitar o manuseio. O interior possui forro interno personalizado, divisória com fechamento em zíper, bolso interno organizador em tela e cinta elástica com trava para melhor organização dos itens. O modelo ainda apresenta detalhes premium, como acabamento refinado, estrutura reforçada e rodas com design exclusivo Up4you. Mala de Viagem Média Expansiva ABS Up4you Modelo: MF10379UP-20 Dimensões: Altura: 56 x Largura: 36 x Comprimento: 23 cm Peso: 2,9 kg Capacidade: Média Classificação: Viagem Média Material: ABS Expansiva Rodas Duplas com Giro 360° Cadeado com Segredo Carrinho Embutido com Regulagem Alça Superior Reforçada Forro Interno Personalizado Divisória Interna com Zíper Bolso Organizador Interno Cinta Elástica Organizadora Logo Up4you nas Rodas e Puxadores Dicas de uso: ideal para viagens médias, viagens corporativas, férias e passeios Dicas de limpeza: limpar com pano úmido e sabão neutro. Evitar produtos abrasivos para preservar o acabamento do material.', 309.3, 309.3, NULL, 'Travel & Luggage > Travel Bags > Others', 'https://cf.shopee.com.br/file/sg-11134201-8259s-mqs5jzs0cv0g46', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1251967897%2F18298304727', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
