INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693939954', 'Junta do coletor de admissão Sup Chevrolet Astra 1999 a 2005', 'Descrição: A Junta do coletor de admissão SABÓ 84000 é uma peça que serve na posição Superior dos veículos CHEVROLET ASTRA, VECTRA. Confira abaixo as especificações e aplicações detalhadas. Atenção: EMBALAGEM COM 1 UNIDADE Especificações Técnicas: - Informações adicionais: CHAPA DE AÇO - Posição: SUPERIOR Aplicação: - CHEVROLET ASTRA 2.0 16V 2.0 L 16V DOHC L4 1999 a 2005; - CHEVROLET ASTRA 2.0 16V MPFI 2.0 L 16V DOHC L4 2001 a 2004; - CHEVROLET ASTRA GLS SFI 16V 2.0 L 16V DOHC L4 1999 a 2005; - CHEVROLET VECTRA CD 2.0 L 16V DOHC L4 1996 a 1997; - CHEVROLET VECTRA CD 2.2 2.2 L 16V DOHC L4 1997 a 2005; - CHEVROLET VECTRA ELEGANCE 2.2 L 16V DOHC L4 1997 a 2005; - CHEVROLET VECTRA GLS 2.2 L 16V DOHC L4 1997 a 2005; Sobre o Peça Aí: Com o Peça Aí, você acha a peça certa para cada carro e compra num só lugar. É o maior estoque digital de peças do país! São mais de 100 mil itens originais e de reposição à sua disposição. Importante: • Dúvidas: Caso tenha qualquer dúvida sobre as aplicações do produto, entre em contato conosco. • Instalação Profissional: Recomendamos que a instalação do produto seja realizada por profissionais especializados. • Responsabilidade: Não nos responsabilizamos por montagens mal realizadas e equívocos de instalação." • Produto novo, original e com nota fiscal.', 64.22, 64.22, NULL, 'Spare Parts and Accessories for Vehicles > Others', 'https://cf.shopee.com.br/file/sg-11134201-82623-mkrhzt5cj85he2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1343288194%2F23693939954', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54706830721', 'Berloque de Prata 925 Coração Liso', 'Berloque de Prata 925 Coração Liso: Simplicidade e Elegância O Berloque de Prata 925 Coração Liso é uma peça delicada e elegante, ideal para quem busca um design minimalista com um toque de sofisticação. O coração liso simboliza o amor puro e verdadeiro, sendo perfeito para expressar sentimentos profundos. Feito com Prata 925, este berloque é resistente, durável e garante brilho duradouro. Especificações do Berloque Tamanho: 7mm Peso: 0,85g Material: Prata 925 Destaques do Berloque Design simples e elegante com o símbolo do coração, representando o amor. Feito com Prata 925, garantindo durabilidade, brilho e resistência. Ideal para ser adicionado a pulseiras, proporcionando um toque de sofisticação e sentimento. Elegância e Sentimento em Uma Peça O Berloque de Prata 925 Coração Liso é a escolha perfeita para quem deseja expressar sentimentos de amor de forma elegante e sofisticada. Uma peça delicada que pode ser combinada com outros acessórios para criar um visual cheio de significado. Cuidados com o Produto Evite o contato com produtos químicos para preservar o brilho da prata. Guarde em local seco e seguro para evitar arranhões e oxidação. Limpe regularmente com uma flanela macia para manter a beleza e o brilho da peça. Simplicidade e Sofisticação em Uma Peça Adicione o Berloque de Prata 925 Coração Liso à sua coleção e leve consigo uma peça cheia de amor e sofisticação. Uma escolha ideal para quem deseja expressar seus sentimentos com estilo e delicadeza.', 90.0, 55.0, NULL, 'Fashion Accessories > Additional Accessories > Charms, Pendants & Ornaments', 'https://cf.shopee.com.br/file/br-11134207-820mf-mlgr8dhyql8m09', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F54706830721', 