INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18722844454', 'Óleo de Girassol Ozonizado Grandha Fitozon F3 Cuidado Facial e Dermorreparação', 'CUIDADO FACIAL E DERMORREPARAÇÃO Fitozon F3 é uma sinergia projetada para os cuidados faciais com notável capacidade de firmar a pele e prevenir o surgimento de acne. Promove o clareamento de manchas e repara pequenas lesões e imperfeições da pele. Óleo de Girassol Ozonizado Óleo Vegetal Preservado de Avelã Óleo Vegetal Preservado de Rosa Mosqueta Óleo Essencial de Palmarosa Óleo Essencial de Lavanda Óleo Essencial de Anis Estrelado Ideal para: REPARAÇÃO TECIDUAL PROTOCOLOS FACIAIS E CORPORAIS ENRIJECIMENTO DA PELE PREVENÇÃO DE ACNE CLAREAMENTO DA PELE CORREÇÃO DE PEQUENAS IMPERFEIÇÕES DA PELE TRATAMENTO ANTI-AGE AUXILIAR PROTOCOLOS DE TRATAMENTO DE FERIDAS MODO DE USO Aplicar sobre o rosto com movimentos delicados até sua total absorção. Indicado para os cuidados faciais. Não enxaguar. CONTRAINDICAÇÕES Não usar em gestantes, pessoas com hipertiroidismo, anemia severa ou hemorragia ativa. SOBRE A LINHA FITOZON A linha Fitozon de Alkymia di Grandha contempla a aplicação do ozônio medicinal em óleos fixos, integrando o melhor da engenharia cosmética e da tecnologia de processos industriais para cumprir o "Protocolo de Madri", documento base internacional que estabelece as condições de eficácia e segurança para uso e aplicação deste recurso. Estas preparações são associadas a outros óleos essenciais com seus benefícios extraordinários para fins específicos. A linha Fitozon de Alkymia di Grandha apresenta uma nova tendência em aromaterapia de alto desempenho, com foco nos cuidados e protocolos de saúde integrativa, beleza e bem-estar. 100% NATURAL 100% VEGANO AROMATERAPIA DE ALTO DESEMPENHO DERMOCOSMÉTICO DE USO TERAPÊUTICO COSMECÊUTICO ASSOCIADO À TECNOLOGIA DO OZÔNIO MEDICINAL DERMATOLOGICAMENTE TESTADO CLINICAMENTE TESTADO EXCLUSIVA SINERGIA DE ÓLEO OZONIZADO COM ÓLEOS ESSENCIAIS E ÓLEOS VEGETAIS PRESERVADOS NÃO TESTADO EM ANIMAIS', 83.16, 83.16, NULL, 'Beauty > Skincare > Facial Oil', 'https://cf.shopee.com.br/file/sg-11134201-7rdvk-lzjul18em59k92', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F415568490%2F18722844454', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
