INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18798112403', 'Acquaflora Pós-Progressiva Máscara Capilar 250ml', 'Acquaflora Pós-Progressiva Máscara para cabelos quimicamente alisados. Acquaflora Pós-Progressiva ajuda a nutrir, hidratar e regenerar profundamente os fios que passaram por processos de alisamento ou escovas progressivas. A Máscara Acquaflora Pós-Progressiva traz o Complexo de Nanocristalização dos fios, que ajuda na recuperação da fibra capilar e devolve brilho e movimento. Seus agentes condicionantes exclusivos diminuem o frizz, além de fortalecer o cabelo e aumentar a durabilidade do efeito liso. Conselho de Aplicação Após lavar os cabelos, remova o excesso de umidade e aplique a máscara no comprimento e pontas. Massageie delicadamente e deixe agir por alguns minutos. Enxágue bem. Nossos Experts Ensinam Para prolongar o efeito do tratamento e potencializar a ação dos agentes, utilize sempre os produtos da mesma linha.', 123.25, 69.9, NULL, 'Beauty > Bath & Body Care > Sun Care', 'https://cf.shopee.com.br/file/sg-11134201-8261u-ml2byfl81iip11', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F18798112403', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
