INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697970000', 'Patinete Raposinha Dobrável 2 Rodas Vermelho - Zippy Toys', 'Procurando por um brinquedo divertido para o seu filho ou filha? O Patinete Raposinha da Zippy Toys é uma escolha incrível! Este patinete é a escolha perfeita para crianças que amam se movimentar e se divertir ao ar livre. O Patinete Raposinha tem um tema super fofo de raposinha, que com certeza vai encantar as crianças! Além disso, ele é dobrável, tornando-o fácil de guardar e transportar quando não estiver em uso. Com ajuste de altura, o Patinete Raposinha pode crescer junto com a criança. Ele também possui um freio traseiro para garantir uma frenagem segura e suave. Este patinete resistente suporta até 35kg, então é adequado para crianças de diversas idades e estaturas também. Se você está procurando um brinquedo divertido e prático para manter seus filhos ativos e felizes, o Patinete Raposinha da Zippy Toys é a escolha ideal! Especificações: - Idade Recomendada: a partir de 5 anos - Dimensões Aproximadas do produto (CxLxA): 59 x 26 x 73 cm - Altura ajustável - Sistema de freio traseiro - Dobrável - Rolamento Abec-7 - Material: PVC, Ferro e EVA - Peso máximo suportado: 35 Kg Características: - Marca: Zippy Toys - Modelo: 8742 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - 01x Patinete Raposinha Dobrável 2 Rodas Vermelho', 144.33, 144.33, NULL, 'Mom & Baby > Toys > Sports & Outdoor Play', 'https://cf.shopee.com.br/file/sg-11134201-7rdy0-m1fupzs9p8ov11', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F371036439%2F23697970000', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
