INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20297920973', 'Kit Braé Hair Proteín e Divine Plume Sérum Capilar (2 produtos)', 'Kit Braé Hair Proteín e Divine Plume Sérum Capilar (2 produtos) Esse Kit Contém Braé Hair Protein - Proteína Concentrada Leave-in 80g: é um tratamento capilar enriquecido com um poderoso complexo de proteínas vegetais. Sua fórmula concentrada garante reparação dos danos, redução de pontas duplas e proteção dos fios. Atua na reposição de proteínas essenciais e possui proteção térmica (de até 230°C). Fios hidratados, nutridos e protegidos. Braé Divine Plume Sensation - Sérum Reparador Capilar 60ml: possui fórmula ultra concentrada com ação emoliente, hidratante e nutritiva. Consegue deixar cabelos macios, sedosos e com brilho intenso, além de disciplinar os fios rebeldes. Conselho de Aplicação Proteína: aplique diretamente nos cabelos secos ou úmidos. Comece pelas pontas até o comprimento, evitando a raiz. Finalize como desejar. Não é necessário enxaguar. Plume: aplique algumas gotas do sérum na palma das mãos e espalhe no comprimento dos cabelos até completa absorção. Finalize como desejar.', 204.4, 204.4, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rdwy-m147ygb9xfbn03', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F20297920973', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20897969008', 'Keune So Pure Clarify Refil - Shampoo 400 ml', 'Keune So Pure Clarify Refil - Shampoo 400 ml Indicado para todos os tipos de cabelo. Keune So Pure Clarify limpa gentilmente e sem agredir os fios e o couro cabeludo, auxiliando no controle de umidade e antipoluição. Formulado com romã, remove a sujeira, os resíduos e os radicais livres, protegendo as madeixas da oxidação por fatores externos. Embalagem refil, que ajuda na redução do uso de plástico no meio ambiente. Livre de parabenos, cruelty free, vegano e carbono neutro. Conselho de Aplicação Aplique o shampoo no couro cabeludo úmido, massageie até formar espuma, distribua entre os fios, enxágue completamente e repita se necessário.', 447.9, 231.9, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-7rdvc-m1h3a3y8956efe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F20897969008', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
