INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259903832', 'Cream Cheese Light Danubio', 'O Cream Cheese Light Danubio é a opção ideal para quem busca uma alimentação equilibrada e saborosa. Com menos calorias e sem glúten, é perfeito para dietas com restrição de lactose e para celíacos. * Versão light com redução de 29% de calorias e 35% de gorduras totais * Sem glúten * Ideal para dietas com restrição de lactose * Fabricado por Dan Vigor Indústria e Comércio de Laticínios Ltda', 23.79, 20.21, NULL, 'Food & Beverages > Dairy & Eggs > Others', 'https://cf.shopee.com.br/file/sg-11134201-8258h-mqnelghtvrwja3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1703290582%2F58259903832', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13591703871', 'Kit Cronômetro Digital QiYi e Mini Tapete Galaxy para Cubo Mágico', 'SOBRE O PRODUTO Cronômetro digital QiYi para treinos de cubo mágico e speedcubing. O acionamento é feito pelos sensores de toque: apoie as mãos, aguarde o sinal de prontidão e retire-as para iniciar a contagem. DESTAQUES - Visor com três casas decimais - Resolução de 0,001 segundo - Sensores de toque para início e parada - Encaixes para fixação em tapete compatível ESPECIFICAÇÕES - Material: plástico ABS - Dimensões aproximadas: 276 x 81 x 34 mm - Alimentação: 2 pilhas AAA, não inclusas CONTEÚDO DA EMBALAGEM - 1 cronômetro digital QiYi - 1 mini tapete Galaxy - 1 kit de encaixe para tapete', 189.9, 189.9, NULL, 'Hobbies & Collections > Toys & Games > Rubik''s Cubes', 'https://cf.shopee.com.br/file/d4b3fefff94ccd9e5f6dacebab92b2ac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F302271094%2F13591703871', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22494450033', 'Removedor De Cola Graxa e Piche Finisher Tira Adesivo', 'Elimine as sujeiras mais difíceis da lataria com o Removedor de Cola, Graxa e Piche Finisher. Este descontaminante automotivo profissional limpa e dissolve com extrema facilidade grudes pesados que não saem na lavagem comum, agindo rápido sem danificar a superfície. É o produto de estética automotiva perfeito para remover resíduos de piche de asfalto, ceras antigas, graxas e restos de cola de adesivos ou insulfilm. Escolha o Tamanho Ideal nas Variações: 60ml: Uso prático e portátil (perfeito para ter no porta-luvas para emergências). 700ml com Borrifador: Pronto para o uso diário na oficina ou detalhamento. 1,5L: Máximo rendimento e economia para profissionais de lava-rápido. Alta Eficiência: Dissolve piche de asfalto, óleos pesados e colas de etiquetas com facilidade. Seguro para Várias Superfícies: Pode ser aplicado em metais, plásticos, vidros e borrachas. Pronto Uso: Prático e rápido, sem necessidade de diluição. Modo de Uso Rápido: Agite bem o frasco antes de usar. Aplique o produto diretamente sobre a sujeira e deixe agir por alguns minutos. Se necessário, esfregue levemente com uma microfibra macia ou pincel de detalhamento. Enxágue abundantemente com água para remover os resíduos. Conteúdo da Embalagem: 01 Unidade do Removedor Finisher no tamanho selecionado (60ml, 700ml ou 1,5L).', 134.99, 134.99, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Degreasers', 'https://cf.shopee.com.br/file/br-11134207-820l8-moihsnc0kwzk32', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F369458625%2F22494450033', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20597808814', 'Cortina Decorativa Metalizada Roxo 1x2m - 1 unidade - Rizzo', '✨ Cortina Decorativa Metalizada Roxo 1x2m 1 unidade ideal para facilitar seu dia a dia com praticidade e eficiência! O Cortina Decorativa Metalizada Roxo 1x2m 1 unidade combina funcionalidade e qualidade, sendo uma excelente escolha para quem busca praticidade e um ótimo resultado no uso diário. Descrição Técnica: Produto: Cortina Decorativa Metalizada Roxo 1x2m Modelo: 1 unidade Composição: Quantidade: 1 unidade Marca: Rizzo Dúvidas Frequentes: Quanto tempo leva o envio? ⏰ Todos os pedidos com etiqueta de envio liberado pela shopee até as 18hs são coletados no próximo dia útil pela transportadora Shopee Express. Qual o prazo de entrega? 🛵 A loja não tem acesso a parte logística da shopee. A Shopee não informa para a loja prazo de entrega. Ao clicar em comprar na opção envios é apresentado o prazo de entrega. O produto é novo? 😀 Sim. Só trabalhamos com produto novos e dentro da embalagem original do fabricante. Como faço para comprar mais de um item da loja? 🛍 No app ao lado do botão comprar tem o ícone de um carrinho de supermercado, clicando nele o produto será acrescentado no carrinho que fica na parte superior do app. Após acrescentar todos os produtos que gostaria é só clicar no carrinho e selecionar todos os itens e clicar em continuar. Comemore com Alegria: 🥰😀 Na Rizzo Distribuidora, a tradição e o encanto do nosso espaço físico no coração da 25 de março, em São Paulo, são cuidadosamente embalados para chegar até você. Permita-nos levar a magia de uma das lojas mais tradicionais da região diretamente para o conforto da sua casa ou empresa.', 14.9, 14.9, NULL, 'Home & Living > Decoration > Curtains & Blinds', 'https://cf.shopee.com.br/file/sg-11134201-7rdxw-lzrn9muzphrga0', 'https://shope.ee/a