INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693863141', 'Irrigador Dental Portátil Oral Cleaning G-Life', 'Você está no caminho certo para melhorar a saúde da sua gengiva e ter um sorriso mais saudável! O Irrigador Dental Oral Cleaning G-Life proporciona maior limpeza e frescor na higiene bucal. Ajuda a remover resíduos de comida entre os dentes, previne contra bactérias orais e massageia a gengiva. Muito recomendado para as pessoas que utilizam aparelhos ortodônticos! Possui bocais de reposição, 3 modos de ajuste do jato de água, desligamento automático após 3 minutos de uso contínuo, rotação 360° e carregamento via usb. Reservatório com capacidade para 230 ml de água. Itens inclusos: 1 Irrigador oral 4 bicos diferentes para limpeza mais eficiente 1 Cabo USB para carregar', 230.0, 189.0, NULL, 'Home Appliances > Small Household Appliances > Water Flossers', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m7vn1gcsdbbo4f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275933522%2F22693863141', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
