INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093169797', 'Atuador De Marcha Lenta Original Gauss Equivalente 2s6a9f715ba Ford', 'Atenção, apaixonado por carros! Está buscando o componente ideal para garantir a marcha lenta perfeita do seu Ford? Apresentamos o Atuador de Marcha Lenta Gauss, a solução inteligente para o seu veículo! Entenda a importância do Atuador de Marcha Lenta O Atuador de Marcha Lenta é uma peça fundamental no sistema de injeção eletrônica. Ele controla a entrada de ar no motor quando o veículo está em marcha lenta, garantindo um funcionamento suave e estável, além de evitar o consumo excessivo de combustível. Por que escolher o Atuador de Marcha Lenta Gauss? A Gauss é referência em componentes automotivos, sinônimo de qualidade e durabilidade. O Atuador de Marcha Lenta Gauss Equivalente 2S6A9F715BA Ford é fabricado com alta tecnologia, seguindo os mais rigorosos padrões de qualidade, para garantir o máximo desempenho e confiabilidade para o seu carro. Compatibilidade Este atuador é compatível com diversos modelos Ford com motor Zetec Rocam: Courier (2007 a 2013) Ecosport (2003 a 2012) Fiesta (2004 a 2014) Focus (2003 a 2009) Ka (2004 a 2007) Equivalências Este atuador possui equivalência com os códigos: DPL808245 (DPL), 1149683, 2S6A9F715BA e 2S6A9F715BB (Ford Original), 84057 (Meat & Doria), 7427 (MTE-Thomson) e A98102 (VDO). Especificações Técnicas Marca Gauss GTIN 7899751907460 Dimensões da embalagem 8 x 9.5 x 5 cm Peso 0.137 kg Não perca tempo! Garanta agora mesmo o seu Atuador de Marcha Lenta Gauss e volte a ter o melhor desempenho do seu Ford. Clique e compre já!', 134.99, 134.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/br-11134201-7r98o-m5kpxc2w3o1x21', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1272573624%2F23093169797', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22197693434', 'Kit Lâmpada Super Branca Creta 2.0 2017-2020 Farol E Milha', '🚚 𝗘𝗡𝗩𝗜𝗢 𝗜𝗠𝗘𝗗𝗜𝗔𝗧𝗢 𝗘𝗠 𝗔𝗧𝗘́ 𝟭𝟮𝗛 𝗨́𝗧𝗘𝗜𝗦 A Lâmpada Super Branca Hyundai Creta 2 original Gauss tem como principais características: Luz branca azulada para uma aparência de Xênon; Até 30 % mais luz (se comparada com as lâmpadas halógenas comuns); Revestimento de anel azul patenteado para menos brilho e filtro UV; Homologação Detran; Tenha a mais avançada tecnologia em iluminação, o modelo tem um excelente padrão de qualidade e possui certificação do Inmetro confirmando sua eficácia e segurança para a melhor iluminação. As Lâmpadas Hyundai Creta 2 Super Branca combina eficiência com durabilidade, para que você possa ter o melhor desempenho do seu veículo, trazendo o melhor de iluminação nas estradas. As Lâmpadas Automotivas Gauss são rigorosamente testadas para que apresentem sempre o melhor resultado. Usando tecnologia de ponta, a Gauss hoje é uma multinacional, com mais de 20 anos do mercado e certificado pelo ISO 9001, que garante excelência de qualidade e atendimento. Compatibilidade com os seguintes veículos: Hyundai Creta 2 2017 Hyundai Creta 2 2018 Hyundai Creta 2 2019 Hyundai Creta 2 2020 Especificações tecnicas do veículo: veículo: Creta 2 Montadora: Hyundai Ano: 2017 a 2020 Especificação Tecnica - Lâmpadas: Cod Milha: Gl95H11 Cod Alto: Gl97Hb3 Cod Baixo: Gl97Hb3 Modelo Lâmpada: Hb3-Hb3-H11 Modelo Baixo: Hb3 Modelo Alto: Hb3 Modelo Milha: H11 Modelo: Super Branca Posicao: Baixo, Alto E Milha Encaixe: P20D, P20D, Pgj19-2 Encaixe Baixo: P20D Encaixe Alto: P20D Encaixe Milha: Pgj19-2 Cor Lâmpada: Azul Cor Luz: Branca Tecnologia Lâmpada: Halógena Quantidade Lâmpadas: 6 Potência: 60 Potência Baixo: 60W Potência Alto: 60W Potência Milha: 55W Tensão: 12 🚚 Enviamos para todo o Brasil com segurança e rapidez! ✅ Qualquer dúvida estamos à disposição no chat.', 223.07, 223.07, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/br-11134201-7r98o-m5kkobflvmts06', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1272573624%2F22197693434', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
