INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43564542824', 'Kit Hello Kitty - Laptop Infantil Bilíngue + Boombox Karaoke', 'Laptop infantil bilíngue (português/inglês) com diferentes grupos de jogos e atividades, sendo eles: música, letras, palavras, ortografia, perguntas e respostas, soma e divisão. Com o laptop da Hello Kitty as crianças aprendem brincando. Utiliza 3 pilhas AA não inclusas.Os laptops infantis são uma febre entre a criançada, eles amam imitar seus pais fingindo que estão trabalhando como eles, eles também levam para a escola e mostram para seus amigos e se divertem muito com isso. Apresentamos o encantador Boombox Karaokê Hello Kitty, uma experiência musical divertida e cativante para os pequenos fãs da personagem mais fofa do mundo. Equipado com uma função amplificadora, o Boombox Karaoke permite que você conecte seu dispositivo de som, como um smartphone ou tablet, e reproduza suas músicas preferidas. Deixe que a Hello Kitty faça parte das aventuras musicais dos pequenos, transformando cada canção em uma experiência encantadora e educativa. É uma ótima maneira de estimular a criatividade, a expressão vocal e a paixão pela música. Divirta-se e cante junto com a Hello Kitty!', 229.98, 229.98, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rdxu-mdq66bx1jsak6f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F689242394%2F43564542824', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
