INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898829847', 'Kit Selim Gts 2 Molas + Manopla Gts Preto Branco Confort MTB', 'Kit Selim GTS 2 Molas + Manopla GTS Preto/Branco Confort MTB Esse kit é perfeito para quem busca mais conforto e ergonomia na bicicleta, seja para passeios, trilhas ou uso urbano. O selim GTS com duas molas garante excelente absorção de impactos, reduzindo desconfortos em terrenos irregulares. Já as manoplas anatômicas proporcionam melhor aderência e controle, evitando fadiga nas mãos durante longos pedais. Benefícios: Selim com sistema de molas para maior absorção de impactos Manoplas anatômicas que reduzem a fadiga das mãos Material resistente e de alta durabilidade Maior conforto para pedais longos e terrenos acidentados Design moderno nas cores preto e branco Especificações: Marca: GTS Selim com 2 molas para melhor amortecimento Manoplas ergonômicas para MTB e uso urbano Cor: Preto/Branco Compatível com diversos modelos de bicicletas Ótima opção para quem deseja pedalar com mais conforto e segurança. Envio rápido e seguro. Aproveite a oferta.', 37.72, 37.72, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-7rdw1-mdrzhqs998f821', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F23898829847', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23497670523', 'Buzina Automotiva Caracol Ford Ecosport 2008-2011 12v Original Gauss', '🚚 𝗘𝗡𝗩𝗜𝗢 𝗜𝗠𝗘𝗗𝗜𝗔𝗧𝗢 𝗘𝗠 𝗔𝗧𝗘́ 𝟭𝟮𝗛 𝗨́𝗧𝗘𝗜𝗦 Buzina Automotiva Caracol Ford EcoSport 2008-2011 12v Gauss A principal função da buzina é alertar no trânsito sobre alguma condição adversa sendo utilizada para evitar uma colisão no trânsito, em ocasiões de desatenção de outro motorista.Trata-se de um item obrigatório no veículo, que pode render multa para o motorista, caso não esteja funcionando regularmente. A Buzina Gauss Ford EcoSport Buzina Caracol combina eficiência com durabilidade, para que você possa ter o melhor desempenho do seu veículo As buzinas da Gauss são rigorosamente testados para que apresentem sempre o melhor resultado. Usando tecnologia de ponta, a Gauss hoje é uma multinacional, com mais de 20 anos do mercado e certificado pelo ISO 9001, que garante excelência de qualidade e atendimento. Compatibilidade com os seguintes veículos: Ford EcoSport 2008 Ford EcoSport 2009 Ford EcoSport 2010 Ford EcoSport 2011 Especificações Técnicas do Veículo: Veículo: EcoSport Montadora: Ford Ano: 2008 a 2011 Especificação Técnica - Buzina: Cod Produto: Gb1052 Modelo: Buzina Caracol Voltagem: 12.0 Nivel Sonoro: 110.0 Quantidade De Conectores: 2.0 Quantidade Buzinas: 1.0 Quandidade De Cornetas: 1.0 Origem: Brasil 🚚 Enviamos para todo o Brasil com segurança e rapidez! ✅ Qualquer dúvida estamos à disposição no chat.', 46.99, 46.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/br-11134201-7r98o-m5ki6pr69oky96', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1272573624%2F23497670523', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493010919', 'Jogo 4 Pneus Itaro Aro 16 Comformax 205/55R16 91V', '*Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores. Sobre a marca Itaro A Itaro nasceu para motoristas viverem novas histórias - em duas ou quatro rodas. Desenvolvida nas grandes fábricas asiáticas, a marca é homologada nos principais mercados da Europa e América, como o Brasil. Seus pneus foram pensados em centros de pesquisa e desenvolvimento de países como China, Paquistão e Tailândia, que estão entre os maiores do mundo. Com presença exclusiva na PneuStore, a Itaro oferece soluções para carros de passeio, SUVs, caminhonetes, motos e caminhões, com excelente qualidade e custo que ajudam motoristas a viverem novos capítulos todos os dias.', 1472.26, 1369.21, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rd5s-lvdpjux85xaace', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F23493010919', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
