INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22599372390', 'Acabamento Perfil "U" p/Forro PVC 3CMX3M Marrom/Cerejeira Bariri Cerejeira', 'O Perfil U em PVC é a solução ideal para quem busca um acabamento refinado e profissional na instalação de forros residenciais ou comerciais. Este acessório atua como moldura entre o forro e a parede, escondendo recortes e garantindo uma transição visual harmoniosa e limpa para o teto. • Design e Estilo: A tonalidade cerejeira confere um aspecto amadeirado que traz calor e sofisticação ao ambiente sem a necessidade de pintura ou tratamentos complexos. • Resistência Superior: Produzido com material que não propaga fogo, este perfil é imune a fungos e corrosão, mantendo sua integridade mesmo em áreas que sofrem com a umidade. • Facilidade de Manutenção: A superfície lisa permite uma limpeza rápida e eficiente utilizando apenas pano macio com água e sabão neutro para conservar o aspecto de novo por mais tempo. • Tamanho e Cobertura: Cada peça apresenta 300 cm de comprimento com altura de 3 cm e largura de 1,3 cm, dimensões planejadas para se adaptar perfeitamente a diferentes espessuras de placas de forro. • Versatilidade de Uso: O modelo é compatível com forros de diversos tamanhos, sendo especialmente indicado para réguas que exigem um arremate lateral preciso e seguro. Acompanha 1 rodaforro perfil U. Para uma compra certeira: Os itens decorativos das imagens não fazem parte do produto. Garantia: 12 Meses Altura (cm): 3 Largura (cm): 1.3 m² por caixa: 15 Espessura (mm): 1.3 Área por Peça: 10 Comprimento (cm): 300 Imune a Fungos: Sim Requer Pintura: Não Profundidade (cm): 0.8 Imune à Corrosão: Sim Origem do Produto: Nacional Resistência Química: Sim Permite Reutilização: Sim Resistência à Umidade: Sim Acompanha Ficha Técnica: Não Porte do Ambiente Indicado: Médio Porte Acompanha Manual de Instalação: Não Informações Complementares (Novo): O Roda forro "U" PVC compõe a instalação do Forro Régua PVC e é utilizado para acabamento final do forro Acabamento (Construção e Acabamento): Liso Material Principal Construção e Acabamento: PVC Marca: Bariri Modelo: Bariri Pvc Cor: Cerejeira Meio Ambiente: Produzido com material dentro das normas ambiental Cor do Produto: Cerejeira Itens Inclusos: 1 Rodaforro perfil U Cor Predominante: Marrom Linha ou Coleção: Linha Tipo de Certificado: NRR14285', 93.55, 93.55, NULL, 'Home & Living > Tools & Home Improvement > Roofing & Flooring', 'https://cf.shopee.com.br/file/sg-11134201-820lb-mo2ykailt14z8e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F22599372390', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22097440727', 'Filtro De Oleo Ford Belina Del Rey Escort F250 Pampa Royalle Scala Verona Versalles', 'O FILTRO DE ÓLEO MAHLE OC522 É UM FILTRO DE ALTA QUALIDADE PROJETADO PARA FORNECER PROTEÇÃO SUPERIOR AO MOTOR DO SEU VEÍCULO. ESPECIFICAÇÕES: CÓDIGO DO FABRICANTE: OC522 MARCA: MAHLE / METAL LEVE TIPO DE FILTRO: BLINDADO DIMENSÕES: DIÂMETRO EXTERNO: 76 MM ALTURA: 97,5 MM EFICIÊNCIA DE FILTRAÇÃO: 99,9% MATERIAL: CORPO: AÇO MEIO FILTRANTE: CELULOSE E FIBRAS SINTÉTICAS VÁLVULA ANTIRRETORNO: BORRACHA NITRÍLICA VEDAÇÃO: BORRACHA NITRÍLICA BENEFÍCIOS: PROTEÇÃO SUPERIOR DO MOTOR: O FILTRO DE ÓLEO MAHLE OC522 REMOVE IMPUREZAS COMO POEIRA, FULIGEM, METAL E PARTÍCULAS DE DESGASTE DO ÓLEO, PROTEGENDO AS PEÇAS DO MOTOR CONTRA DESGASTE E CORROSÃO. MAIOR VIDA ÚTIL DO MOTOR: AO MANTER O ÓLEO LIMPO, O FILTRO DE ÓLEO MAHLE OC522 AJUDA A AUMENTAR A VIDA ÚTIL DO MOTOR. MELHOR DESEMPENHO DO MOTOR: O FILTRO DE ÓLEO MAHLE OC522 GARANTE O FLUXO IDEAL DE ÓLEO PARA O MOTOR, O QUE CONTRIBUI PARA UM MELHOR DESEMPENHO E ECONOMIA DE COMBUSTÍVEL. SEGURANÇA E CONFIABILIDADE: O FILTRO DE ÓLEO MAHLE OC522 É FABRICADO COM MATERIAIS DE ALTA QUALIDADE E PASSA POR RIGOROSOS TESTES DE CONTROLE DE QUALIDADE, GARANTINDO SEGURANÇA E CONFIABILIDADE. FÁCIL INSTALAÇÃO: O FILTRO DE ÓLEO MAHLE OC522 É FÁCIL DE INSTALAR E REMOVER, SEM NECESSIDADE DE FERRAMENTAS ESPECIAIS. OUTRAS CARACTERÍSTICAS: TECNOLOGIA DE FILTRAGEM MULTICAMADAS PARA MÁXIMA EFICIÊNCIA VÁLVULA ANTIRRETORNO PARA EVITAR O REFLUXO DE ÓLEO DURANTE A PARADA DO MOTOR VEDAÇÃO ROBUSTA PARA EVITAR VAZAMENTOS ALTA CAPACIDADE DE RETENÇÃO DE IMPUREZAS RESISTÊNCIA A ALTAS TEMPERATURAS E PRESSÕES CONSULTE O MANUAL DO SEU VEÍCULO PARA VERIFICAR A FREQUÊNCIA IDEAL DE TROCA DO FILTRO DE ÓLEO. ------------------------------------------------------ APLICAÇÃO COMPLETA FORD