INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898312422', 'Shampoo Anticaspa Head & Shoulders Men 3 em 1 400ml', 'O Shampoo Head & Shoulders 3 em 1 possui uma fórmula com pH balanceado possui uma tecnologia inteligente: age diretamente no couro cabeludo, com 2x mais deposição de ativos anticaspa. Um escudo de proteção duradouro. Use diarimente para ter um cabelo lindo e couro cabeludo bem cuidado. Um Shampoo que limpa, protege e suaviza só podia ser Head & Shoulders. Experimente a marca N°1 de shampoo do mundo. O Shampoo que limpa profundamente, protege contra a caspa e suaviza o cabelo.', 49.34, 49.34, NULL, 'Beauty > Men''s Care > Hair Care', 'https://cf.shopee.com.br/file/sg-11134201-7rd6b-m770v8zkhypi28', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F23898312422', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
