INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593483870', 'Máscara de Dormir com Almofada Hello Kitty', 'Você passou o dia todo vivendo aventuras incríveis, mas precisa de uma mãozinha para salvar a hora da sua soneca durante a viagem? A gente te ajuda! Não importa qual é a sua aventura, essa máscara com almofada é ideal para te acompanhar em todos os lugares! O produto é importado, feita com tecido plush e o enchimento em fibra siliconada, é muito fofinha e confortável, com detalhes que vão fazer você se apaixonar! Se você está cansado durante a viagem e não consegue dormir, essa máscara com almofada é ideal para você! A máscara bloqueia todas as luzes do ambiente e ajusta perfeitamente no rosto, com esse produto você desbloqueia um novo nível na hora das suas aventuras! Além de confortável, você consegue levar pendurada na bolsa! Especificações: Altura: 20cm| Largura: 40cm| Enchimento: Fibra Siliconada| Tecido: Malha Plush (100% Poliéster) Cuidados e recomendações de uso: Não alvejar. Permitido uso de centrifuga e máquina secadora. Temperatura máxima de lavagem 40°. Não limpar a seco.', 124.9, 124.9, NULL, 'Travel & Luggage > Travel Accessories > Travel Pillows & Eye Covers', 'https://cf.shopee.com.br/file/sg-11134201-81zun-miw0sk53hts0cf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404743073%2F23593483870', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
