INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203186366', 'Aditivo Bardahl Power Diesel 500ml Limpa Bico Via Tanque Combustível Pickup Caminhão', 'POWER DIESEL Aditivo para combustível que aumenta o número de cetano. INDICAÇÃO Tanque de combustível de veículos com motores a diesel. Ideal para veículos utilitários, caminhonetes, 4x4 e 4x2, caminhões e ônibus. BENEFÍCIOS Aumenta o número de cetano do diesel Mantém limpos bicos, bomba injetora e válvulas Evita a formação de emulsões estáveis entre a água e o diesel Lubrifica bicos injetores e bomba injetora MODO DE USAR Deve ser adicionado ao combustível na proporção de 0,6%, ou seja, um frasco de 500 ml para cada 80 litros de diesel em todo abastecimento. Frasco: 500 ml Marca: Bardahl Aditivo para combustível que aumenta o número de cetano.', 73.54, 73.54, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-8261h-mjfjez36q5fmae', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F552700125%2F58203186366', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
