INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58205127274', 'CHAVEIRO CORITIBA OFICIAL ESCUDO', 'Chaveiro Oficial Coritiba Foot Ball Club em Metal Premium Leve sua paixão pelo Coritiba Foot Ball Club para todos os lugares com este chaveiro oficial licenciado. Produzido em metal de alta qualidade e acabamento premium, é o acessório ideal para torcedores que desejam demonstrar seu orgulho pelo clube no dia a dia. Com escudo esmaltado em alto relevo e excelente nível de detalhes, o chaveiro combina resistência, elegância e praticidade. Pode ser utilizado em chaves, mochilas, bolsas, malas ou até mesmo como item de coleção. Destaques do produto: Produto oficial licenciado do Coritiba Foot Ball Club Fabricado em metal com acabamento premium Escudo esmaltado em alto relevo Resistente, compacto e durável Argola metálica com mosquetão para maior praticidade Ideal para uso diário ou para presentear torcedores Especificações: Material: Metal Cor: Prata e verde Fixação: Argola metálica e mosquetão Produto oficial licenciado Conteúdo da embalagem: 1 Chaveiro Oficial Coritiba Foot Ball Club Este é um excelente presente para qualquer torcedor do Coxa, reunindo qualidade, durabilidade e um acabamento diferenciado para quem faz questão de carregar a paixão pelo Coritiba em todos os momentos.', 29.9, 29.9, NULL, 'Hobbies & Collections > Souvenirs > Keychains', 'https://cf.shopee.com.br/file/br-11134207-820m8-mqgcqs0d27lv78', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1561205436%2F58205127274', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
