INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58255788555', 'Kit 10 Unidades Sopas Cremosas VONO® Individual Sabor Batata com Carne 18G', 'VONO® Individual é uma sopa perfeita para quem busca a liberdade de um momento que une praticidade, sabor e facilidade no preparo. Dessa forma, acompanhado de VONO® Individual, o seu lanche, almoço ou jantar fica ainda mais especial, gostoso e aconchegante. Ótima escolha para curtir um momento só seu! Uma verdadeira caixinha de surpresas! Divino no quesito sabor a cada colherada, VONO® Individual garante uma experiência deliciosa para o seu paladar e, ao mesmo tempo, pode fazer parte de uma alimentação equilibrada e nutritiva. Deliciosidade: o prazer de saborear cada momento Seja individualmente ou no preparo de uma receita especial, uma coisa é certa: VONO® Individual pode fazer parte de refeições deliciosas e reconfortantes. É uma opção cremosa que dá aquele quentinho no coração, agrada seu paladar e te acompanha nos dias mais frios — ou nos mais quentes! Equilíbrio: o complemento ideal para suas refeições', 43.08, 43.08, NULL, 'Food & Beverages > Cooking Essentials > Stock, Gravy & Instant Soup', 'https://cf.shopee.com.br/file/sg-11134201-824hk-mplpx3hd3jsw0f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1598062483%2F58255788555', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
