INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43522581974', 'Kit de 4, 8 ou 12 Peças Pijama Brilha no Escuro Infantil Menino Verão - Roupa Infantil Masculino', '👦✨ Kit Pijama Infantil Menino 4, 8 ou 12 Peças – Brilha no Escuro ✨👕 Deixe as noites do seu pequeno muito mais divertidas e confortáveis! 🌙 Nosso kit é perfeito para quem busca pijama infantil menino, roupa infantil menino e até mesmo roupa de bebê menino, com qualidade, economia e estilo. Você pode escolher entre 4, 8 ou 12 peças O kit inclui: 4 peças ✔ 2 camisetas em algodão ✔ 2 bermudas/shorts lisos ou estampados em algodão 8 peças ✔ 2 camisetas em algodão ✔ 2 bermudas/shorts lisos ou estampados em algodão 12 peças ✔ 6 camisetas em algodão ✔ 6 bermudas/shorts liso ou estampado em algodão ✅ Super confortável e leve, ideal para dormir bem. ✅ Estampas divertidas que brilham no escuro 🌟. ✅ Ótimo custo-benefício: mais peças por menos! ✅ Envio rápido em até 24h 📦 ⚠️ Atenção: os kits são sortidos, sem opção de escolha de estampas, cores ou modelos. As peças podem ser diferentes das fotos, mas sempre com a mesma qualidade, conforto e beleza. ✨ Um produto essencial para o guarda-roupa dos pequenos, unindo praticidade, estilo e diversão na hora do soninho!', 62.9, 38.99, NULL, 'Baby & Kids Fashion > Boy Clothes > Sleepwear', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjzyule4vwu97c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436773535%2F43522581974', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256600742', 'Payot Maternité Plus - Creme Antiestrias 200ml', 'Creme antiestrias. Payot Maternité Plus restaura a elasticidade e firmeza da pele, deixando uma aparência mais bonita. O Creme Antiestrias Payot Maternité Plus tem em sua composição óleos vegetais e pantenol que fortalecem as fibras elásticas e o colágeno. Garante uma hidratação e nutrição profunda da derme, deixando-a macia ao toque. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 63.9, 63.9, NULL, 'Mom & Baby > Maternity Healthcare > Moisturizers & Creams', 'https://cf.shopee.com.br/file/sg-11134201-82612-mlmhj7t7i0w379', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58256600742', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43514529345', 'Chuteira De Futebol Futsal Matis XXI Jr Kids Infantil Original Penalty', 'Chuteira Futsal Infantil Penalty Matis XXI Modelo: MATIS-KIDS-XXI Destaque seu talento dentro das quatro linhas com a Chuteira Futsal Infantil Penalty Matis, projetada para oferecer conforto, durabilidade e desempenho superior. Ideal para os pequenos atletas, este modelo combina tecnologia avançada e design moderno, proporcionando total controle e segurança nas quadras. Benefícios: Conforto e Controle: Palmilha em EVA plana de 3,5 mm para maior amortecimento e suporte durante as jogadas. Durabilidade Superior: Cabedal em Micropower, com microcélulas de PVC que garantem alta resistência à abrasão. Desempenho Avançado: Solado em borracha com tecnologia de ponta para movimentos precisos e maior vida útil. Diferenciais Técnicos: Hiperflex: Canaletas estrategicamente posicionadas que auxiliam na flexão e movimentação natural dos pés. Non-Marking: Tecnologia no solado que evita marcas e riscos no piso, ideal para uso em quadras. Rotate: Pontos de giro no solado que facilitam movimentos rotacionais e reduzem o risco de lesões. Especificações: Solado: Borracha de alta resistência à abrasão. Cabedal: Material Micropower para maior resistência e durabilidade. Palmilha: EVA plana de 3,5 mm para conforto extra. Tecnologias: Hiperflex, Non-Marking e Rotate. Cuidados com o Produto: - Limpe com pano umedecido, água e sabão neutro. - Deixe secar à sombra. - Armazene em ambiente seco e ventilado. Por que escolher a Penalty Matis? Produto 100% original, disponível na Usee Brasil, uma loja confiável e especializada em qualidade. Perfeita para atletas mirins que buscam conforto, estilo e desempenho em todas as partidas. Garanta já a sua Chuteira Penalty Matis e eleve o jogo ao próximo nível!', 199.99, 115.99, NULL, 'Sports & Outdoors > Sports Footwear > Futsal Shoes', 'https://cf.shopee.com.br/file/sg-11134201-7rdwf-mdq5j9taazmc70', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349198275%2F43514529345', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
