INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51401921770', 'Jogo de Taças de Vinho de Cristal com Titânio Mendoza 540mL 2 peças - Seu Lar', 'Conjunto de Taças Vinho em Cristal Mendoza 540ml 2 peças - Seu Lar As Taças Mendoza são produzidas em Cristal com titânio trazendo em seu design mais brilho e transparência que as taças de vidro, são feitas com 460ml, elas são perfeitas para apreciar seu vinho em momentos especiais com sua família e amigos. Por serem de cristal, as taças possuem microporos e isso ajuda aerar o vinho quando giramos, todos os seus aromas ficam mais notórios do que na taça de vidro. Cuidados com suas taças: - Lavar com água e sabão neutro utilizando esponja macia. Secar com pano seco e macio. - Não utilizar produtos químicos ou abrasivos na limpeza. - Não pode ir ao micro-ondas. - Não pode ir à lava-louças. Dimensões: Altura: 24cm Diâmetro: 6,5cm Capacidade: 540ml Características: Marca: Seu Lar Modelo: Mendoza Referência: SL6899/2 Material: Cristal Quantidade: 2 peças Cor: Transparente Imagens ilustrativas.', 79.9, 65.9, NULL, 'Home & Living > Dinnerware > Cups, Mugs & Glasses', 'https://cf.shopee.com.br/file/sg-11134201-82269-mhc96l13vvgp10', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F402076848%2F51401921770', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
