INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250470082', 'Kit 12 Copos Avulso Aruba Long Drink 465ml Nadir', 'O Copo Aruba 465ml Nadir é a combinação perfeita entre design moderno, praticidade e qualidade. Produzido pela tradicional marca Nadir Figueiredo, esse copo de vidro é ideal para servir cervejas, refrigerantes, sucos, drinks e até água com muito mais elegância e conforto. Com capacidade generosa de 465ml, o Copo Aruba é uma excelente escolha para quem gosta de copos altos e funcionais, ideais tanto para o uso diário quanto para ocasiões especiais. Seu formato anatômico facilita o manuseio, enquanto o vidro transparente valoriza a cor e apresentação da bebida.Características do Copo Aruba 465ml:Capacidade: 465mlModelo: ArubaMarca: NadirMaterial: Vidro de alta resistênciaIdeal para: cerveja, sucos, drinks longos, refrigerantes, águaPode ir à lava-louçasExcelente para uso doméstico ou profissional (bares, restaurantes e eventos)Seja para relaxar após um dia cansativo ou para receber amigos com estilo, o Copo Aruba Nadir 465ml é a escolha certa. Um item indispensável para quem valoriza qualidade, durabilidade e beleza à mesa.', 71.88, 71.88, NULL, 'Home & Living > Dinnerware > Cups, Mugs & Glasses', 'https://cf.shopee.com.br/file/sg-11134201-8258p-mqqrgs6i5s778f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050213612%2F58250470082', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
