INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9151835244', 'Pó Facial Solto Translúcido Woman´s Be You Phallebeauty PH004', 'O Pó Solto Translúcido Woman´s Be You da PhÁlleBeauty é um aliado de quem tem pele oleosa. Pensado para finalizar a maquiagem, ele cria uma espécie de véu no rosto que ajuda a segurar a oleosidade e prolongar a duração dos outros produtos de maquiagem. Benefícios: - Aliado para quem tem pele oleosa; - Cria um véu no rosto que segura a oleosidade; - Prolonga a duração de outros produtos de maquiagem; Contém: 10g; Composição: Talc, Magnesium Stearete, Zinc Oxide, Paraffinum Liquidum, Phenoxyethanol, Ci 77492, Metylparaben, Ethylparaben, Ethylparaben, Butylpraben, Propylparaben Como Usar: Aplique sobre o rosto a base ou diretamente sobre ela, sempre que desejar controlar o brilho.', 12.99, 12.99, NULL, 'Beauty > Makeup > Face', 'https://cf.shopee.com.br/file/7227abed9d79fc3eb9bd7ca8e8f922a7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F434200296%2F9151835244', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23599312292', 'Granado Terrapeutics Sálvia E Confrey - Shampoo 180ml', 'Shampoo para cabelos oleosos. Limpa gentilmente os fioscontrola a oleosidade excessivados fios. Granado Terrapeutic Sálvia e Confrey tem propriedades adstringentes, antioxidantes e emolientes que ajudam na hidratação, mas sem deixar a fibra capilar pesada ou com oleosidade intensa. Para você se livrar do aspecto gorduroso e recuperar o movimento leve dos fios, Granado Terrapeutic Sálvia e Confrey proporciona toque sedoso e aveludado. Seu cabelo fica limpo, hidratado e sem o brilho excessivo. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 22.9, 22.9, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-82607-mjy7nx8mo8p1ce', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F23599312292', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22794892762', 'Weleda Mum - Manteiga Corporal para Estrias 150ml', 'Manteiga corporal para estrias. Weleda Mum melhora a elasticidade, previne estrias e nutre a pele. A Manteiga Corporal para Estrias Weleda Mum oferece uma abordagem natural e delicada para o tratamento da elasticidade da pele, sendo particularmente indicado para gestantes, pessoas em processos de mudança corporal ou com tendência ao surgimento de estrias. Com uma seleção de ingredientes cuidadosamente escolhidos, este creme nutre profundamente a pele, mantendo sua flexibilidade. A amêndoa, rica em propriedades nutritivas e emolientes, fortalece a barreira cutânea. Sua textura cremosa de rápida absorção proporciona conforto imediato sem deixar a pele oleosa. Como usar: Aplique a manteiga corporal em movimentos circulares suaves sobre a pele limpa e seca, com atenção especial às áreas propensas ao surgimento de estrias, como abdômen, quadris, coxas e seios. Massageie delicadamente até completa absorção, preferencialmente duas vezes ao dia, durante períodos de mudanças corporais como gravidez, ganho ou perda de peso significativa. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 154.9, 154.9, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/sg-11134201-8260e-mlmdv83ohvyaa0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F22794892762', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58252370184', 'Esmalte Anita Coleção Modo Avião', 'OEsmalte Anita Coleção Modo Avião tem fórmula de alta cobertura, proporciona cor vibrante já na primeira aplicação, enquanto o pincel anatômico facilita o uso e garante acabamento uniforme.Com secagem rápida e ótima fixação, mantém as unhas impecáveis por mais tempo. A Coleção Modo Avião foi inspirada em momentos de desconexão e autocuidado, perfeita para qualquer ocasião. Modo de Uso: Agite bem o frasco antes de usar. Aplique uma camada de base para proteger as unhas. Passe uma ou duas camadas do esmalte até atingir a cobertura desejada. Finalize com extra brilho para prolongar a durabilidade e realçar a cor.', 14.38, 14.38, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/sg-11134201-81ztw-milumakuzfnq4d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F58252370184', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58252113496', 'Bioderma Hydrabio Sérum Facial Hidratante e Fortalecedor 40ml', 'Sérum hidratante fortalecedor para todos os tipos de pele, inclusive as oleosas. Bioderma Hydrabio proporciona um boost de hidratação e luminosidade para a pele. O Sérum Facial Bioderma Hydrabio restaura a capacidade natural de hidratação da pele, devolvendo a vitalidade, saúde e brilho que você deseja. Bioderma Hydrabio Sérum possui uma fórmula exclusiva com a patente Aquagenium™, Ácido Hialurônico, Xilitol e Glicerina, que juntos fortalecem e recuperam o conforto e luminosidade da sua pele de forma duradoura. Além disso, possui fórmula suave, com perfume delicado e alta tolerância, é livre de parabenos, álcool e corantes, e foi testada sob controle dermatológico. Experimente o poder do Sérum Bioderma Hydrabio e veja sua pele radiante e revitalizada. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 135.9, 135.9, NULL, 'Beauty > Skincare > Eye Treatment', 'https://cf.shopee.com.br/file/sg-11134201-82607-mk4aveyfjxmo13', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58252113496', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793723409', 'Marcador para Quadro Branco Compactor Preto', 'Com o Marcador para Quadro Branco Compactor você conseguirá traços consistente que facilitem a visualização em sala de aula, reunião ou auditórios. A tinta de secagem rápida evita borrões nas mãos, mas sai com facilidade do quadro branco. A caneta para quadro bran co possui ponta cônica macia, porém reforçada, permitindo traços de 2 a 5 mm, dependendo do ângulo da escrita. Graças à exclusiva te cnologia Cap Off sua ponta não resseca, mesmo se destampada por algumas horas. O pincel para quadro branco Compactor pode ser reabas tecido de forma simples e sem fazer sujeira. Basta encaixar a tampa no fundo do marcador e girar no sentido anti-horário, colocar 10 0 gotas de reabastecedor QB, encaixar o fundo e girar no sentido horário até vedar completamente. Pronto! Você tem um marcador novo em mãos. Sem descarte, o seu bolso e o meio ambiente agradecem!', 24.99, 19.9, NULL, 'Stationery > Others', 'https://cf.shopee.com.br/file/sg-11134201-8259g-mqs0gc3la1oi5c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050213612%2F23793723409', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23696737059', 'Algodão Minná Hidrófilo 50g', 'Algodão Hidrófilo Minná é produzido a partir da rigorosa seleção de fibras naturais e 100% puro algodão hidrófilo. Oferecem qualidade, higiene, maciez e alto poder de absorção. Modo de uso: Aplicar no algodão o produto a ser utilizado e espalhar sobre a pele. Uso indicado para procedimentos diários de higiene, beleza como remoção de maquiagem, esmalte, aplicação de cosméticos e curativos.', 14.75, 14.75, NULL, 'Beauty > Beauty Tools > Makeup Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rbkt-lm6irsgjlie1eb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F23696737059', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17505552017', 'Mangá - Vagabond - 16 - Novo/Lacrado', 'Vagabond - 16 A espada enlouquece o homem... Kojiro está com 17 anos. O instinto selvagem represado em seu interior está prestes a explodir. Tipo de Produto: Revista Segmentos: Mangás Marcas: Planet Manga Autor(es): Takehiko Inoue Check-List: Janeiro/2022 Gênero: Ação, Adulto, Artes Marciais, Aventura, Drama, Histórico Demografia: Seinen Editora: Editora Panini Número de páginas: 212 Lombada/Encadernação: Quadrada Tipo de capa: Cartão Data de Lançamento: 19/01/2022 Idioma: Português', 51.9, 51.9, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/8dac8fa96048144ed672ccf2f06fbba9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F642933481%2F17505552017', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
