INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22792496543', 'Loção Tônica Facial Nupill 60Ml', 'Tônico facial enriquecido com Vitamina B5 Os cuidados com a pele começam sempre com a limpeza. Mas, outro passo importante, é tonificar o rosto. O Tônico Facial Nupill Firmness Intensive tonifica, hidrata, higieniza e prepara a pele para a aplicação do creme antirrugas e antissinais de sua rotina de cuidados e beleza para pele. É o último passo da limpeza que fecha os poros mantendo sua pele limpa e protegida, livre de impurezas. Enriquecido com PróVit. B5, ou ácido pantotênico mais conhecido como PANTENOL, muito famoso pela sua ação anti-inflamatória e por promover renovação da pele. Formulada com Aloe Vera (derivado da babosa) que ajuda a sua pele reter a hidratação natural sem agregar oleosidade. Disponível nos tamanhos 200 e 60ml. Modo de uso: Use pela manhã e de noite como parte de sua rotina de cuidado facial. Aplique o produto com algodão, fazendo movimentos circulares e ascendentes. Em seguida use um creme hidratante facial Nupill. #html-body [data-pb-style="646BA652F2E48"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA652F2E5E"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 21.21, 21.21, NULL, 'Beauty > Skincare > Toner', 'https://cf.shopee.com.br/file/sg-11134201-7rbnj-lmhzngjr2yqh0b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F22792496543', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20498989558', 'Esfoliante Facial Ricca Bastão', 'O bastão esfoliante Ricca, O Poderoso Carvão!, Traz a combinação perfeita de carvão com tomate, que além de auxiliar no controla da oleosidade, elimina as impurezas e células mortas, com uma esfoliação suave e sem ressecar a pele!', 72.68, 72.68, NULL, 'Beauty > Skincare > Face Scrub & Peel', 'https://cf.shopee.com.br/file/sg-11134201-7rbkq-lmhgat05yhbt85', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F20498989558', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
