INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21199663312', 'TV LED Smart Philco PTV24G5YR2CP 24"', 'A Smart TV 24" LED da Philco é a escolha perfeita para quem busca qualidade de imagem e uma experiência de entretenimento completa. Com uma tela de 24 polegadas e tecnologia DLED, você poderá desfrutar de suas séries e filmes favoritos com uma resolução HD nítida e vibrante. O design elegante na cor preta se adapta a qualquer ambiente, tornando-a uma adição estilosa à sua casa.Equipado com o sistema operativo Roku OS, este modelo oferece acesso fácil a uma variedade de aplicativos integrados, como Netflix, Prime Video, Apple TV, Disney+ e YouTube. Com duas portas HDMI e uma porta USB, você pode conectar facilmente seus dispositivos e aproveitar uma experiência de visualização personalizada. Além disso, a TV conta com conectividade Wi-Fi, permitindo streaming sem complicações.A TV Philco também possui assistentes virtuais integrados, como Alexa e Google Assistant, que facilitam o controle por voz e a interação com outros dispositivos inteligentes em sua casa.', 999.9, 999.9, NULL, 'Home Appliances > TVs & Accessories > TVs', 'https://cf.shopee.com.br/file/sg-11134201-825ax-mqz2oy586k9132', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050213612%2F21199663312', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
