INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21699256057', 'Mochila Infantil Zoo Gatinha Skip Hop', 'A Mochila Infantil Zoo Gatinha Skip Hop é ideal para passeios e pré-escola. Ela tem um compartimento principal espaçoso com um forro fácil de limpar e etiqueta de identificação interna. Guarde os lanches no bolso térmico frontal e coloque a caixinha de suco ou garrafa de canudo no bolso lateral de rede. Suas alças são acolchoadas e ajustáveis. Venha conhecer essa coleção e nossos personagens divertidos. ESPECIFICAÇÕES: - Idade indicativa: 3 anos+; - Contém um bolso frontal com fechamento em zíper e dois bolsos laterais sem fecho; - Uma alça de mão e duas alças de costas; - Fechamento da mochila em zíper. MATERIAL: - 97% poliéster 3% espuma de polietileno. MEDIDAS: - 27,94 x 12,7 x 30,48 cm. LIMPEZA E MANUTENÇÃO: - Limpeza localizada com pano úmido e sabão neutro ou lave à mão com água fria e sabão neutro e seque na horizontal. SOBRE A MARCA: Skip Hop é uma marca americana, criada em 2003, focada em design e criação de produtos para pais, bebês e crianças. O desafio é sempre fazer o melhor para seus consumidores, por isso a Skip Hop repensa e reenergiza produtos essenciais de bolsa maternidade a carrinho de bebê e brinquedos de banho para dar aos pais, bebês e crianças um design inteligente e verdadeira funcionalidade.', 269.9, 269.9, NULL, 'Baby & Kids Fashion > Baby & Kids Accessories > Bags & Luggage', 'https://cf.shopee.com.br/file/sg-11134201-7rd6d-lvcb4m5y5owz6f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1240688238%2F21699256057', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
