INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22792560039', 'Chocolate em Gotas 63% Cacau Amargo Bahia - Unique - 400g - 01 Unidade - Harald - Rizzo', 'Chocolate em Gotas 63% Cacau Amargo Bahia - Unique - 400g - 01 Unidade - Harald - Rizzo Chocolates Unique são indicados para fazer brigadeiros gourmets, brownies e outras sobremesas. Para o preparo de bombons, tabletes e ovos de páscoa, lembre-se que é necessário o processo de têmpera. Os chocolates Unique são produzidos com liquor e manteiga obtidos a partir de amêndoas de cacau com origem controlada e rastreada do Brasil, garantindo características particulares de seu terroir. Sugestão de Harmonização - Unique ao leite 63% cacau combina muito bem com frutas cítricas, como laranja, a tangerina e o cupuaçu. O sabor picante das pimentas aromáticas e as bebidas como licores e Vinho do Porto também oferecem excelentes combinações. Cacau de Origem Bahiana. Ingredientes: Açucar, manteiga de cacau, leite integral em pó, massa de cacau, leite desnatado em pó e emulsificante: lecitina de soja. ALERGICOS CONTÉM DERIVADOS DE LEITE E SOJA. CONTÉM LACTOSE. NÃO CONTÉM GLÚTEN.', 166.9, 166.9, NULL, 'Food & Beverages > Snacks > Chocolate', 'https://cf.shopee.com.br/file/sg-11134201-7rbn6-lmym8svod2qr05', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400124163%2F22792560039', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
