INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56101734668', 'Jogo Stop Criança Familia Educativo Diverção Brinquedo', 'Jogo STOP – Pais & Filhos Diversão, rapidez e muito raciocínio! O Jogo STOP da Pais & Filhos é o clássico desafio de palavras que coloca toda a família para pensar. Escolha uma letra e escreva o mais rápido possível palavras que se encaixem nas categorias do tabuleiro — mas corra, porque quem terminar primeiro grita “STOP!” Um jogo educativo e superdivertido que estimula a memória, concentração e vocabulário, perfeito para brincar com amigos ou em família. Ideal para todas as idades, o STOP é garantia de risadas e aprendizado em cada rodada! Características do produto: Marca: Pais & Filhos Modelo: STOP – Jogo de Palavras Estimula agilidade mental, concentração e vocabulário Ideal para jogos em grupo e momentos em família Pode ser jogado por crianças e adultos Material resistente e colorido Um clássico que nunca sai de moda! Por que escolher o Jogo STOP Pais & Filhos? Porque é o jogo perfeito para aprender se divertindo, promovendo interação, raciocínio rápido e muita competição saudável', 45.9, 45.9, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/sg-11134201-821cy-mh9ar13ydxcb64', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404144117%2F56101734668', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
