INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23094710787', 'Kit 2 Vasos para Plantas Bojo Escovado 1,2 com Prato Coletor', 'Kit 2 Vasos para Plantas Bojo Escovado 1,2 com Prato Coletor 🚀 ENVIO IMEDIATO GARANTIA DE 90 DIAS !! Renove seu ambiente com este conjunto premium de vasos escovados e texturizados! Combinando design moderno, resistência e leveza, eles são perfeitos para realçar a beleza de qualquer espaço, seja interno ou externo. ✨ O que você recebe? ✔️ 1 Vaso Bojo N1 ✔️1 Vaso Bojo N2 ✔️ Pratos coletores inclusos – Mais praticidade para você! Dimensões Vaso Bojo N1: - Altura: 19cm - Largura maior (Boca): 25cm - Profundidade menor (Fundo): 17cm - Peso: 0,4Kg Dimensões Vaso Bojo N2: - Altura: 26cm - Largura maior (Boca): 34cm - Profundidade menor (Fundo): 23cm - Peso: 0,9Kg 💎 Por que escolher nossos vasos? ✅ Estilo e requinte – Acabamento impecável que imita a sofisticação da cerâmica ✅ Versatilidade total – Para áreas internas e externas, valorizando qualquer ambiente ✅ Material ultra resistente – Feitos em polietileno de alta qualidade, suportam sol, chuva e impactos sem perder a cor ✅ Super leves e fáceis de transportar – Diferente dos vasos de cerâmica, sem risco de quebrar! ✅ Proteção garantida – Resistentes à umidade, maresia e não proliferam fungos e bactérias ✅ Durabilidade incomparável – Não desbotam, não racham e mantêm sua beleza por muito mais tempo ⚠️ Atenção: As cores podem apresentar pequenas variações conforme a tela do seu dispositivo. Plantas e flores das imagens são meramente ilustrativas. 🌟 Garanta agora o seu kit exclusivo e transforme sua decoração com elegância e praticidade!', 82.0, 67.9, NULL, 'Home & Living > Gardening > Pots & Planters', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjtyyttz2yv5e1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F608615567%2F23094710787', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54057463895', 'Mangá - Alice in Borderland - BIG - Vol. 08 - por Haro Aso - Editora JBC ISBN 9788545716129', 'Alice in Borderland - BIG - Vol. 08 Os mistérios de Borderland finalmente começam a vir à tona!Com os jogos chegando ao fim, os moradores de Borderland cada vez mais buscam descobrir o que é aquele mundo. Em uma partida decisiva contra um dos representantes de Borderland, Chishiya descobre o passado daqueles que agora organizam os jogos, colocando em risco sua vida e tudo aquilo em que acredita. Autor(es): Haro Aso ISBN: 9788545716129, 978-85-457-1612-9 Check-List: Maio/2026 Editora: JBC Número de páginas: 360 Lombada/Encadernação: Quadrada Tipo de capa: Cartão Data de Lançamento: 28/05/2026 Idioma: Português Condição: Novo/Lacrado', 73.9, 73.9, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-8260b-mm24n0pslzpcd8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F642933481%2F54057463895', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29439452693', 'Mangá - Dandadan 16 - Novo/Lacrado - Editora Panini', 'Dandadan 16 Momo e Okarun pedem ajuda à Velha Turbo pra identificar quem pegou a bola dourada da cabine de polícia e apesar da invasão ser um sucesso, o plano fracassa pois a Velha Turbo não sabe como acessar o computador que contêm a informação! Quando a dupla está pensando numa nova tentativa, dão de cara com Rokurou, o Serpiano! Com essa ajuda pra lá de inusitada, Momo e Okarun conseguem a informação do paradeiro da bola dourada!! Tipo de Produto: Revista Segmentos: Mangás Marcas: Planet Manga Autor(es): Yukinobu Tatsu Check-List: Setembro/2025 Classificação Etária: 14 anos Editora: Panini Editora Original: Shueisha Gênero: Comédia, Ficção Científica, Mistério, Sobrenatural Indicação: Jovens Maduros - Ensino Médio/Universitário Demografia: Shonen Número de páginas: 194 Tipo de capa: Capa Cartão Data de Lançamento: 21/09/2025 Idioma: Português Condição: Novo/Lacrado', 51.9, 51.9, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mf2w2m29ts0667', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F642933481%2F29439452693', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29493601408', 'Comics - Dylan Dog omnibus vol. 4 - Mythos Editora ISBN 9786559517619', 'Dylan Dog omnibus vol. 4 Achuva cai na noite de Londres. Uma chuva eterna e escura que se mistura ao sangue e à solidão. O homem invisível escreve seu diário, enquanto a lâmina do assassino continua a golpear. As prostitutas da grande cidade estão no olho da morte, e uma delas, Bree Daniels, recorre ao Investigador do Pesadelo. Para Dylan é o início de um grande amor e de uma investigação ao longo da fronteira entre homens e monstros, visíveis e invisíveis... enquanto a chuva continua a cair. Autor(es): Alfredo Castelli, Luigi Mignacco, Marcello Toninelli, Tiziano Sclavi ISBN: 9786559517619 Check-List: Novembro/2025 Editora: Mythos Editora Número de páginas: 596 Tipo de capa: Cartão Data de Lançamento: 30/11/2025 Idioma: Português Condição: Novo/Lacrado', 172.9, 172.9, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-821eq-mh3ysvp5qlfw20', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F642933481%2F29493601408', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29985345225', 'Livro 3 Palavrinhas Bíblia do Bebê Capa Dura', 'Que tal apresentar aos pequenos as emocionantes histórias da Bíblia? As histórias cuidadosamente selecionadas e ricamente ilustradas apresentarão a eles mensagens de fé e amor. Ao longo dessas histórias, eles encontrarão ensinamentos simples, breves orações, além de QR codes para assistirem aos clipes favoritos da turma do 3 Palavrinhas. Descobrir a Palavra de Deus pode ser incrivelmente divertido! Os pequenos vão aguardar ansiosamente por esses momentos especiais em que vocês poderão compartilhar juntos as maravilhas da Bíblia. Acabamento: capa dura Páginas: 48', 23.9, 23.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rfhm-m95ahx7arzjb2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F29985345225', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52257631649', 'Bíblia Sagrada | Letra Jumbo | ARC com Harpa | Palavras de Jesus em Vermelho | Luxo Pink', 'A Bíblia perfeita para quem busca conforto na leitura e beleza em cada detalhe. Com letra jumbo, essa edição foi pensada para proporcionar uma experiência agradável, tornando a leitura mais leve e acessível no dia a dia. A tradução ARC (Almeida Revista e Corrigida) preserva a fidelidade ao texto bíblico, ideal para quem valoriza profundidade e tradição. As palavras de Jesus destacadas em vermelho trazem ainda mais clareza e conexão durante a leitura, enquanto a inclusão da Harpa Cristã torna essa Bíblia completa para momentos de devoção, louvor e edificação espiritual. Seu acabamento luxo agrega sofisticação, sendo uma excelente opção tanto para uso pessoal quanto para presentear alguém especial com algo significativo e duradouro. Uma Bíblia completa, elegante e feita para te acompanhar em todos os momentos com Deus. Detalhes: Titulo: Bíblia Sagrada | Letra Jumbo | ARC com Harpa | Palavras de Jesus em Vermelho | Luxo Editora: Publicações Cordeiro Acabamento: Capa luxoTamanho: 20 x 25 Tradução: ARC Harpa: Sim Índice: Destacado em FULL Collor Paginas: 1080', 64.9, 59.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-820lk-mm7mavnwkoav95', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F52257631649', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22999029765', 'Pneu MTB Chaoyang Phantom Dry Aro 29x2.20 2c Kevlar Tubeless', '================== DESCRIÇÃO DOPRODUTO ================= Pneu Chaoyang Phantom Dry Aro 29x2.20 2c Kevlar Tubeless Mtb Para suas condições gerais de tempo seco, escolha Phantom Dry. Possui cravos de altura média fornece grande tração e controle durante a frenagem. Cravos apertados no centro para minimizar a resistência ao rolamento, espaço aberto no ombro dá segurança e estabilidade através do canto. =============== ESPECIFICAÇÕES =============== - Marca: Chaoyang - Modelo: Phantom Dry - Modalidade: Mountain Bike, Cross Country entre outras- Medida: 29 x 2.20 (56 -622) - Calibragem: 23-50 PSI- TPI: 60 - Peso Aproximado: 749 gr - Cor: Preto TecnologiasDual Compound (2c-Mtb), composto duplo (lateral mais reforçada que os kevlar comuns)Tr - Tubeless ReadyProduto novo, original, adquirido no fornecedor oficial da marca no Brasil. ITENS INCLUSOS 1x Pneu OBSERVAÇÃO: Fotos meramente ilustrativas. As especificações estão sujeitas a alterações sem aviso prévio, podendo variar com base na disponibilidade de componentes e outros fatores. ================ ENVIO DO PRODUTO ================ Seu produto será enviado em ATÉ 24 horas úteis após a confirmação do pagamento. =========== NOTA FISCAL =========== Todos os nossos produtos são enviados com nota fiscal em seu nome e via transportadoras parceiras. ==== SAC ==== O suporte ao cliente é um dos nossos compromissos! Após a aprovação da compra você terá acesso aos nossos contatos, e poderá contar com todo o apoio da nossa equipe de atendimento.', 249.0, 142.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfwuo5wy15hj31', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.