INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22197036346', 'Filtro Ar Toyota Corolla 1992 a 2001 - 7544 - JFA0249', 'Filtro Ar Toyota Corolla 1992 a 2001 7544 JFA0249 (GLI) - Motor 1.6 16v /(LE/WG/SE-G/XEI/XLI) - Motor 1.8 16v /(LE) - Motor 2.2 16v Após passar pelo filtro, o ar é aspirado pelo motor através de seus êmbolos (pistões). Durante este processo, sensores do sistema de injeção eletrônica enviam sinais para o Módulo da Injeção Eletrônica do Veículo, informando a temperatura do ar que está sendo admitido. O filtro do ar é construído para que as impurezas em suspensão no ar sejam separadas, ficando as mais pesadas depositadas no fundo da caixa de filtração e as mais leves sendo retidas pelo elemento filtrante.', 53.69, 53.69, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-825ao-mq1yxybawr9df0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22197036346', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198826673', 'Verniz Acrilico Coral 18L', 'Nome : Verniz Acrílico Coral 18 Litros Marca: Coral Modelo: Verniz Acrilico Tipo: Verniz Volume: 18L Rendimento Acabado: 120m² Superficie: Parede Aerosol: NãoInformações Acabamento Brilhante Rendimento 15 m²/L Secagem ao toque Ao toque: 2h Entre demãos: 4h Final: 4h Número de demãos 2 Características do produto Alta resistência e poder de preenchimento Descrição do Produto O Verniz Acrílico deve ser utilizado para dar maior proteção e melhor acabamento às paredes externas e internas de concreto, pedra mineira, ardósia e tijolo à vista. Possui resistência à alcalinidade, à ação da maresia e também ao sol e à chuva. É diluível em água e, quando seco, fica incolor, proporcionando maior brilho, beleza e facilidade para limpar a superfície. Uma lata de 18L pinta até 275m² por demão. Materiais de aplicação Rolo de lã de pelo baixo, pincel ou trincha.', 452.55, 452.55, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/br-11134275-7r98o-mcmaxqd23ls1c4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F717380864%2F22198826673', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594201572', 'Mini Grill E Sanduicheira Philco Inox Preto 750W 220V', 'Mini Grill E Sanduicheira Philco Inox Preto 750W 220V Com seu Design moderno em aço escovado, o Mini Grill e Sanduicheira Philco Inox Preto 750W é ótimo para você que gosta de comida rápida saborosa! Grelha hambúrgueres, carnes, peixes, vegetais e prepara deliciosos sanduíches. Com espaço suficiente para preparar alimentos para duas pessoas; Conte com 750W de potência para preparar seus sanduiches e grelhados em menos tempo! Leve e compacto, suas chapas onduladas com revestimento antiaderente garantem também praticidade; Possui luz indicadora de aquecimento e funcionamento para facilitar no monitoramento e segurança; 2 em 1 para preparar refeições gostosas, rápidas e mais saudáveis. O Mini Grill e Sanduicheira Philco Inox Preto 750W foi feito para você! Principais Características: - Chapas onduladas com revestimento antiaderente - Pode ser usado como grill ou sanduicheira - Acabamento em aço escovado - Trava de fechamento e armazenamento - Base antiderrapante - Porta cordão - Luz indicadora de funcionamento - Composição Metal e Baquelite. Especificações Técnicas: Marca: Philco Cor: Preto Estado: Novo Potência (W): 750W Trava de fechamento: Sim Revestimento da chapa: Antiaderente Altura do produto: 25,1 cm Largura do produto: 25,5 cm Comprimento do produto: 11,2 cm Peso do produto: 1,24 kg Altura com embalagem: 25,1 cm Largura com embalagem: 25,5 cm Comprimento com embalagem: 11,2 cm Peso com embalagem: 1,24 kg Garantia (Dias): 360 Observação: Somente faturamos para o nosso consumidor final, ou seja, não faturamos pedidos para CNPJ por este portal de vendas;', 164.9, 164.9, NULL, 'Home Appliances > Kitchen Appliances > Toasters', 'https://cf.shopee.com.br/file/sg-11134201-7rdwi-mbww8abvb1w657', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F23594201572', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
