INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45161278029', 'Noites Brancas | Fiódor Dostoiévski', 'Em Noites Brancas, Dostoiévski nos apresenta um sonhador solitário que vaga pelas ruas de São Petersburgo até encontrar alguém que transforma, por algumas noites, sua forma de enxergar a vida. Uma história delicada sobre amor, esperança e os encontros que marcam para sempre. Quando a cidade parece suspensa entre sonho e vigília, um jovem solitário encontra, por acaso, alguém que também carrega no coração a esperança e a espera. Em poucos encontros, entre confidências tímidas e promessas sussurradas, nasce uma ligação frágil e intensa. Mas, a realidade, silenciosa e inevitável, aproxima-se com a mesma suavidade da madrugada. Uma história delicada sobre solidão, desejo e instante fugaz em que dois destinos quase se tornam um. Título: Noites Brancas | Fiódor Dostoiévski Autor: Fiódor Dostoiévski Páginas: 96 Formato: 17 X 24 cm Edição: 2026 Capa: Brochura Peso: 0,250 kg ISBN: 9788595205741 Editora: Pé da Letra', 14.9, 14.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-823on-mor643xq7h1e83', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F45161278029', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
