INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20797672230', 'Tampa Reservatório Expansão Gm Kadett 1989 a 1997 - 111762 - 24032', 'Tampa Reservatório Expansão Gm Kadett 1989 a 1997 111762 24032 TODOS (1,4 BAR) TAMPA AMARELA Além de fechar o reservatório de expansão, esta tampa também mantém a pressão do sistema, através de uma válvula que se abre, dando passagem ao excesso de pressão. O controle da pressão faz com que o líquido tenha uma circulação completa, atingindo todos os pontos do motor, tenha um ponto de ebulição mais elevado, impede a formação de vapor no interior do motor, permite a entrada de ar atmosférico quando a temperatura do líquido abaixa.', 25.87, 25.87, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd46-lufakzewt477ad', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20797672230', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
