INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9524481418', 'Cápsula Chocolate Quente Bicafé Compatível Máq. Dolce Gusto* 16 Cápsulas Cremoso', 'CHOCOLATE QUENTE BICAFÉ COMPATÍVEL COM MÁQUINAS DOLCE GUSTO* Desfrute de um delicioso chocolate quente cremoso, com sabor intenso e textura aveludada. Uma bebida reconfortante, perfeita para os dias mais frios ou para qualquer momento em que você deseja uma pausa saborosa. Compatível com máquinas Dolce Gusto®, utiliza apenas 1 cápsula por preparo, oferecendo praticidade e excelente rendimento. BENEFÍCIOS ✔ Chocolate quente cremoso ✔ Textura aveludada e sabor marcante ✔ Espuma cremosa e aromática ✔ Compatível com máquinas Dolce Gusto® ✔ 16 cápsulas = 16 bebidas ✔ Produzido em Portugal ✔ Não contém glúten ✔ Produzido com energia limpa ESPECIFICAÇÕES • Marca: Bicafé • Tipo: Chocolate Quente • Compatibilidade: Máquinas Dolce Gusto® • Quantidade: 16 cápsulas • Rendimento: 16 bebidas • Peso líquido: 256g • Preparado à base de leite e cacau INGREDIENTES Açúcar, cacau em pó, xarope de glicose, gordura de coco, leite em pó, soro de leite em pó, amido de batata, sal, espessante, aroma, estabilizante e emulsionante. MODO DE PREPARO Utilize conforme as instruções da sua máquina Dolce Gusto®. Conservar em local fresco e seco. CONTEÚDO DA EMBALAGEM • 1 Caixa com 16 cápsulas de Chocolate Quente Bicafé Compatíveis com Dolce Gusto®', 53.9, 45.82, NULL, 'Food & Beverages > Beverages > Chocolate Drinks', 'https://cf.shopee.com.br/file/br-11134207-7r98o-loe86lcb6h7t6c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F392614369%2F9524481418', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
