INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22792524005', 'Filtro Gasolina OMEGA 1999/2004 - 43656 - FCI1660', 'Filtro Gasolina OMEGA 1999/2004 (Australiano) - Motor 3.8 V6 Gasolina - (Automático/Mecânico) (Plástico) O Filtro do combustível retém impurezas contidas no combustivel. O Filtro possui um elemento de papel filtrante. Por este motivo, a direção de fluxo indicada no filtro deve ser obrigatoriamente mantida. O filtro é fixado na carcaça (de metal), através de uma placa de apoio. A troca do filtro deve ser feita integralmente, a sua vida útil depende da quantidade de impurezas contida no combustível e varia de acordo com as quilometragens indicadas nas publicações.', 27.11, 27.11, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbne-lmqg43xa3ctl43', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22792524005', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22692567139', 'Bóia Tubular Fiat Uno 1989 a 2005 - 179142 - T060004', 'Bóia Tubular Fiat Uno 1989 a 2005 179142 T060004 MILLE - Combustível: Gasolina (Com RETORNO/PARAFUSO) 60MM A boia tubular de combustível funciona em conjunto com indicador, normalmente localizado no painel. A boia no interior do tanque realiza a medição do nível de combustível de forma eletromagnética e transforma essa medição em um sinal que é enviado ao indicador, interpretando o sinal, o transformando na indicação através do ponteiro no mostrador, auxiliando no monitoramento e controle da quantidade de combustível.', 182.34, 182.34, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7ravr-maar3bximofodd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22692567139', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
