INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20077394221', 'Alicate para Anéis 19-60mm Interno Reto 7" Tramontina PRO 44008/107', 'Alicate para Anéis Interno Reto 7" Tramontina PRO 44008/107 Descrição do Produto: - Colocar e retirar anéis de equipamentos fica mais fácil com o alicate de anéis da Tramontina PRO. Maior resistência, conforto e segurança em suas mãos. Os alicates de corte são testados quanto à resistência ao desgaste do gume de corte em máquina de ensaio específica. Essa ferramenta possui dureza diferenciada no gume de corte e no corpo e são testadas com relação à aderência das empunhaduras de PVC. Além disso, um ensaio de extrema importância analisa o grau de isolação do revestimento aplicado sobre os cabos dos alicates isolados, e que promove segurança na sua utilização em locais com tensões de até 1.000 V CA. Vantagens: - Bico reto; - Forjado em aço cromo vanádio. - Acabamento fosfatizado; - Têmpera total no corpo; - Cabos com revestimento especial; - DIN 5256; - Ideal para puxar, prender, enrolar, deformar e cortar arames e chapas finas. Dados Técnicos: - Modelo: 44008/107; - Capacidade: 19 a 60mm; - Peso: 0,19kg; - Dimensões do produto: 187x53x13 mm; - Dimensões conforme a imagem: A: 5.0 mm; B: 187.0 mm; C: 13.0 mm; D: 53.0 mm; E: 1.8 mm. Componentes inclusos na embalagem: - 1 Alicate para Anéis Interno Reto 7" Tramontina PRO 44008/107.', 93.0, 65.1, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7qve5-lf5rir2wn1zg22', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F397583038%2F20077394221', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207138302', 'Conjunto Longo Infantil Menino Esportes Elian Amarelo', 'O Conjunto Elian é composto por blusão e calça em moletom felpado. O blusão possui punhos nas mangas e barra para um ajuste confortável ao corpo, enquanto sua estampa divertida e moderna traz o tema de esportes para o dia a dia dos meninos. Já a calça conta com elástico no cós, punho nas barras e recorte lateral. Ideal para passeios e momentos de lazer, aposte nesse look cheio de atitude para completar o guarda-roupa infantil!Detalhes da peça: • Conjunto composto por blusão e calça • Feito em moletom felpado • Possui mangas longas • Estampa com tema de esportes • Elástico no cós • Ideal para passeios e momentos de lazer', 119.9, 83.93, NULL, 'Baby & Kids Fashion > Boy Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-8259h-mr1trokdm51dcd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F58207138302', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993053589', 'Fogareiro Fogão Camping E Pesca A Gás Slim Azul Kala', 'Fogareiro Fogão Camping E Pesca A Gás Slim Azul Kala: Cozinhe em Qualquer Lugar com Facilidade! Procurando por uma solução prática e eficiente para suas aventuras ao ar livre? Apresentamos o Fogareiro Kala Dobrável a Gás Slim, uma peça indispensável para quem ama acampar, fazer trilhas, pescar ou simplesmente passar um tempo na natureza! Fogareiro Kala Slim de uma boca é feito para você aventureiro ou caseiro, é ideal para uso em casa ou para uso em camping. Ele vem também com uma prática bolsa de transporte para você armazená-lo e carregá-lo com segurança. ESPECIFICAÇÕES Modelo: Kala Fogareiro Dobrável Slim Consumo de gás: 120g/h Peso: 1,4kg OUTRAS CARACTERÍSTICAS: Ignição automática; Possui ajuste fino de chama; Base para panela com pintura enamel; Pintura automotiva epóxi, facilita a limpeza; Potência: 2600W; Consumo de Gás: 120g/h; Dimensões Aberto: 275 x 325 x 100 mm; Dimensões Fechado: 250 x 83 x 110 mm;', 419.89, 419.89, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Camping & Hiking', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lvt58biel2w660', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F320275364%2F23993053589', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
