INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26259919950', 'Dr.Jart Premium BB Beauty Balm SPF 50 (Fair Light), 40ml', 'Maquiagem e FPS 50 em um. Este Creme BB Cream de próxima geração não apenas uniformiza o tom da pele; ele também hidrata, melhora a barreira e protege a pele. Multitarefa final para um visual de maquiagem sem maquiagem. O que diz que deixa um acabamento natural semelhante a me 96% disseram que o tom da pele parece uniforme 97% disseram que a pele fica hidratada 96% disseram que é sem peso na pele 97% disseram que não deixou um elenco branco A pele disse que a pele parece mais suave Teste do consumidor em 114 mulheres após o uso do produto por 3 dias. O que o torna único: Este híbrido é embalado com potentes ativos para cuidados com a pele, como Niacinamida e Glicerina. O creme macio cushiony espalha perfeitamente sobre a pele deixando você com uma tez radiante e com um acabamento semelhante a você. Ele vem em 4 tons que se estica em uma gama de tons de pele, facilitando a escolha da que está certa para você. O que há nele: O Niacinamida 2% para melhorar a barreira da pele. Glicerina 5% para umidade instantânea. Protetores solares minerais e químicos para proteção SPF 50 de amplo espectro contra raios UVA e UVB.', 222.14, 212.0, NULL, 'Beauty > Makeup > Face', 'https://cf.shopee.com.br/file/sg-11134207-7rdwu-lzssm7f1azqa63', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F26259919950', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
