INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204291844', 'Ribbed Legging Bege Camélia Poliamida', 'Ribbed Legging Bege Camélia | Tendência Minimalista Estruturada e elegante! A Ribbed Legging Bege Camélia da Donna Carioca apresenta textura canelada que está em alta nas passarelas, com recortes estratégicos na cintura que valorizam sua silhueta enquanto proporcionam sustentação e estrutura. Tecnologia Premium Excelência em Materiais Textura Canelada - Tecido em alta que adiciona interesse visual e estrutura Recortes Estratégicos na Cintura - Detalhes posicionados para silhueta valorizada e sustentação Costura Reforçada - Construção durável para atividades intensas Modelagem que Abraça - Abraça seu corpo sem restringir movimento Design Exclusivo Cor Bege Camélia - Tom neutro sofisticado para styling versátil Tag Personalizada - Detalhe personalizado para caráter exclusivo Estrutura Minimalista - Linhas limpas que focam na textura e caimento Não Possui Forro - Tecnologia zero transparência COMPRE AGORA - Textura em alta para seu guarda-roupa!', 155.44, 155.44, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Bottoms', 'https://cf.shopee.com.br/file/sg-11134201-825zq-mk2dkd0gv4ecde', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1576910750%2F58204291844', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
