INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '24020918183', 'MEDIPEEL Peptide 9 Volume Leaf Tox Eye Cream, 20 ml', 'MEDIPEEL Peptide 9 Volume Leaf Tox Eye Cream, 20 ml - Solution For Aging and tired skin - Product Function Reduces appearance of fine lines and wrinkles. Revitalises tired and dry skin - How to use Take an appropriate amount and place some contents around your eyes. Move back and forth around the eyes and gently absorb the contents. - Product Benefits Wrinkle Care: Expertly targets wrinkles around the eyes, providing effective wrinkle improvement. Dual Functional Cosmetics: Acts as both a whitening and wrinkle-improving solution. Rich Nutrition: Nourishes delicate areas such as wrinkled and drooping eyes, laugh lines, and forehead wrinkles. Mess-Free Application: Designed for easy application directly onto the eyes without the need to use your hands. - Ingredients Purified Water, Cetylethylhexanoate, Salvia Extract, Glycerin, Niacinamide, Dipropylene Glycol, Polyglyceryl-3 Methyl Glucose Distearate, Cyclohexasiloxane, Cetearyl Alcohol, Stearic Acid, 1 ,2-hexanediol, Olive Oil, Shea Butter, Panthenol, Zinnia Mushroom Extract, Adlay Seed Extract, Salmon Roe Extract, Butylene Glycol, Calmeg Extract, Carnosine, Hydrolyzed Soybean Protein, Acetyl Hexapeptide-8 (10 ppb), Copper Tripeptide-1 (10 ppb), Palmitoyl Pentapeptide-4 (10 ppb), Tripeptide-1 (10 ppb), Palmitoyl Tripeptide-1 (10 ppb), Hexapeptide-9 (5 ppb), Nonapeptide-1 (1 ppb), Palmitoyl Tetrapeptide-7 (50 ppb), Palmitoyl Tripeptide-5 (11 ppb), Edelweiss Callus Culture Extract, Green Tea Extract, Centella Asiatica Extract, Spanish Licorice Root Extract, Golden Extract, Rose Hip Root Extract, Matricaria Flower Extract, Rosemary Leaf Extract, Lactobacillus/Soybean Fermented Extract, White Willow Bark Extract, Cinnamon Bark Extract, Oregano Leaf Extract, Cypress Leaf Extract, Purslane Extract, Hydro Genated Polyisobutene, Zemo Root Extract, Hydroxypropyltrimonium Hyaluronate, Sodium Acetylated Hyaluronate, Hydrolyzed Hyaluronic Acid, Hyaluronic Acid, Sodium Hyaluronate Crosspolymer, Hydrolyzed Sodium Hyaluronate, Potassium Hyaluronate, Hydrolyzed Collagen, Royal Jelly Extract, Argan Kernel Oil, Squalane, Ceramide NP, Tocopheryl Acetate, Adenosine, Disodium EDTA, Betaine, Sodium Hyaluronate, Carbomer, Ethylhexylglycerin, Glyceryl Stearate, Tromethamine, Sodium Polyacrylate, Ethylhexyl Stearate, Trideceth-6, Pentylene Glycol, Caprylyl Glycol Col, Hydroxyacetophenone, Dipotassium Glycyrrhizate, Fragrance - Volume: 20ml Made in Korea', 108.0, 108.0, NULL, 'Beauty > Skincare > Eye Treatment', 'https://cf.shopee.com.br/file/sg-11134207-7rcd9-ltbuica1j9w391', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F24020918183', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26307137051', 'Missha Time Revolution Night Repair Ampoule Shep Mask, 1ea', 'Uma máscara de folha hidratante formulada com 50% Extreme Biome, que é composta por 10 diferentes ingredientes fermentados altamente concentrados. Oferece resultados visíveis à sua pele de forma rápida e eficaz. Melhora a elasticidade e nutre a pele. Certificado Vegano. Pegue uma grande quantidade da ampola e aplique suavemente ao longo das áreas desejadas da pele. Padre levemente para absorver. Dica da ponta: Prepita a pele com a primeira essência 5X para dar à ampola de reparo noturna um aumento extra!', 27.54, 27.54, NULL, 'Beauty > Skincare > Face Mask & Packs', 'https://cf.shopee.com.br/file/sg-11134207-7rdyl-lylxunh8a1fba7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F26307137051', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
