INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20599067428', 'Par Pino Trava Porta Dianteira Gol Parati Saveiro G2 4 Portas Com Haste', '🚀 ENVIO IMEDIATO — PRODUTO EM ESTOQUE NO BRASIL! ⚡ Envio ágil após a confirmação do pagamento. ⚙️ Substitua o pino de trava desgastado e recupere o funcionamento correto da porta. Ideal para reposição, garante acionamento preciso e acabamento alinhado ao padrão original. 🚗 Compatível com: Volkswagen – Gol G2 1994 a 2001 Volkswagen – Parati G2 1996 a 2001 Volkswagen – Saveiro G2 1997 a 1999 Aplicação apenas em modelos 4 portas ℹ️ Mais Informações: Cor: Preto Aplicação: Interna (porta dianteira) Material: Plástico ABS Alta durabilidade Excelente acabamento Produto novo, embalado e protegido 🏷️ Tags: #pinotrava #pinotravaporta #travaporta #pinogolg2 #pinoparati #pinosaveiro #golg2 #paratig2 #saveirog2 #gol1994a2001 #parati1996a2001 #saveiro1997a1999 #pecasvolkswagen #autopecasvw #reposicaoautomotiva #segurancaveicular #kyodaiacessorios', 46.2, 42.51, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/br-11134207-820l7-mpl4xxgcnqwz0b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373280378%2F20599067428', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22192849882', 'Mascara Capilar SOS Mandioca Fios Fortes Milcy 250G', 'Mascara Capilar SOS Mandioca Fios Fortes Milcy 250G A Máscara de Tratamento S.O.S Mandioca oferece uma experiência de cuidado capilar completa, promovendo máxima hidratação, extra brilho e auxílio no crescimento dos fios. Sua fórmula enriquecida com mandioca e linhaça proporciona benefícios multifuncionais para a saúde e beleza dos cabelos. Com a poderosa mandioca como ingrediente principal, esta máscara nutre profundamente os cabelos, fornecendo a umidade necessária para restaurar sua vitalidade e elasticidade. Além disso, a presença da linhaça confere propriedades antioxidantes, que ajudam a proteger os fios dos danos causados pelos radicais livres, enquanto auxilia na regeneração capilar, proporcionando cabelos mais fortes e saudáveis. O modo de uso simples e eficaz garante resultados visíveis desde a primeira aplicação. Primeiro, aplique o shampoo da linha, massageando delicadamente o couro cabeludo para remover impurezas e preparar os fios para o tratamento. Em seguida, aplique a máscara de tratamento S.O.S Mandioca, distribuindo uniformemente por todo o comprimento dos cabelos, e deixe agir de 3 a 5 minutos para potencializar os resultados. Por fim, finalize o tratamento aplicando o condicionador para selar as cutículas dos fios, proporcionando maciez, brilho e facilitando o pentear. Com essa rotina de cuidados, seus cabelos ficarão incrivelmente hidratados, radiantes e com um aspecto saudável. Experimente a Máscara de Tratamento S.O.S Mandioca e transforme seus cabelos em uma verdadeira expressão de beleza e vitalidade.', 28.52, 28.52, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rd5u-lu0zi4c19qoo50', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F385388689%2F22192849882', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22499306230', 'Rede De Dormir Descanso Com Mosquiteiro Camping 300kg Acampamento ao ar livre pesca ao ar livre', 'Tamanho expandido da rede L*W=260cm*140cm Rede de acampamento e feita de nylon para-quedas duravel, este para-quedas de nylon e mais resistente que o normal, mais facil de secar e tem um material mais respiravel. Poderia suportar ate 300 kg. Duas funcoes preparadas para voce? 1) Instale a rede mosquiteira para se proteger dos mosquitos e outros insetos; 2) Coloque o mosquiteiro embaixo da rede e use-o normalmente. Pesando apenas 690g, este hammok e pequeno para guardar. Adequado para a maioria das ocasioes? Esta rede portatil foi projetada especificamente para protege-lo de insetos menores, como mosquitos, tornando-o o item perfeito para atividades ao ar livre, como camping, caminhadas, viagens, mochila e assim por diante, funciona muito bem em qualquer ambiente, seja ao ar livre no interior ou entre dois postes ou duas arvores, para que voce possa se sentir confiante pendurado como um profissional. Todas as ferramentas de instalacao incluidas?: 1 * Rede de campismo com rede mosquiteira, 2 * mosquetoes de aco macico em forma de d, 2 *cordas para arvore, 1 * Bolsa de transporte. 100% Reembolso / Substituicao Gratuita? visa fornecer produtos premium, bem como atendimento rapido e eficiente aos nossos clientes. Oferecemos reembolso 100% / substituicao gratuita para esta rede de campismo, se voce nao estiver satisfeito. Com esta rede, voce tem tudo o que precisa para sair com total conforto em qualquer lugar! Utilizando materiais de alta resistencia e qualidade, ele e construido para durar uma vida inteira de aventuras, proporcionando conforto total. Leve e compacta quando dobrada, nossa rede de mochila e perfeita para camping, mochila, caminhadas, viagens, quintais, parques ou praias. PARAMETROS E RECURSOS: Rede de arvore com duas funcoes preparadas para voce? 1) Configure a rede mosquiteira para se proteger dos mosquitos e outros insetos; 2) Coloque a rede mosquiteira embaixo da rede e use-a como uma rede normal. Redes portateis de para-quedas (fabricadas com 100% Nylon de alta resistencia 210T, de secagem rapida e respiravel). Saco de material de cordao anexado para armazenamento compacto. peso total: 690g Dimensoes embaladas: 23cm (altura) x 14cm (largura) x 12cm (profundidade) 300 kg de estresse testados com capacidade maxima de peso.', 169.0, 89.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Camping & Hiking', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjt7xm2e0feu1c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1687489154%2F22499306230', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
