INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22499171966', 'Creme de Pentear Explosão de Azeite de Oliva + Óleo Capilar Explosão de Abacate e Oliva 55ml', 'O Creme de Pentear Explosão Azeite de Oliva promove umectação aos fios pois tem alto poder de nutrição, e devolve a oleosidade necessária para o comprimento e pontas saudáveis. Isso por que o Azeite de Oliva tem alta concentração de lipídeos e vitamina E, que garantem reposição de nutrientes essenciais para o cabelo, combatendo o ressecamento e pontas duplas enquanto repara as partes danificadas da fibra capilar. Cachos e crespos nutridos, macios e com brilho incrível! O Explosão de Óleos Abacate + Oliva é ideal para cabelos crespos, cacheados e ondulados. Nutre profundamente, controla o frizz, protege contra danos sem pesar os fios, além de entregar um brilho extraordinário. Possui proteção térmica e uma combinação de aromas que deixas os cabelos super perfumados.', 86.99, 50.69, NULL, 'Beauty > Hair Care > Hair Styling', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgqkq57aeneo84', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1202663615%2F22499171966', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19397683969', 'Colchão Solteiro (78x188) D20 Preto Valencia Topázio Colchões', 'Desfrute de noites de sono revigorantes com o Colchão Solteiro Valencia da renomada marca Topázio Colchões. Com suas dimensões generosas de 78x188x12 centímetros, é perfeito para quem busca conforto individualizado. Sua espuma D20 proporciona o suporte ideal para uma postura correta durante o sono, garantindo o descanso necessário para enfrentar o dia seguinte. O elegante revestimento preto em poliéster confere um toque de sofisticação ao ambiente, enquanto o tampo em poliéster proporciona uma superfície suave e agradável ao toque. Transforme seu quarto em um refúgio de tranquilidade e conforto com o Colchão Solteiro Valencia da Topázio Colchões. Informações técnicas Cor Predominante do Produto: Preto Dimensões do produto: Altura: 12,00cm; Largura: 78,00cm; Comprimento: 188,00cm Dimensões do produto com embalagem: Altura: 12,00cm; Largura: 78,00cm; Comprimento: 188,00cm Marca: Topazio Colchões Conteúdo da embalagem: 1 Colchão Solteiro Modelo: Valencia Garantia: 3 Meses do Fabricante Peso: 3,40Kg Densidade: D20 Tamanho: Solteiro Tipo de Colchão: Espuma Atenção: As CORES e/ou GRAVURAS dos colchões poderão sofrer alterações na sua tonalidade ou tipologia na parte facial do produto dependendo da disponibilidade do fornecedor.', 289.9, 289.9, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-7rd45-lvah5fk4pz3ebc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1060724397%2F19397683969', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
