INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21699676929', 'Kit 6 Cuecas Cotton Masculinas Academia - Alpha', '*NÃO É POSSÍVEL REALIZAR TROCAR DESTE ITEM Experimente o conforto definitivo com o Kit 6 Cuecas Cotton Masculinas Dry Academia Alpha, perfeita para quem busca uma peça íntima de qualidade superior que oferece suporte, maciez e liberdade em todas as situações do dia a dia. Desenvolvida em 96% algodão + 4% elastano, essa cueca proporciona toque extremamente macio, ventilação natural e flexibilidade que acompanha seus movimentos sem apertar, marcar ou incomodar. O algodão premium garante que sua pele respire livremente, mantendo a região íntima sempre fresca e seca, evitando irritações e desconfortos. Com modelo boxer de cintura baixa, entrega cobertura ideal e design moderno que valoriza o corpo masculino. Seja para o trabalho, academia, esportes ou momentos de lazer, essa cueca garante bem-estar o dia todo. Assim, você se sente confiante e confortável em qualquer atividade. Benefícios da cueca: - Modelo boxer: suporte adequado sem comprimir. - Cintura baixa: design contemporâneo e confortável. - Respirabilidade natural: mantém frescor e higiene. - Ajuste perfeito: não marca, não sobe e não aperta. - Resistência duradoura: qualidade que se mantém lavagem após lavagem. Se você quer investir em conforto real e qualidade que faz diferença todos os dias, a Cueca Boxer Alpha é essencial no seu guarda-roupa.', 215.94, 215.94, NULL, 'Men Clothes > Innerwear & Underwear > Underwear', 'https://cf.shopee.com.br/file/sg-11134201-824hq-mpvufh9vxlvm04', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1337417367%2F21699676929', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
