INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53255819198', 'Chuteira Puma Futsal Attacanto II IT BDP Preto e Branco - Masculino', 'Controle, agilidade e conforto para dominar o futsal! Chuteira Puma Futsal Attacanto II IT BDP Preto e Branco - Masculino Ficha Técnica: Marca: Puma Cor: Preto com branco Cabedal: Material sintético resistente Gênero: Masculino Palmilha: EVA forrada e macia Sola: Borracha antiderrapante Fechamento: Cadarço Amortecimento: Leve Estabilidade: Neutro Tecnologias: Solado emborrachado para máxima tração e aderência em quadras Altura do salto: 2,5 cm Tipo de bico: Redondo Ocasião de uso: Jogos de futsal e treinos indoor Detalhes: Reforço acolchoado no calcanhar, lingueta flexível, ajuste firme e confortável A Chuteira Futsal Puma Attacanto II IT oferece a performance que todo jogador indoor precisa. Porque investir: Com cabedal sintético de alta durabilidade, palmilha forrada e solado com tração eficiente, ela entrega agilidade e estabilidade nos lances decisivos. O reforço acolchoado garante segurança nos movimentos rápidos e cortes laterais. Tudo com o estilo esportivo da Puma. Conteúdo da embalagem: 1 par de Chuteira Puma Futsal Attacanto II IT BDP Preto e Branco – Masculino', 349.99, 276.99, NULL, 'Sports & Outdoors > Sports Footwear > Futsal Shoes', 'https://cf.shopee.com.br/file/sg-11134201-82611-mkbdehdhk9341b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F53255819198', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22795693059', 'Kit 02 Cadeira Praia Reclinável 8 Posições Mor Azul Marinho', 'Kit 02 Cadeira De Praia Piscina Reclinável 8 Posições Alumínio Mor A Cadeira Reclinável 8 Posições Alumínio é fabricada pela Mor em materiais de excelente qualidade. Possui estrutura em tubos de alumínio e suas peças plásticas em polipropileno. Ainda mais leve e durável, mesmo em regiões litorâneas. Conta com braço largo e ergonômico com regulagem para oito posições diferentes, para que você relaxe na inclinação que for mais confortável. A cadeira fica completamente sentada na posição 1 e completamente deitada na posição 8, ideal para banhos de sol, além disso, seu apoio permite maior estabilidade nessa posição. Sua tela é produzida em 100% poliéster com revestimento em PVC. Super resistente, suporta até 90 Kg e vai ser a opção perfeita para seus momentos de descanso. Descrição do produto Composição: 02 unidades da Cadeira Mor 2295 Marca: Mor Material: Alumínio Capacidade: 90kg Altura do assento: 27,5 cm Largura do assento: 43 cm Altura: 87,00 cm Largura: 53,50 cm Comprimento: 68,00 cm Peso: 1,82 kg', 437.33, 275.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Others', 'https://cf.shopee.com.br/file/sg-11134201-7qvdr-lgo3ay0pj6kn21', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F638399297%2F22795693059', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098807644', 'Sandália Rasteira Feminina Preta Ramarim 2421203-6', 'Sandália Rasteira Feminina Caqui com Tira Nó – Leveza, Conforto e Estilo no Seu Dia a Dia! Essa sandália rasteira caqui é sinônimo de praticidade com charme! O modelo minimalista com tiras finas e detalhe de nó no cabedal garante um toque elegante, enquanto a palmilha com espuma proporciona conforto prolongado. Um item curinga no closet de quem ama estar bem vestida sem abrir mão do conforto. Destaques do Produto: Material sintético resistente e de fácil manutenção Palmilha com espuma que oferece maciez e conforto o dia todo Solado emborrachado que garante aderência e estabilidade Fechamento com fivela ajustável para melhor encaixe no pé Design moderno com detalhe de nó delicado no cabedal Sugestão de Uso: Ideal para o dia a dia, looks de trabalho em ambientes casuais ou passeios de fim de semana. Combina com vestidos estampados, calças pantacourt, conjuntos de linho ou até um jeans com camiseta básica para um visual fresh e equilibrado. Dica de Moda: O preto alonga visualmente as pernas e harmoniza com qualquer paleta de cores. Use com peças em tons terrosos, branco ou preto para um look monocromático chic, ou com cores vibrantes para equilibrar a produção. Cuidados e Limpeza: Limpeza com pano úmido e sabão neutro Secar sempre à sombra, longe de fontes de calor Evite exposição prolongada à água e produtos abrasivos', 149.9, 115.2, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdyg-mdetkangc1wk8f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1011144984%2F23098807644', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40421701745', 'Chuteira Topper Futsal Cup VIII Azul Marinho e Dourado - Masculino', 'Leve seu futsal a outro nível com máximo controle e estabilidade! Chuteira Topper Futsal Cup VIII Azul Marinho e Dourado - Masculino Parte superior do formulário Ficha Técnica: Marca: Topper Cor: Azul Marinho e Dourado Cabedal: Cabedal em sintético para resistência e flexibilidade Gênero: Masculino Palmilha: Têxtil Sola: Borracha Fechamento: Cadarço Estilo: Controle Trava: Sem Trava Tecnologias: Design compacto para melhor aderência e estabilidade nas quadras Entressola: Leve e confortável para movimentos rápidos e precisos Indicação: Partidas de futsal e treinos em quadra indoor Detalhes: Símbolo da marca nas laterais da chuteira Eleve sua performance nas quadras com a Chuteira Topper Futsal Cup VIII. Porque investir: Desenvolvida para quem busca controle e velocidade em cada lance, ela combina cabedal em material sintético resistente e flexível, garantindo conforto e durabilidade. O solado em borracha com excelente aderência proporciona mais segurança para dribles rápidos e movimentações precisas. Leve, confortável e com design moderno, essa chuteira é ideal para jogadores que não abrem mão de estilo e desempenho. Conteúdo da embalagem: 1 par de Chuteira Topper Futsal Cup VIII Azul Marinho e Dourado - MasculinoParte superior do formulário', 169.99, 152.99, NULL, 'Sports & Outdoors > Sports Footwear > Futsal Shoes', 'https://cf.shopee.com.br/file/sg-11134201-824i2-mf45pfsl572g27', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F40421701745', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
