INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20898075724', 'Kit C/ 3 Alicates Universal 8'''' Isol 1000v Master Tramontina', 'O Alicate Universal 8 Polegadas Isolado 1000 V Tramontina é a opção perfeita para quem precisa de um alicate versátil e resistente! Produzido em aço especial temperado, possui cabo de plástico ergonômico que evita que os dedos escorreguem da ferramenta. O cabo também oferece proteção contra correntes elétricas de até 1.000 V em corrente alternada. Desenvolvido para cortar, apertar e dobrar cabos e metais, vai ser o auxiliar perfeito para suas tarefasProduto em conformidade com a NBR9699 e NR10.Alicate UniversalAplicação: PedreiroIsolação: Com Isolação*Imagens meramente ilustrativas*Todas as informações divulgadas são de responsabilidade do Fabricante/FornecedorAlicate de uso geral', 153.57, 153.57, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rd5w-m7cpcuj7eub40a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1425275679%2F20898075724', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
