INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393661378', 'COZY TIME LIVRO DE COLORIR', 'COZY TIME LIVRO DE COLORIR Inspirado no fenômeno dos livros de colorir para relaxamento do TikTok, o livro Cozy Time é perfeito para quem ama transformar momentos simples em uma verdadeira experiência calmante. Impressos em papel de alta gramatura, para garantir a melhor qualidade de pintura, as 48 páginas deste livro são repletas de ilustrações exclusivas que retratam momentos cotidianos e aconchegantes, permitindo que você explore sua criatividade ao máximo, seja colorindo com lápis de cor ou marcadores. Livre para todos os públicos, este livro é perfeito para aliviar o estresse e se desconectar da correria do dia a dia.. Informações Adicionais Autor: ALEKSANDRA, BOZHBOVA Data Publicação: 01/01/1900 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: COZY TIME LIVRO DE COLORIR Idioma: PORTUGUÊS Páginas: 48 Edição: 1 ISBN-13: 9786526120521 ISBN-10: 6526120520', 20.92, 18.2, NULL, 'Books & Magazines > Books > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rbkg-m5e8fx8h0j2vde', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F23393661378', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203368279', 'Kit Relação Transmissão Did Srad Gsx-r 750 06-13 Com Retentor', 'KIT RELAÇÃO / TRANSMISSÃO DID LINHA EXTRA PREMIUM ORIGINAL COMPATÍVEL COM: SUZUKI GSX-R SRAD 750 2007 A 2013 (ANOS BRASIL) Kit é composto por: - Corrente DID japonesa 525 VX3 x 116 ZB retentores X-ring - Emenda remanche (rebitar) - Coroa JT Aço 1049: 45 (5 furos) - Pinhão JT 1049: 17 A parceria D.I.D e JT trouxe para o Brasil o que há de melhor em desempenho e durabilidade. Em todos os kits existe uma atualização de produtos que os torna superiores aos originais de fábrica. VANTAGENS Todas as coroas possuem têmpera nos dentes, melhor resistência ao desgaste; Acabamento anticorrosivo nas coroas e pinhões; Dentes em perfil “U”, mais silencioso e durável; Coroas e pinhões produzidos em aço ligado de maior resistência; Características: Linha Extra Premium Com retentor: diminui a frequência de ajuste do tensionamento e lubrificação. Emenda tipo “ZJ” (Rebite): O elo de emenda ZJ segue o mais alto grau de segurança e desempenho. Uma vez instalado, a corrente tem características de fechamento sem emendas, que garante menor nível de ruído, menor alongamento e principalmente, maior vida útil. As emendas ZJ possuem placas de fechamento com interferência, ou seja, são montadas com prensagem. Uma vez na posição correta, a placa é travada pela rebitagem da extremidade dos pinos. Aplicável em todas as correntes com retentores para melhor desempenho e segurança. JT SPROCKETS: marca inglesa de altíssima qualidade. Os kits de transmissão Extra Premium foram desenvolvidos através de uma parceria entre o maior fabricantes de coroas e pinhões da atualidade, a inglesa JT, e correntes DID de alta performance. Toda a linha pode ser considerada um UPGRADE da formação original, tomando-se como parâmetro a tecnologia que é empregada em cada um dos produtos que forma o kit transmissão. As coroas e os pinhões são produzidas em aço de alta resistência ao desgaste e impacto. As correntes se utilizam de retentores tipo "X", que garantem melhor desempenho e durabilidade. Toda linha utiliza emendas do tipo ZJ e por isso se faz necessário o uso de ferramentas de montagem específicas.', 959.9, 959.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Transmission', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjivpfzabegy99', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1421013142%2F58203368279', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398005814', 'Gel Prolongador da Ereção e Retardador de Ejaculação - Intt Prolong - 17 ml', 'Prolong é um incrível prolongador de ereção e retardador de ejaculação! Ele mantém sua energia e vigor, permite um contato mais deslizante na pele e você pode fazer uma massagem bem gostosa no crush! Cuidado! Alto risco de se apaixonar! Experimente! Contém:17 ml. Informações e Recomendações: Havendo irritação suspenda o uso. Manter fora do alcance de crianças. Composição:Aqua, Dissodium Edta, Hydroxyethylcellulose, Glycerin, Methyldibromo Glutaronitrile (and) Phenoxyethanol, Propylene Glycol, Zingiber Officinalis Extract, Flavor, Clove Oil, Alcohol, CI 4209, Vanilyl Butyl Ether. Conservação: Manter em local fresco, longe da luz solar. Modo de Usar: Passar por todo o escroto e também na glande (cabeça do pênis). Características do Produto:', 54.9, 54.9, NULL, 'Health > Sexual Wellness > Lubricants', 'https://cf.shopee.com.br/file/sg-11134201-7rena-m22uk5xegijh67', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F433423094%2F23398005814', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20099681705', 'Par Aro +raio 4mm + Lona Dianteira Traseira Cg Titan Fan 150', 'Par de Aro Cromado 18 + Par de Raio + Par de Lonas Freio Anuncio contem: 01 - Aro 18 Traseiro 01 - Aro 18 Dianteiro 01 - Jogo de Raio Dianteiro 01 - Jogo de Raio Traseiro 01 - Lona de Freio Dianteira 01 - Lona De Freio Traseira Compatível com: Titan 125 00/08 Fan 125 09/18 Titan 150 / Titan 160 Fan 150 / Fan 160 - Raio Cromado 4mm - Aro Cromado Tork Fabricado com aço carbono que é um dos melhores materiais do mercado Brasileiro, os produtos atendem rigorosamente as especificações normativas, com qualidade 100% nacional. Conservação Os cuidados para conservação do cromo, tanto no seu aspecto quanto na prevenção contra a oxidação, devem considerar a limpeza frequente com água e sabão neutro aplicados com pano ou esponja macia. A montagem e desmontagem do pneu deve ser realizada por profissional experiente e com equipamento adequado. Nunca utilize materiais abrasivos ou produtos químicos para limpeza.', 274.9, 247.41, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Wheels', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8nqfpeu88w26c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F695489389%2F20099681705', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
