INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52507767069', 'Disco De Corte 75 mm x 1,4 mm x 10 mm VONDER Corte Metais Aço Inox Resistente Oferta Premium', 'Disco de Corte 75mm x 1,4mm x 10mm DCV – Vonder 🔩⚙️ O Disco de Corte Vonder DCV é ideal pra quem busca corte rápido, preciso e com acabamento limpo 💥 Indicado para metais, incluindo aço inox, ele entrega alta performance com menor geração de calor e menos rebarbas. Perfeito para uso em cortadores pneumáticos, garantindo eficiência no dia a dia profissional. Itens Inclusos 📦: 1 Disco de Corte 75mm Especificações Técnicas 📊: Referência: 1240075140 Diâmetro do disco: 75 mm Espessura: 1,4 mm Diâmetro do furo: 10 mm Modelo: DCV Grão: G 46 Número de telas: 2 Tipo: Tipo 41 Rotação máxima: 20.300 rpm Normas: ABNT NBR 15230 e ABNT NBR 16245 Aplicação 🔧: Indicado para corte de metais, inclusive aço inox Uso em cortadores pneumáticos Não utilizar em serra mármore ❌ Por que escolher este produto? 🤔 Corte rápido e eficiente ⚡ Menor geração de calor 🔥 Reduz rebarbas e melhora o acabamento ✨ Alta durabilidade e desempenho 💪 Produto novo e original ✔️ Pronta entrega e envio em até 24 horas 🚚 Compra 100% segura 🔒 IMPORTANTE: SUA SATISFAÇÃO GARANTIDA! ✔️ -----> Entrega assegurada pela Shopee com garantia', 17.9, 9.99, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-820lw-mmagjid1qy2o29', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F942805673%2F52507767069', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
