INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9718634117', 'Gotas De Chocolate Forneável Top Chipshow Avelã 1,01kg - Harald', 'Gotas de Chocolate Forneável Top Chipshow Avelã 1,01kg – Harald | Resistência ao Forno e Sabor Irresistível 🍪🍫✨ 😋 Perfeitas para cookies, bolos e sobremesas assadas! As Gotas de Chocolate Forneável Top Chipshow Harald são especialmente desenvolvidas para não derreterem durante o processo de forneamento, garantindo pedaços crocantes e sabor intenso de chocolate com toque de avelã em cada mordida. Ideal para padarias, confeiteiros e amantes da chocolataria artesanal. 🍬 O que é o produto? Gotas de chocolate forneável sabor avelã, em embalagem prática de 1,01kg, da linha Top Chipshow Harald. 🎯 Para que serve? Produção de cookies, muffins e brownies Bolos, pães doces e cupcakes Recheios, decorações e sobremesas assadas Confeitaria profissional e caseira 🌟 Diferenciais: Forneável: mantém a forma e não derrete no forno Textura crocante e sabor intenso Toque especial de avelã para receitas mais sofisticadas Produto da linha Top Harald, referência em confeitaria 📦 Características Técnicas: Marca: Harald Linha: Top Chipshow Produto: Gotas de Chocolate Forneável Sabor: Chocolate com Avelã Peso líquido: 1,01kg Armazenamento: Local fresco, seco e protegido da luz solar (18°C a 22°C) Tabela nutricional e lista de ingredientes disponíveis na embalagem do fabricante. ✅ Benefícios: Mantém a forma após o forneamento Sabor equilibrado e sofisticado de chocolate + avelã Ideal para padarias, confeitarias e uso doméstico Rendimento elevado em produções profissionais 🎯 Indicado para: Confeiteiros profissionais e iniciantes Padarias, docerias e cafeterias Produção de cookies, bolos e sobremesas artesanais Quem busca praticidade e sabor nas receitas 📦 Entrega e Disponibilidade: Produto com pronta entrega Envio rápido e embalagem segura ⚠️ Avisos: Contém leite, derivados e soja Pode conter traços de castanhas Contém glúten Nossos produtos têm prazo de validade superior a 5 meses. Se tiver mais alguma dúvida ou precisar de mais informações, estou à disposição! 🛍️ Somos uma loja especializada em artigos de festa, confeitaria, embalagens, doces e chocolates, com lojas físicas no estado de São Paulo, desde 2002.', 63.99, 63.99, NULL, 'Food & Beverages > Snacks > Chocolate', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9a7nghpuf4281', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318555124%2F9718634117', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997967280', 'Kit Relação CB 250F Twister 2016 a 2023 Transmissão Honda', 'KIT TRANSMISSAO CB 250F TWISTER 2016/2022 (520HX110LX40TX13T) O kit de transmissão é um dos principais responsáveis pelo bom funcionamento da moto, garantindo força, desempenho e segurança na pilotagem. Pensando nisso, oferecemos um produto de alta qualidade, desenvolvido dentro dos padrões originais para proporcionar encaixe perfeito e máxima durabilidade. FICHA TÉCNICA: Material da Coroa: Aço 1045; Material do Pinhão: Aço 1045; Quantidade de dentes da coroa: 40; Quantidade de dentes do pinhão: 13; Comprimento da corrente: 520 cm; Quantidade de ligações da corrente: 110. COMPATIBILIDADE: HONDA CB 250 TWISTER 2016 HONDA CB 250 TWISTER 2017 HONDA CB 250 TWISTER 2018 HONDA CB 250 TWISTER 2019 HONDA CB 250 TWISTER 2020 HONDA CB 250 TWISTER 2021 HONDA CB 250 TWISTER 2022 CONTEÚDO DA EMBALAGEM: 01 Corrente; 01 Coroa; 01 Pinhão. Fabricado com matéria-prima de alta qualidade; Produto testado e aprovado pelos engenheiros e mecânicos; Matéria prima de alta qualidade o que permite longa vida útil ao produto; Rigoroso controle de qualidade, com alta resistência e máxima durabilidade; OBS: Recomendamos mão de obra especializada ---------------------------------- - Envio no máximo em 24 horas úteis. - Produto 100% original. - Devolução sem custo para o cliente (dentro do prazo de 7 dias ou em caso de garantia).', 229.9, 229.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Transmission', 'https://cf.shopee.com.br/file/sg-11134201-822x8-mo74rnr78l4w14', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404353670%2F23997967280', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
