INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897630805', 'Kit Fralda Pampers Confort Sec Tamanho P com 100 Unidades', 'O Kit contém: 2 pacotes de Fralda Pampers Confort Sec Tamanho P com 50 unidades cada. Experimente a NOVA Pampers confort sec com canais de ar! Que permitem que o ar circule livremente dentro da fralda, para o bumbum ficar menos abafado, e a pele arejada e sequinha durante a noite. Até 2X mais seco* e arejado * vs fraldas comuns. Canais de Ar: Permitem que o ar circule livremente dentro da fralda, para o bumbum ficar menos abafado, e a pele arejada e sequinha durante a noite. Gel Mágico que absorve e retém a umidade no interior da fralda para noites mais sequinhas Camada ultra absorvente:absorve rapidamente a umidade mantendo a pele do bebê sequinha. Barreiras Anti Vazamento: se adaptam suavemente ao redor das pernas do seu bebê. Ajuste cômodo e flexível para dar uma proteção anti vazamentos todas as noites. Loção hipoalergênica: ajuda a prevenir irritaçãoes. *Compre produtos Pampers', 179.89, 157.88, NULL, 'Mom & Baby > Diapering & Potty > Disposable Diapers', 'https://cf.shopee.com.br/file/401f11ac0dbee57faeabaec7a4424ab9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1062557396%2F23897630805', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
