INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20096990864', 'Kit Com 6x Óleos Desengripante Lubrificante Spray White Lub 300ml', 'KIT 6 SPRAY DESENGRIPANTE WHITE LUB - ORBI QUIMICA Desengripante Completo White Lub Super 300ml/180g- ORBI Química APLICAÇÃO: No carro: é ideal para neutralizar qualquer sintoma de ferrugem que apareça em seu carro, além de proteger as partes cromadas e todos os metais. Em casa e no escritório: na conservação de todos os aparelhos eletrodomésticos, dobradiças, fechaduras, trincos, peças de ferro ou de qualquer outro material oxidável. Solta com facilidade porcas e parafusos enferrujados. No esporte e no lazer: O seu material de caça e pesca, a lancha a moto, a bicicleta, o skate, os patins a até o velocípede estarão sempre em condições de uso imediato com aplicação de White Lub Super. Na indústria e na oficina: na conservação de todas as ferramentas e peças em geral. Sua indústria ou oficina ficará livre da ação destruidora da ferrugem. Instruções de Uso: Pulverize a uma distância de cerca de 15cm, dirigindo o jato aerossol para parte a ser tratada. Para lubrificar partes pouco acessíveis encaixe o tubo plástico (prolongador) que acompanha a embalagem no orifício apropriado à válvula de pressão e proceda a aplicação como descrito anteriormente. Armazenagem: Armazenar em lugar fresco e seco. Longe de fontes de calor, mantenha na embalagem original para conservação da qualidade do produto. Material inflamável e recipiente sob pressão. Nuvem de Tags: Spray, desengripante, anti ferrugem, neutralizador, lubrificante, anticorrosivo, white lub.', 82.99, 62.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9qas58sp9a11c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F944577712%2F20096990864', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093999220', 'Cachimbo de Vela CBX 250 XR 250 Tornado CB 300 XRE 300 Sahara Falcon', 'Cachimbo de vela de alta qualidade, compatível com diversos modelos Honda. Fabricado com materiais duráveis e resistente a altas temperaturas, garantindo boa condução elétrica e excelente desempenho do motor. Ideal para quem busca reposição confiável, com encaixe preciso e durabilidade. Modelos compatíveis: CBX 250 Twister – 2001 a 2008 XR 250 Tornado – 2001 a 2008 CB 300R – 2009 a 2015 XRE 300 – 2010 em diante Sahara 350 – 1990 a 1999 NX-4 Falcon 400 – 1999 a 2008 NX 400i Falcon – 2013 a 2015 Características: Material resistente ao calor e vibração Excelente vedação e condução de energia Encaixe padrão, fácil instalação Produto de reposição com ótimo custo-benefício 🛠️ Pronto para instalação! 📦 Enviado com segurança e agilidade. 🔧 Ideal para manutenção preventiva e corretiva. Shopping da MotoBike agradece sua preferência.', 29.9, 26.91, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Ignition', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9q5hd7xm2v69d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F531303273%2F22093999220', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
