INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597727164', 'Chinelo Havaianas Top FC Feminino - Branco', 'A Havaianas Top tem o DNA Havaianas: é Democrática, versátil, clássica, confortável e colorida. Tem para todos os gostos: Do básico ao fashion, do neutro ao vibrante. Na nova coleção, destaque para a cartela de cores inspirada no movimento alemão Bauhaus.', 49.9, 39.9, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/sg-11134201-7rdxg-lzfb7vxp3fuuc5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F23597727164', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23892784361', 'Fogão Cooktop Gás em Vidro Temperado Mueller 5 Bocas Ultra Chama Bivolt Preto', 'O Cooktop 5 Bocas Mueller Ultra Chama é a escolha perfeita para quem busca sofisticação na cozinha! Seu acendimento superautomático permite acender as chamas com facilidade, enquanto as grades individuais de ferro fundido garantem robustez e durabilidade, com 6 pontos de apoio para panelas mais estáveis. O sistema de encaixe exclusivo assegura grades firmes e seguras. Além disso, os queimadores de aço esmaltado são duráveis e fáceis de limpar. Com um queimador Ultra Chama de 2400W, você terá potência para preparar suas receitas rapidamente. Dois queimadores Semirrápidos de 2700KW são ideais para pequenas receitas, enquanto o queimador Auxiliar de 1000W é perfeito para pratos que necessitam de baixa potência. Adicione sofisticação e eficiência à sua cozinha com o Cooktop da Mueller! Especificações: - Comprimento: 68 cm - Largura: 44 cm - Altura: 10,5 cm - Acende ao girar o botão - Mais robustez e durabilidade - Um queimadores Ultra Chama com potência de 2400W - Dois queimadores Semirrápidos com potência de 2700KW - Um queimador Auxiliar com potência de 1000W - Tipo de Gás - GLP (Conversível para GN) - Mesa de vidro temperado - Acendimento superautomático - Grades individuais de ferro fundido - Grades com 6 pontos de apoio - Sistema de encaixe exclusivo - Queimadores de aço esmaltado - Registro INMETRO: 004555/2014 - Cor: Preto - As configurações do seu monitor ou dispositivo móvel podem afetar a tonalidade da cor do produto. Conferir na descrição. - Recomendação de Limpeza: Limpar com pano seco para retirar o pó. Não aplicar produtos abrasivos. - Produtos de Enfeite e Eletrônicos Não Estão Inclusos.', 899.88, 709.9, NULL, 'Home Appliances > Kitchen Appliances > Stoves, Hobs & Gas Regulators', 'https://cf.shopee.com.br/file/sg-11134201-7rdx3-lxyxm9jwar1ic5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1296760327%2F23892784361', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19099499360', 'Kit 48 und Dermaone Sabonete Íntimo Tradicional 200ml', 'Kit Dermaone Sabonete Íntimo Tradicional 200ml Os sabonetes ÍNTIMOS DERMAONE possuem um pH compatível com o da área íntima, graças a presença do ácido lático, agente responsável por esse equilíbrio. Eles ajudam a proteger a região íntima de infecções e consequentemente seus odores. Além disso, proporcionam limpeza e uma sensação de frescor. DermaOne Floral possui um pH compatível com o da região íntima, graças a presença do ácido lático, agente responsável por esse equilíbrio e ajudar a proteger a região íntima de infecções e consequentemente maus odores. Além disso, proporciona limpeza e sensação de frescor. Modo de uso: Aplique diariamente durante o banho na região genital externa previamente umedecida e espalhe até obter espuma. Em seguida, enxague abundantemente.', 379.67, 379.67, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-7rdvc-m0yo7wmxr9onbc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F19099499360', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
