INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093555028', 'Kit Com 10 Perfumes Attimo Le Parfum Paris Elysees 100ml', 'O kit contém: - 10 perfumes Attimo Le Parfum da Paris Elysees de 100ml cada. - Produto original e lacrado. Attimo da Paris Elysees é um perfume masculino, suas notas são equilibradas e clássicas, perfeitas para homens tradicionais que também gostam de se aventurar no mundo moderno. É uma fragrância refrescante com toques herbais e masculinos. Ideal para uso diário em diversas atividades cotidianas. Se você está pensando em experimentar o Attimo, tenho certeza de que vai apreciar essa combinação clássica! Família Olfativa: Aromático Fresco. Nota de Saída: Limão e Tomilho. Notas de Coração: Jasmim, Noz Moscada e Zimbro. Notas de Fundo: Sândalo, Musgo e Âmbar.', 369.91, 369.49, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m35amcxurrv991', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F369057850%2F23093555028', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
