INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22192961283', 'Limpador Higienizador de Couro Higicouro 500ml Vonixx', 'Bem-vindo a Koala Parts! A sua escolha certa para peças e acessórios automotivos - Há mais de 10 anos oferecendo qualidade e confiança. Limpador Higienizador de Couro Higicouro 500ml Vonixx • LIMPA SEM AGREDIR • NÃO RESSECA • ELIMINA ÁCAROS E MOFO • PROTEGE E RENOVA LIMPEZA SEGURA PARA BANCOS E SUPERFÍCIES DE COURO! Remove impurezas com extrema facilidade, sem agredir o material do couro. ELIMINAÇÃO DE ÁCAROS E MOFO Além de limpar, o Higicouro contribui para a higiene, eliminando ácaros e mofo. PROTEÇÃO E REALCE Deixa os bancos com aspecto de novo, protegendo e realçando a cor natural do couro. FÁCIL APLICAÇÃO Basta pulverizar o produto, aguardar 30 segundos e limpar com um aplicador de espuma. Remova o excesso com uma toalha de microfibra e repita, se necessário. DICA Para bancos com furos, é aconselhável o uso de pincel ou escova macia, para garantir uma limpeza eficaz e evitar o acúmulo de produto nos furo. USO RECOMENDADO Veículos Motos Aeronaves Embarcações ** Pode ser utilizado em qualquer tipo de couro, natural ou sintético ESPECIFICAÇÕES TÉCNICAS: - Disponível em: 500ml - Estado Físico: Líquido - Cor: Incolor - Diluição: Pronto uso CONTEÚDO DA EMBALAGEM: - 01 Limpador de Couro Higicouro Vonixx', 44.9, 44.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Treatments', 'https://cf.shopee.com.br/file/sg-11134201-7rd3v-lty2x1c01f4808', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F288113309%2F22192961283', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22698869283', 'Rolamento De Roda Dianteira HONDA CIVIC 1.5 16V 1993 A 1995', 'Rolamento De Roda Dianteira HONDA CIVIC 1.5 16V 1993 A 1995 ESPECIFICAÇÕES: DIANTEIRO S/ABS 79X43X38/41MM APLICAÇÕES : HONDA CITY 1.5 16V 2010 A 2014 HONDA CIVIC 1.5 16V 1993 A 1995 HONDA CIVIC 1.6 16V 1992 A 1995 HONDA CIVIC 1.7 16V 2001 A 2006 HONDA FIT 1.4 16V 2009 A 2014 HONDA FIT 1.5 16V 2009 A 2014 Número Original/Similar: 43BWD08 / DAC4379W1CS57 / IR18695 / 4379 GARANTIA: 3 MESES DUVIDAS FREQUENTES: VOCÊS SÃO CONFIÁVEIS? R: SIM, BASTA OLHAR NOSSA REPUTAÇÃO E MEDALHA . PRESTAMOS UM ÓTIMO ATENDIMENTO E DESPACHAMOS OS PRODUTOS NO PRAZO. AS FOTOS DO PRODUTO SÃO REAIS? R: SIM, FOTO REAL DA PEÇA. A QUALIDADE DO PRODUTO É BOA? R: SIM, TODOS OS NOSSOS PRODUTOS SÃO NOVOS E COM GARANTIA. QUAL O PRAZO DE ENTREGA? R: VOCÊ PODE VERIFICAR O PRAZO DE ENTREGA NA TELA INICIAL ABAIXO DO PREÇO DO PRODUTO. VARIA DE REGIÃO PARA REGIÃO. DEVOLUÇÃO E TROCAS COMO FAZER? R: A DEVOLUÇÃO É GRÁTIS; VOCÊ PODE TROCAR O PRODUTO SE NÃO FICAR SATISFEITO (PRAZO DE 30 DIAS APÓS RECEBER). EM CASO DE GARANTIA COMO FAZER? R: EM CASO DE GARANTIA, ENTRAR EM CONTATO VIA CHAT PARA FAZER A TROCA DA PEÇA. POSSO RASTREAR MEU PEDIDO? R: SIM, APÓS A COMPRA, LIBERA O CÓDIGO DE RASTREAMENTO PARA VOCÊ ACOMPANHAR O PEDIDO EM TEMPO REAL ATÉ A CHEGADA. APÓS A COMPRA, PODEREI MADAR MENSAGEM PARA O VENDEDOR? R: SIM, APÓS A COMPRA CONFIRMADA, O CHAT É LIBERADO. ACESSE O CHAT NO MENU "MINHAS COMPRAS". O PRODUTO É COMPATÍVEL COM MEU VEÍCULO? R: OBSERVE QUE NA DESCRIÇÃO DISPONIBILIZAMOS A COMPATIBILIDADE DA PEÇA. SE O SEU VEÍCULO NÃO ESTIVER LISTADO, NOS FAÇA UMA PERGUNTA AQUI ABAIXO ENVIANDO MODELO E ANO QUE CONFIRMAREMOS A APLICAÇÃO.', 99.6, 99.6, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-824jk-me4ddz8ibeh20b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1355263989%2F22698869283', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
