INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46607721594', 'Kit 4 conjunto Meia Luva Touca para Bebê Recém Nascido 0 a 03 meses Maternidade Enxoval Fofurinha', 'Este kit foi cuidadosamente pensado para proporcionar ainda mais conforto e praticidade para o seu bebê. O conjunto inclui 4 pares completos com touca, luvinhas e meias, garantindo que o recém-nascido tenha sempre peças macias e aconchegantes para o dia a dia. As toucas, confeccionadas com tecido macio e respirável, ajudam a proteger o bebê do ambiente externo, proporcionando um toque suave e confortável. As luvinhas oferecem uma camada extra de proteção para as mãozinhas delicadas, ajudando também a evitar arranhões. Para completar, as meias mantêm os pezinhos aquecidos e protegidos, trazendo ainda mais conforto para os primeiros meses de vida. Cada peça foi desenvolvida com materiais de qualidade e pensada especialmente para o bem-estar do bebê, tornando esse kit uma escolha prática, charmosa e essencial para os primeiros momentos. Características: KIT COM 4 PARES, contendo 4 unidades de cada produto da foto, sendo: 4 Pares Toucas 4 Pares de Luvinhas 4 Pares de Meias Composição: TOUCA: 70% Algodão, 29,7% Poliamida e 0,3% Elastano LUVAS: 60% Algodão, 39% Poliamida e 1% Elastano MEIAS: 76% Algodão, 22% Poliamida e 2% Elastano Tabela de Medidas: Tamanho RN: veste de 0 a 3 meses.', 119.95, 71.99, NULL, 'Baby & Kids Fashion > Baby Mittens & Footwear', 'https://cf.shopee.com.br/file/br-11134207-820l5-mm8xyfyy3e2v7a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F287287585%2F46607721594', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
