INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57157031763', 'Capa Anti Impacto X-Level Duke Magnética - Galaxy S26 Ultra', 'Capa Anti Impacto X-Level Duke Magnética Compativel com Galaxy S26 Ultra A Capa X-Level Duke Magnética combina proteção reforçada com compatibilidade magnética para facilitar o uso com carregadores e acessórios modernos. Seu design premium oferece segurança, praticidade e acabamento elegante no uso diário. • Compatível com carregadores magnéticos, suportes veiculares e outros acessórios magnéticos • Estrutura premium em policarbonato, TPU e revestimento em PU que oferece resistência e acabamento sofisticado • Sistema de absorção de impacto com TPU flexível e PC rígido que ajuda a proteger contra quedas e batidas • Design fino e leve que mantém o perfil elegante do smartphone sem adicionar volume excessivo • Recortes precisos que garantem acesso completo a botões, portas e câmera As capas da X-Level oferecem proteção eficiente com acabamento de alta qualidade. Aviso: Não utilize produtos abrasivos nem álcool na limpeza da capa, pois podem danificar o material e o acabamento.', 79.9, 79.9, NULL, 'Mobile & Gadgets > Accessories > Cases, Covers, & Skins', 'https://cf.shopee.com.br/file/sg-11134201-8260y-mlntcljs44jo4f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442913304%2F57157031763', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
