INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22324678847', 'Sutiã com Aro e Bojo Liz 51501 Taça C', 'Em Detalhes: Lift com bojo e com aro, levanta e modela Levíssimo, ideal para quem não gosta de sentir o sutiã Detalhe da luxuosa Renda French Design Ideal para ser usado com blusas em decote U Laterais mais largas Tecido Tato Zero Marcas em microfibra indesmalhável, fresco e respirável Indicado para seios: Pequenos, médios e grandes Características: Sutiã Lift com aro e bojo. Levanta e modela os seios na medida ideal. Confeccionada em exclusiva microfibra, encorpada e macia. Decote com aplicação de delicada e sofisticada renda. Base reforçada proporcionando maior sustentação. Laterais estreitas. Alças reguláveis. Costas com fecho em colchetes. Diferenciais: Indicado para seios pequenos, médios e grandes. Firmes ou flácidos. Outros Detalhes: Taça C. Composição: Corpo: 76% Poliamida e 24% Elastano. Forro: 100% Poliéster. Bojo: 100% Poliuretano.', 215.9, 215.9, NULL, 'Women Clothes > Lingerie & Underwear > Bras', 'https://cf.shopee.com.br/file/sg-11134201-23020-9k3zdce8rknvd4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F946236885%2F22324678847', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
