INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23893847840', 'Sonny Angel Série Animal 2', 'O popular anjinho que vem para trazer alegria aos ambientes. Na cultura oriental, a felicidade é uma das maiores fontes de saúde para todos. Sorrir é sempre o melhor remédio. Com estilo retro, os olhinhos grandes e sorriso fofo. Nascidos no Japão, cada série é única. Com personagens especiais, cada série contém 12 personagens ou segredo aleatório. São colecionáveis e um mais lindo que o outro. Se prepare para ser surpreendido. Esse anjinho pode te deixar muito feliz. Você não escolhe um Sonny Angel. O Sonny Angel é quem escolhe você. PRODUTO IMPORTADO. Cada série contém 12 personagens. Você receberá uma caixinha contendo um dos 12 bonecos desta coleção. Como as caixinhas são lacradas, nem nós büp baby sabemos o que tem dentro da cada uma delas. Você descobrirá o modelo que comprou somente quando abrir a caixinha. ESPECIFICAÇÕES: - Contém 1 unidade; - Perfeito para decoração de ambientes; - Itens colecionáveis; - Origem: Japão. MATERIAL: - PVC. MEDIDAS: - 8 x 4 x 2 cm. LIMPEZA E MANUTENÇÃO: - Limpeza localizada com pano úmido e sabão neutro. SOBRE A MARCA: Sonny Angel encanta os fãs há 14 anos. Desde o nascimento de Sonny Angel, que nasceu para nos fazer sorrir e adicionar um pouco de diversão às nossas vidas, decora do canto de uma sala a uma prateleira. Você não escolhe um Sonny Angel. O Sonny Angel é quem escolhe você.', 129.9, 119.9, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/sg-11134201-824gn-mfpiphzqnswac4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1240688238%2F23893847840', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23994815672', 'Jogo de 6 Canecas 360 Ml Oxford Flora Áster', 'A Caneca Flora chega como complemento à linha, ampliando a proposta da coleção. Seu relevo externo tem o mesmo design dos pratos Flora, com vincos delicados que evocam o desenho das pétalas, criando um relevo suave no externo de cada peça. Com capacidade de 360 ml, a caneca une conforto de uso e harmonia de conjunto, permitindo composições coordenadas com as cores da linha. Azul claro e luminoso, que adiciona frescor visual e sensação de tranquilidade. Conteúdo da embalagem: 6 canecas 360 ml, 10,5 cm de altura e 9 cm de diâmetro - Garantia: 3 Meses para Defeitos de fabricação - Marca: Oxford - Decoração: Monocromático - Cor: Azul claro - Conteúdo da embalagem: 6 canecas 360 ml, 10,5 cm de altura e 9 cm de diâmetro - Conjunto ou avulso: Conjunto - Material: Porcelana - Linha: Flora - Uso: Resistente a micro-ondas - Origem: Nacional - Tipo da embalagem: Papelão pardo - Formato: Redondo - Fabricado por: Oxford - Tipo de produto: Canecas - Modelo: Áster - Quantidade de peças: 6 - É apto para lava-louças: Sim ATENÇÃO: Para compras de pessoa jurídica,cadastreosdados exatamente como consta em seu cartão do CNPJ', 237.6, 237.6, NULL, 'Home & Living > Dinnerware > Cups, Mugs & Glasses', 'https://cf.shopee.com.br/file/sg-11134201-8261c-mkbb7t9cwiyvb0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1075271269%2F23994815672', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
