INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22297996209', 'Sandália Infantil Menina Casual Confortável Original Moda 28 Ao 36', 'TABELA DE MEDIDAS 28 - 20.5 cm 29 - 21 cm 30 - 21.5 cm 31 - 22 cm 32 - 22.5 cm 33 - 23 cm 34 - 23.5 cm 35 - 24 cm 36 - 25 cm Se você procura um calçado que una conforto, estilo e versatilidade, a sandália feminina é a escolha perfeita! Seja para um dia ensolarado na praia, um passeio no parque ou uma saída à noite, as sandálias são a solução ideal para completar qualquer look. Com uma infinidade de estilos, cores e designs, há sempre uma sandália perfeita para cada ocasião. Desde modelos clássicos e elegantes até opções mais despojadas e coloridas, você pode expressar sua personalidade e se sentir confiante em qualquer situação. Imagine-se desfilando com uma sandália que não só combina com seu visual, mas também realça sua beleza! Além de estilosas, as sandálias femininas oferecem conforto essencial, garantindo que você possa caminhar com facilidade durante todo o dia. Chega de abrir mão do conforto em nome da moda! Não perca a chance de elevar seu guarda-roupa com uma sandália feminina que combine estilo e conforto. Experimente e descubra como cada passo pode ser uma afirmação de moda e elegância!', 99.9, 64.9, NULL, 'Baby & Kids Fashion > Girl Shoes > Sandals', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgxujj6w2yo5a6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1296584125%2F22297996209', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
