INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22497750413', 'KIT Caderno Brochurão Universitário Capa Dura 96 Folhas Amarelo Stiff - Pacote Com 5 Unidades', 'Marca: Jandaia; Referência: 00061-55; Código: 680; Características: Caderno Brochurão Capa Dura 96 Folhas Amarelo Stiff; Dimensões do Produto: 200x275mm; Embalagem: Pacote Com 5 Unidades; Este caderno brochura universitário, com capa dura e 96 folhas, é o companheiro perfeito para suas jornadas acadêmicas. Sua capa dura oferece proteção confiável para suas anotações, garantindo durabilidade ao longo do semestre. Com espaço suficiente para suas matérias, é ideal para acompanhar suas aulas, fazer exercícios e manter suas ideias organizadas. Seja para estudos, projetos ou simplesmente para anotações do dia a dia. Compacto e prático, é fácil de transportar na mochila, garantindo que você tenha sempre suas notas à mão.', 79.17, 79.17, NULL, 'Stationery > Notebooks & Papers > Notebooks & Notepads', 'https://cf.shopee.com.br/file/sg-11134201-7rdxo-lzjgusphtk3q92', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1306190243%2F22497750413', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
