INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23891660514', 'Livro Os Valdenses Capa Dura | A História dos Protestantes que antecederam a Reforma | Magno Paganelli', 'A produção de obras sobre a História da Igreja e, particularmente, sobre a Reforma protestante é extensa, especialmente durante a comemoração dos 500 anos daquele marcante evento, no ano de 2017. Nesses textos, os valdenses costumam aparecer — quando são mencionados — como um apêndice e, em certos casos, são indicados como um grupo cismático e herege.No entanto, essa impressão não resiste a um exame crítico. Ao contrário! Antecipando em alguns séculos os principais postulados das Reformas de Lutero, Calvino e outros, esse grupo surgido nos vales do Piemonte, entre os Alpes Cócios, compreendeu desde cedo que a Igreja de Roma havia perdido a direção e se corrompera, doutrinária e moralmente. Mas, ao esforçarem-se por preservar a própria fé em uma consciência limpa (1Tm 1.19), foram caçados por exércitos de príncipes, por ordem papal. Este livro resgata essa impressionante história de perseguições e mortes, mas também de esperança e fé. Apresenta os primórdios do movimento, a relação posterior e pouco esclarecida com o personagem Pedro Valdo, de Lion, na França, os referenciais de fé, a teologia valdense e muito mais. Tudo examinado à luz da obra de historiadores que souberam tratar do tema fora do país, em uma rica edição ilustrada, pela primeira vez publicada no Brasil. Detalhes do Produto: Autor: Magno Paganelli Editora: Geográfica Acabamento: Capa Dura Dimensões: 16 larg. X 23 alt. Número de páginas: 128', 29.9, 29.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7qvfe-lixbajx3y48nee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F23891660514', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
