INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22899424534', 'Cera Fixadora Em Bastão Ricca 15G', 'Cera em Bastão Ricca - Fixa e Modela com 12h de Frizz Control A Cera em Bastão Ricca é a solução perfeita para quem busca praticidade e resultados incríveis. Ela fixa, modela e alinha os fios, garantindo penteados perfeitos com durabilidade de 12 horas, sem frizz. Ideal para finalizar seu estilo de forma rápida e prática, a cera é a aliada que seus cabelos pediam para garantir looks impecáveis durante todo o dia! O que só ela faz? Fixa e modela os fios Controle do frizz por 12 horas Alinha os fios e proporciona acabamento perfeito Ideal para penteados rápidos e práticos Perfeito para estilizar o baby hair Modo de Uso Para finalizar o penteado: Aplique a Cera em Bastão nos cabelos secos e modele como desejar para garantir o acabamento perfeito. Dica Ricca para cacheadas: A Cera em Bastão Ricca é perfeita para estilizar o baby hair, proporcionando controle e definição nos fios mais finos e delicados da raiz. Sorria, na Cera em Bastão Ricca NÃO tem: Parabenos Corantes Sulfato Ingredientes de origem animal Experimente a Cera em Bastão Ricca e conquiste penteados incríveis, sem frizz, que duram o dia todo!', 77.9, 44.0, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134275-820lg-mmamcf05ut52ee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1328633078%2F22899424534', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
