INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22194373674', 'Caixa de Som Philco Extreme Flash Lights 2000W PCX10101', 'Transforme seus momentos em casa ou nas festas com a Caixa de Som Philco Extreme Flash Lights 2000W PCX10101. Com 2000W de potência, a Caixa de Som Philco Extreme entrega uma experiência sonora vibrante e envolvente, fazendo com que você sinta cada batida da música. Sua bateria interna garante até 20h de festa ininterrupta, enquanto o Bluetooth 5.3 oferece conectividade estável com até 10m de distância. Imagine unir várias caixas de som Philco e criar uma festa ainda maior com a função Philco Connection, que permite reproduzir a mesma música simultaneamente em todos os dispositivos conectados. Já o design com dois woofers de 10” e tweeter da Caixa de Som PCX10101 oferece graves profundos e nítidos, e o recurso EX BASS ajusta o som conforme sua preferência. As luzes Flash Light e Full Led tornam cada evento ainda mais especial, com cores e efeitos personalizáveis que animam o ambiente. Além disso, as múltiplas entradas garantem que você ouça sua música do jeito que preferir, seja via Bluetooth, entrada auxiliar, pen drive, cartão TF ou rádio FM. Eleve o nível da sua diversão e praticidade no dia a dia com a Caixa de Som Philco Extreme PCX10101 da Philco. Entrada USB Entrada de cartão TF Rádio FM com memorização de estações 2 x Entradas Microfone e 1 Entrada para Guitarra Entrada Auxiliar P2 Bluetooth V5.3 Philco connection TWS 2 x Woofer de 10” e Tweeter Flash Light e Full Led. 5 opções de equalização Controle Remoto Fonte de alimentação 15V/4A Autonomia de 20h com uso em 50% do volume e luzes desligadas.', 1399.9, 1099.9, NULL, 'Audio > Amplifiers & Mixers', 'https://cf.shopee.com.br/file/sg-11134201-8258p-mq7yd0hm02rwb9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1276145502%2F22194373674', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26018126787', 'Mix de Frutas e Sementes', 'O nosso Mix de Sementes e Frutas é a combinação perfeita para quem busca um lanche saudável e nutritivo. Com uma seleção cuidadosamente escolhida de sementes crocantes e frutas desidratadas, esse mix oferece uma rica variedade de sabores e texturas que vão desde o doce das frutas até o toque crocante das sementes. Ideal para consumo a qualquer hora do dia, ele é uma excelente fonte de fibras, antioxidantes e ácidos graxos essenciais, proporcionando energia e saúde ao seu organismo. Sem adição de conservantes, corantes ou açúcares refinados, é uma opção 100% natural, prática e deliciosa para quem deseja manter uma alimentação equilibrada INGREDIENTES: Amendoim torrado sem pele e sem sal, amendoa crua, castanha do Pará, cranberry, goji berry, girassol semente crua, semente de abobora sem casca crua. ALÉRGICOS: PODE CONTER TRAÇOS DE GLÚTEN, LEITE, SOJA, AMENDOIM E CACAU POR CONTAMINAÇÃO CRUZADA. INFORMAÇÕES ADICIONAIS - PODE HAVER VARIAÇÃO DE COR DEPENDENDO DO LOTE. - EMBALAGEM MERAMENTE ILUSTRATIVA.', 30.0, 30.0, NULL, 'Food & Beverages > Snacks > Seeds', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m2r14zk6h72r9d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F657120589%2F26018126787', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
