INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20599866123', 'Tinta Spray Chemicolor Alta Temperatura Branco Fosco 350ml', 'Características Principais: Marca: Chemicolor Cor: Branco Volume: 350ml Apresentação: Aerossol Suporta temperaturas: Até 600ºC Informações Adicionais: Aplicação: Superfícies metálicas externas sem contato direto com chamas ou alimentos Uso recomendado: Escapamentos de veículos, fornos elétricos externos, churrasqueiras portáteis Preparo da Superfície: Limpar e lixar bem a superfície a ser pintada, garantindo que esteja seca e livre de gordura, ferrugem, restos de tinta velha, pó, etc. Proteger as áreas que não serão pintadas. Não utilizar Fundo ou Primer antes da aplicação da tinta. Aplicação: Agitar bem antes de usar. Testar o aplicador, pressionando a válvula em qualquer superfície. Aplicar a 10 cm de distância com movimentos uniformes. Limitar a aplicação a no máximo 2 demãos para garantir a secagem e resistência adequadas. Secagem: Ao toque: 20 minutos Para manuseio: 2 horas Total para resistência térmica: 24 horas Após a aplicação, aquecer o substrato a 250ºC por 1 hora para garantir resistência de até 600ºC. Recomendações e Precauções: Conteúdo sob pressão; manter longe de chamas e superfícies quentes. Não perfurar a embalagem e não expor a temperaturas superiores a 50ºC. Em contato com pele ou olhos, lavar com água; não inalar. Em caso de ingestão, procurar ajuda médica imediatamente. Fornecedor: Baston', 29.81, 18.9, NULL, 'Home & Living > Tools & Home Improvement > Others', 'https://cf.shopee.com.br/file/sg-11134201-824h2-mpibj4xbi6fh5c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F822103155%2F20599866123', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
