INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20299870552', 'Correia Micro-V Gates 7PK2060', 'Correia Micro-V Gates 7PK2060 para Honda Civic 1.8/ Honda CRV 2.0 de 2007 á 2011. As correias Gates Micro V oferecem uma operação extremamente suave e possui características importantes para seu uso contínuo. Capacidade de força extremamente alta por friso rib, maior durabilidade em virtude da alta capacidade de suportar cargas. Transmissões mais compactas. Os micro canais truncados garantem a flexibilidade. O composto de borracha de alta qualidade protege a correia contra o calor, o ozônio, óleo e a luz solar. O corpo da correia é reforçado com fibras, o que melhora ainda mais a estabilidade da correia, os cordonéis de Poliéster vulcanizados na borracha como uma única peça, proporcionam alta resistência à tração, suportando a fadiga e as cargas de choque. Especificações Técnicas: - Marca: Gates; - Código do fornecedor:7PK2060 - Material: Lona e Borracha - È Kit: Não Compatível com: - Honda Civic 1.8 16V (Com Direção Elétrica) de 2007 à 2011 - Honda CRV 2.0 16V de 2007 à 2011 Obs: Este produto requer um profissional capacitado para realizar a instalação. Não nos responsabilizamos por má instalação ou uso indevido do produto.', 185.5, 139.13, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-23020-c2ir3vhjz4mv70', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1452490205%2F20299870552', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
