INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '4960915997', 'Barra Estabilizadora Escort, Zetec, Verona, Logus, Pointer', 'Conteudo 01 Barra Estabilizadora Dianteira Aplicação: FORD / VOLKS Escort após 1993 Logus Verona Pointer Prazo de Envio: No mesmo dia para pagamentos confirmados no até as 10:59hs. Após as 11:00hs o envio será no próximo dia útil Instalação: Deve ser feita por um profissional qualificado que utilize as ferramentas adequadas para instalação e forneça Nota Fiscal de instalação. Isso atrelada a qualidade das peças contribuem para a alta durabilidade. Defeitos: Garantimos 100% a Qualidade de nossos produtos. Caso haja algum defeito de fabricação o valor do frete de envio para a garantia será por nossa conta. Enviaremos o código de postagem afim de não causar nenhum gasto de postagem ao comprador. Constatado o defeito de fabricação, seu dinheiro será todo devolvido. Qualidade comprovada produto novo 100% original Emitimos a nota fiscal do produto 6 meses de garantia da peça Importante: A E-Commer NÃO se reponsabiliza pela má instalação do produto. Para evitar transtornos, procure sempre um profissional especializado.', 189.0, 189.0, NULL, 'Home Appliances > Projectors & Accessories > Pointers', 'https://cf.shopee.com.br/file/f2d003d090e5a701c73236807d036d80', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F325589565%2F4960915997', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57706271921', 'Kit 10 Bandeja Para Gatos Caixa de Areia para Gatos Pá Higiênica Comedouro bebedouro Para Gatos', 'Bem vindos a PET CHARM! KIT COM 10 UNIDADES DE KIT PARA GATO COM; 1 BANDEJA 1 COMEDOURO 1 BEBEDOURO E 1 PÁ HIGIÊNICA Bandeja com um plástico de excelente qualidade!! Medidas da bandeja; Comprimento> 47cm Largura > 31cm Altura > 9cm Medidas do comedouro/bebedouro 150ml; 12cm de diâmetro 3c,m de altura Medidas da pá higiênica 25cm de comprimento 10cm de largura', 139.9, 119.9, NULL, 'Pets > Litter & Toilet > Cat Litter & Boxes', 'https://cf.shopee.com.br/file/sg-11134201-825zv-mkv82jx4rlza65', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F908280603%2F57706271921', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29837120002', 'ALISANTE HENÊ RENÁ PRETO AZULADO POUCH EMBELLEZE 180G', 'Alisante Henê Gel Rená Preto Azulado Pouch 180g Embelleze - 1 Unidade O Henê Rená Preto Azulado foi feito para quem ama cabelo liso e preto e sonha com um efeito duradouro e natural. Ele transforma os seus cabelos progressivamente, garantindo maciez e um balanço de dar inveja. A sua fórmula, além do poder de alisamento e da força do jaborandi, traz a hidratação do karité, para dar muito mais brilho aos fios. Sua nova e exclusiva fragrância vai deixar seu liso mais perfumado e você ainda mais confiante. E então, preparada para os elogios? Benefícios: Nutrição e megabrilho. Solução definitiva. Toque aveludado e embalagem mais prática. Dê adeus à chapinha, escova e secador. * Como Aplicar: 1 - Aplique o Henê gel Rená, mecha por mecha. 2 - Puxe com pente fino, da raiz às pontas, esticando bem os fios. Cubra com uma touca plástica por 60 minutos (o efeito será o mesmo se o tempo for maior). 3 - Enxágue bem os cabelos e lave-os com shampoo e condicione. 4 - Se você quer um efeito bem liso, pode fazer uma escova. E se você quer um penteado ondulado, é só deixar os cabelos secarem em bobs. 5 - Aconselhamos 2 aplicações por semana até atingir o resultado desejado. Retoque: Ao fim do alisamento, que varia de acordo com o tipo de cabelo e o resultado desejado, faça apenas o retoque na raiz de 15 em 15 dias, evitando levar o Henê Rená para as pontas. Precauções: Este produto é incompatível com qualquer outro tipo de relaxante, alisante, colorações à base de amônia e descolorantes. Se você deseja usar estes produtos, deve esperar 6 meses, cortar todo cabelo tratado com Rená e aplicar somente na parte crescida e virgem do cabelo. Se você coloriu, descoloriu ou usou outro tipo de alisante, aguarde 30 dias antes de aplicar o Henê Gel Rená. Não é recomendado para gestante. Antes de aplicar faça o Teste de Mecha Separe uma mecha no alto da cabeça, aplique o Henê conforme indicação, com auxílio de um pente plástico. Penteie a mecha levando o produto nos fios até as pontas, preservando meio centímetro da raiz. Deixe agir por uma hora penteando a cada cinco minutos verificando se os fios estão resistentes e sem danificações. Após o tempo de pausa, enxágue completamente todo o Henê dos fios, lave com shampoo, condicione e finalize como de costume. Caso os fios apresentem sensibilidades, quebra, ruptura, durante o Teste de Mecha, interrompa imediatamente a aplicação. Faça repetidas reconstruções e depois de um mês repita o Teste de Mecha. Resultado: Cabelão liso escorrido, preto e com brilho pra lacrar!', 19.9, 19.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rau3-mafhvvj993w339', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290598330%2F29837120002', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
