INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13974314690', 'Barra de Proteína BOLD Snacks Trufa de Chocolate (20g de Proteína) - Caixa com 12 unidades', 'Caixa de barra de proteína BOLD sabor Trufa de Chocolate, a combinação perfeita para o lanche. Tem cobertura irresistível de chocolate branco com recheio leve e macio de chocolate preto e caramelo. Cabe na bolsa, prático para comer, salva em todo momento! Contém 12 unidades de barrinhas proteicas. Produto zero açúcar adicionado, fonte de fibras e sem glúten, com 20g de proteína. Com a correria do dia a dia, nem todas as pessoas têm tempo ou acham prático consumir ovos, leite ou whey para bater sua meta de proteína diária. Pensando nisso, a BOLD traz uma solução prática e deliciosa. Nossas barras de proteína possuem uma textura macia e um recheio generoso que satisfazem sua vontade de comer um doce, sem a culpa dos açúcares e calorias não funcionais. Cada barra é ideal para quem pratica atividades físicas e busca energia e recuperação muscular. Leve sua BOLD para qualquer lugar: no trabalho, na academia, em viagens ou até mesmo em casa, e tenha sempre um snack nutritivo à mão. Para garantir a qualidade dos nossos produtos, compre exclusivamente na nossa Loja Oficial. Assim, você terá a certeza de receber barras de alta qualidade e originais. Experimente colocar sua BOLD por 15 segundos no micro-ondas para uma experiência ainda mais deliciosa! Especificações Técnicas: Você pode encontrar todas as informações sobre os ingredientes e a tabela nutricional de cada sabor nas imagens do anúncio. Qualquer dúvida, estamos à disposição pelo canal de atendimento da plataforma.', 200.0, 168.0, NULL, 'Food & Beverages > Breakfast Cereals & Spread > Breakfast Bar', 'https://cf.shopee.com.br/file/sg-11134201-7rdw7-lypdy0snqu5k01', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F662247567%2F13974314690', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
