INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18361906700', 'Filtro Óleo Ford F1000 2.5 4.9 96 A 98 Tecfil', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. >Aplicação F-1000 LIGHTNING/ SUPER 4.9I 1998 F-1000 REGULAR CAB. 4.9I 1997 até 1998 F-1000 TROPICAL CD 4.9I 1996 até 1998 F-1000 TROPICAL SL/ VAN 4.9I 1996 até 1998 F-1000 XL 2.5 HSD DIESEL TB 1996 até 1998 F-1000 XLT 2.5 HSD DIESEL TB 1996 até 1998 Conteúdo Da Embalagem 1 Filtro de Óleo Tipo de Veículo para SUV''s e Caminhonetes Marca Especialista no segmento de Filtros Automotivos a Tecfil foi fundada em 1953, e atualmente é a maior fábrica de filtros da América Latina, além de ser a líder e maior referência do mercado no segmento de reposição automotiva. A empresa possui ainda todas as Certificações exigidas no mercado, o que lhe confere diferenciais de qualidade. O Produto Com a finalidade de remover os resíduos indesejáveis que podem estar contidos no óleo do motor, o Filtro de Óleo é feito com um papel especial, que está contido dentro da carcaça do filtro. O óleo sujo pode causar entupimento do motor podendo causar até a fundição do mesmo. Importante • Tempo de garantia - 3 meses. • Imagem meramente ilustrativa. • Valor Unitário. • Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078. EAN 7891342000635 Código do Fabricante PSL902 >', 26.39, 26.39, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rbkx-llwahiwsq0qzd8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F18361906700', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
