INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22022188069', 'Esmalte Risque Escolha A Sua Cor Unitário Manicure 3 Coleção Tradicional e Metaverso', 'Esmaltes Risqué, escolha sua cor! Os esmaltes Risqué possuem secagem rápida e com ultra brilho, além de ter longa duração nas unhas. Sua fórmula é hipoalergênica, isto é, livre de componentes que costumam causar alergias e seu pincel proporciona aplicação perfeita e alta cobertura. Toda a linha de esmaltes Risqué apresenta textura única, cores elegantes e acompanha as tendências da moda, possibilitando diversas composições de looks e maximizando a beleza da sua maquiagem e acessórios. Apaixone-se pela cor, presencie a longa duração e viva a beleza de suas unhas de forma única com os Esmaltes Risqué Inspirado no metaverso e nas possibilidades de experimentar muitas versões de si no mundo virtual, a coleção Nosso metaverso possui uma textura cremosa. Possui alta durabilidade e cobertura, secagem rápida e fórmula hipoalergênica, livres de substâncias que podem causar alergias. Aproveite! Inspire-se no mundo virtual para colorir a vida real.', 17.61, 17.61, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lkqytdhklqjc20', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F385388689%2F22022188069', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
