INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251440321', 'Puzzle 1000 Peças Nas Montanhas da Áustria Ravensburger 12000649', 'Puzzle Importado Fabricante: Ravensburger Condição: NOVO/ LACRADO Quantidade de peças: 1000 peças Dimensões do puzzle montado: 70 X 50 cm Diversificação. É isso que sempre buscamos oferecer para os amantes de puzzles. Diferentes imagens, tamanhos e temas para proporcionar diferentes experiências. E é pensando nisso que trouxemos para o Brasil uma coleção de Puzzles de uma das marcas mais reconhecidas do mundo, a RAVENSBURGER, empresa especializada no desenvolvimento de puzzles. Mais que um passatempo divertido, os quebra-cabeças desenvolvem o raciocínio, relaxam e se transformam num autêntico hobby.', 214.99, 214.99, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/sg-11134201-8227g-mhtivt9fmt4ye3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F545750185%2F58251440321', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
