INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9671949839', 'Silicone Spray Perfumado Centralsul America 400ml', 'SILICONE SPRAY perfumado VANTAGENS Proteção UV. Penetra e trata as superfícies do veículo, recuperando o brilho e a beleza original do painel deixando um agradável perfume dentro do veículo, sendo o produto ideal para proteger, conservar e dar brilho. O seu formato em aerossol proporciona uma melhor cobertura e mais facilidade na aplicação. APLICAÇÕES Pode ser utilizado em superfícies de borracha, vinil, plástico, madeira e outras superfícies de painéis, frisos laterais, console, pneus e para-choques. Pode ser usado em móveis de madeira. CUIDADOS Deve-se evitar o contato do produto com vidros automotivos. Evitar ser aplicado em pisos, pedais e estofados de couro a fim de evitar uma ação derrapante. MODO DE USAR Limpa-se a superfície e aplica-se o Destaque Silicone Perfumado a uma distância de 20 cm, para que fique uniforme. Após à aplicação, dar acabamento com pano de microfibra limpa e seca', 39.99, 39.99, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-22100-lwgcacpzmwiv54', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F414229824%2F9671949839', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
