INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23494306068', 'Kit Para Banheiro Rio com 5 Peças em ABS Cromado Higiban', '***PRODUTO A PRONTO ENTREGA COM ENVIO IMEDIATO*** ITEM ORIGINAL COM NOTA FISCAL Somos a Domus, Loja oficial da Shopee. Temos 5 anos de experiência em E-Commerce e nosso maior objetivo é garantir a satisfação dos nossos clientes! Kit para Banheiro Rio com 5 Peças em ABS Cromado – Higiban | Organização e elegância para seu ambiente. O Kit para Banheiro Rio da Higiban traz praticidade, resistência e um toque sofisticado para seu banheiro. Produzido em ABS com acabamento cromado, oferece alta durabilidade, fácil limpeza e visual moderno. Ideal para quem busca funcionalidade sem abrir mão da estética, o conjunto inclui 5 peças essenciais para manter o ambiente organizado e elegante. Destaques do produto: Conjunto com 5 peças para completa organização do banheiro Material em ABS com acabamento cromado, garantindo durabilidade e design moderno Fácil instalação, com fixação segura e prática Resistente à umidade, ideal para uso diário em banheiros residenciais ou comerciais Informações técnicas: Marca: Higiban Modelo: Linha Rio Material: ABS com acabamento cromado Quantidade de peças: 5 Peças inclusas: Porta-toalha barra, porta-toalha argola, saboneteira, papeleira e cabide simples Cor: Cromado Conteúdo da embalagem: 1 Porta-toalha barra 1 Porta-toalha argola 1 Saboneteira 1 Papeleira 1 Cabide simples Parafusos e buchas para fixação Produto original com garantia Garantia de 3 meses. Transforme seu banheiro com praticidade e estilo. Adquira já seu kit Higiban!', 61.9, 61.9, NULL, 'Home & Living > Bathrooms > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdw0-mdauhymwd8fa33', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F445163047%2F23494306068', NULL, NULL, '2026-07-28T02: