INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23523126880', 'Limpador Interno Bactericida Sintra Fast 500ML Vonixx', 'Limpador Interno Bactericida Sintra Fast 500ML Vonixx PRONTO PARA USO Sintra Fast é um multilimpador flotador universal bactericida e germicida para limpeza de painéis, laterais, cantos de portas, bancadas de couro, carpetes e estofados no interior do carro. Ele remove manchas de gordura e sujeiras, além de eliminar microrganismos e diminuir maus odores. //Modo de uso// Pulverizar o produto na superfície a ser limpa, utilizar pincel, escova ou aplicador de espuma para fazer movimentos circulares até remover a sujeira, remover o excesso com uma toalha de microfibra úmida e secar com uma toalha de microfibra seca.', 34.39, 34.39, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Shampoo', 'https://cf.shopee.com.br/file/br-11134207-7r98o-luw9z79uts9s74', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F944273111%2F23523126880', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
