INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693125894', 'Troca de Óleo P/ Kawasaki Er6-N / Vulcan 650 / Versys 650 Mobil 10w40 + Filtro', 'Mantenha o motor sempre protegido e com alto desempenho: faça a troca de óleo no tempo certo e garanta mais vida útil para sua moto! Aumente a vida útil de sua moto. Praticando uma manutenção rigorosa do sistema de lubrificação, trocando o óleo e o filtro de óleo regularmente você estará estendendo a vida do motor, evitando desgaste excessivo das partes móveis, aumentando o desempenho e reduzindo o consumo de combustível. Aplicação Ideal Motos Kawasaki ER 6 N VERSYS 650 2016-2020 VULCAN S 650 ABS Conteúdo da Embalagem: 02 Litros de Óleo MOBIL 10W40 Semissintético 01 Filtro de Óleo Código Original (OEM) do Filtro: 15400-PFB-014 / 16097-0002 / 1WD-E3440-00 Especificações Óleo Mobil: - Veículos: Especialmente formulado para veículos flex. - Tipo de motor: 4 Tempos - Viscosidade: 10W-40 - Classificação: Semissintético - Atende ou excede:JASO MA-1, JASO MA-2, API SJ - Número de Registro ANP: 16601 Especificações Técnicas Filtro de Óleo: - Modelo: PH6017A / OC1019 / HF204 / PSL638 - Altura : 75 mm - Diâmetro exterior : 69 mm - Furo roscado : M20x1,5 - Com Oring - Alta Qualidade - Máxima Eficiência - Produto Acompanha Borracha De Vedação Da Tampa Filtro De Óleo A função do filtro de óleo é reter as diversas partículas e impurezas existentes no circuito de lubrificação geradas pelo uso do motor, tais como oxidantes, partículas de metal, poeira e sujeiras. O filtro de óleo proporciona os seguintes benefícios ao seu motor: - Protege o motor; - Prolonga sua vida útil; - Proporciona segurança; - Permite uma lubrificação mais eficaz; - Proporciona melhor rendimento do motor e precisão de funcionamento; - Contribui na economia de combustível; - Contribui para a redução de emissão de poluentes na atmosfera. Importante !! Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto.', 149.9, 134.91, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-824g1-mf1lbw7mntop64', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F22693125894', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
