INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798162947', 'Carabina de Pressão New Jade Oxidada 5.5mm - CBC + Luneta 4x20 + Chumbo + Bipé', 'Carabina de Pressão New Jade Oxidada 5.5mm - CBC A Carabina de Pressão New Jade é a mais silenciosa, precisa e veloz em sua categoria. Modelo fácil de engatilhar com corpo todo produzido em polímero, deixando a arma muito mais leve. Sua coronha é ambidestra com detalhes que proporcionam uma melhor "pegada". Para evitar a oxidação rápida de seu cano, ela possui uma capa/camada protetora ao longo de todo cano. Para acoplar luneta e red dot, essa carabina possui ranhura de 11mm. Possui sistema de cano basculante, tiro à tiro, com carregamento direto no cano. A alça de mira possui regulagem na vertical. E a massa de mira é fixa, protegida por túnel. Ambas são em fibra óptica. Especificações Fabricante: CBC Modelo: Jade New Calibre: 5.5mm(.22) Acabamento: Oxidado Coronha: Polipropileno – Preta Gatilho: Convencional Velocidade (boca) m/s: 137 Velocidade (boca) pés/seg: 450 Energia (boca) joules: 8,5 Força necessária para engatilhar (kg): 8,5 Sistema de Funcionamento: Sistema de engatilhamento por alavanca acionada pelo basculamento do cano Capacidade: Tiro individual de chumbinhos Sistema de Pontaria: Aparelho de pontaria com fibra óptica Alça de mira com regulagem horizontal e vertical Massa de mira fixa protegida por túnel Segurança: Trava ambidestra automática localizada no gatilho Sistema que impede o disparo com o cano aberto Mola: Convencional em Aço Distância máxima do tiro(m): 152 Peso (kg): 2,1kg ATENÇÃO: "O uso do produto exige treinamento e equilíbrio emocional." "Deverá ser guardado em lugar seguro e fora do alcance de terceiros."', 1100.9, 825.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/sg-11134201-7ra0w-m54ht3vbnmww83', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F335160199%2F22798162947', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20306239109', 'Linha Monofilamento Araty Superflex 1/4 LB Verde – Mazzaferro 470mts - 0,50mm', '<u>Linha Monofilamento Araty Superflex 1/4 LB Verde Mazzaferro</u> A linha de pesca mais versátil, utilizada desde pescarias em pesque e pague até nos mais sofisticados torneios. A Linha Monofilamento Araty se adapta bem às condições de água transparente ou turva, doce ou salgada, para utilização em molinetes e carretilhas. <u>Especificações</u> Fabricante: Mazzaferro Modelo: Araty Superflex 1/4 LB Monofilameto Cor: Verde Boa Resistência à tração Flexível Alta maciez Diâmetros regulares', 44.9, 44.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fishing', 'https://cf.shopee.com.br/file/ffea4a87f095df9b81501e727312440e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F335160199%2F20306239109', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
