INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22794949592', 'Filé de Tilápia Bom Peixe', 'O filé de tilápia da Bom Peixe é uma excelente opção para quem busca uma refeição saudável e saborosa. Fonte de proteínas e com baixo teor de gordura, a tilápia é um peixe versátil que pode ser preparado de diversas maneiras. Experimente grelhado, assado, frito ou cozido. Harmoniza bem com saladas, legumes e acompanhamentos de sua preferência. Para um toque especial, tempere com limão, alho e ervas frescas.', 36.99, 36.99, NULL, 'Food & Beverages > Fresh & Frozen Food > Seafood', 'https://cf.shopee.com.br/file/sg-11134201-81zud-miyqb455lzif18', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554958%2F22794949592', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
