INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15846684993', 'Esmerilhadeira Angular 4.1/2 110v 720w Makita Ga4530 127v', 'PRODUTO NÃO RECOMENDADO PARA LIXAR PAREDE ! PRODUTO PARA DESBASTE E CORTE EM MATERIAIS METÁLICOS. A Esmerilhadeira angular 4.1/2" GA4530 da Makita possui estrutura de pequena circunferência e punho lateral ergonômico para fácil manuseio. Com potente motor de 720 watts e rotação 11.000 rpm a Esmerilhadeira da Makita utiliza disco de 115 mm e acompanha punho lateral e flange. Além de possuir construção em labirinto protegendo o motor e os rolamentos de poeira e resíduos, conta com motor de alta qualidade com elevada resistência ao calor, a caixa de engrenagens pequena proporciona fácil manuseio e elevada manobrabilidade, seu estator é protegido com verniz especial que impede a entrada de poeira. Ideal para profissionais da área automotiva, metal mecânica! CARACTERÍSTICAS: Dupla isolação. Gatilho deslizante. ESPECIFICAÇÕES: Potência: 720W; Tensão: 110V; Diâmetro do Disco: 115,0mm; Rotações por min.: 11.000rpm; Dimensões (C x L x A): 266,0 x 128,0 x 103,0mm; Peso: 1,800Kg; Emissão de vibrações: 7.5 m/s²; Incerteza K: 1.5m/s². ITENS QUE ACOMPANHAM: Flange, chave de pino e punho lateral.', 521.0, 495.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/fd1f1828b13e9a813d879379c3e5a364', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380456261%2F15846684993', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
